/* chronicle data chunk: cn-15 | 1912–1948 | 拆分自 cn-09，切点 1912 年，逐行原文照搬 | 生成于 2026-09-21 */
window.__CHRONICLE_CHUNK = window.__CHRONICLE_CHUNK || {};
window.__CHRONICLE_CHUNK["cn-15"] = [
  { id: "cn--1912--p01", track: "cn", year: 1912, yearApprox: false, dim: "politics", weight: 5, title: "中华民国临时政府之成", summary: "元年元旦，孙文受任于南京。", detail: { background: "各省代表之会已定临时政府之格，南京既为诸军所克而空缺未有人，各省之电推交驰，孙文自海外归至上海。", process: "1911年12月29日各省代表会议选举孙文为临时大总统，1912年1月1日孙文就任于南京，以是日为中华民国元年元旦（是日于黄帝纪元为四千六百九年十一月十三日），宣言以推翻专制、建设共和、巩固国内和平、主张国际平等为务，政府改用阳历，旋命部、院各设其长。", impact: "自是亚洲之共和国以其文告与纪元告于天下，各省之印文、学堂之教科书与商民之历书渐为之一变；而临时政府之军与财皆绌，外不能得各国之承认，内不能制各都督之擅权，其所以速让者在此，其所以能立者亦在各省之响。", figures: ["孙文","黄兴","宋教仁","伍廷芳"], place: "江苏南京", state: "中华民国", sources: ["《临时大总统就职宣言》，见《孙中山全集》第二卷","《（民国）政府公报》","《民立报》1912年原载"], tags: ["临时政府","民国元年","孙文"] }, related: ["cn--1911--i01", "cn--1912--p02"] },
  { id: "cn--1912--p02", track: "cn", year: 1912, yearApprox: false, dim: "politics", weight: 5, title: "清帝退位之诏", summary: "宣统三年十二月，两宫以天下为让。", detail: { background: "南北之议开于上海，伍廷芳与唐绍仪往复电文，而北洋诸将联名请定共和，宗社之谋与亲贵之走迭出，清室之款与优待之条为所争者。", process: "1912年2月12日（宣统三年十二月二十五日）以内廷名义下退位之诏，以统治之权公之于全国，定共和之立宪政体，同时公布《清室优待条件》八条、皇室王公宗族与满蒙回藏待遇之条件，皇帝之尊号不废，居宫苑、岁用四百万元，另定辞位以后之礼制，逊位之诏以摄政王与隆裕太后之名义行之。", impact: "一朝之禅代以条件而结，二千年之帝制自是告尽，而宫禁之内仍留其号与其人，此1924年之变与复辟之议所由生；优待条件之执行与岁费之拨，民国历年为之争论，论近代中国之转型者以逊清之局为其最重要之未了之案。", figures: ["溥仪","隆裕太后","袁世凯","赵秉钧"], place: "京师", state: "清、中华民国", sources: ["《清帝退位诏书》与《清室优待条件》（1912年2月12日），见中国近代史资料丛刊《辛亥革命》","《（民国）政府公报》","《民立报》1912年原载"], tags: ["清帝退位","优待条件","共和"] }, related: ["cn--1912--p01", "cn--1912--p03"] },
  { id: "cn--1912--p03", track: "cn", year: 1912, yearApprox: false, dim: "politics", weight: 4, title: "临时大总统之交与政府北迁", summary: "让位之约既成，袁氏任于北京。", detail: { background: "孙文以不使外国干涉、不启内战为让位之条件，须定都南京与新总统来南京就职二事，而北洋之军与各省之财政皆不在临时政府之手。", process: "1912年2月13日孙文向参议院辞职并荐袁世凯，15日参议院选举袁为临时大总统，2月29日曹锟之兵变于北京，袁以北方不可不动辞其南下，3月10日袁世凯在北京就临时大总统之职，11日唐绍仪为国务总理并组阁，4月临时政府北迁，南京留守之府旋以兵变撤。", impact: "政府之中心自是移于北，临时之约法与责任内阁之说徒为文字之格，唐绍仪之去、陆征祥组阁之受阻皆以是起；论民国初年政治之失其机会者，多以南、北京之间此数月中形势已定为其断。", figures: ["孙文","袁世凯","唐绍仪","蔡元培"], place: "南京、北京", state: "中华民国", sources: ["《（民国）参议院议决案汇编》","《（民国）政府公报》","郭廷以《近代中国史纲》"], tags: ["让位","北迁","唐绍仪内阁"] }, related: ["cn--1912--p02", "cn--1912--i01"] },
  { id: "cn--1912--i01", track: "cn", year: 1912, yearApprox: false, dim: "institution", weight: 4, title: "临时约法之公布", summary: "以主权在民与内阁之责约新政府。", detail: { background: "组织大纲取总统之制，而袁氏且来，参议院中多以改定约法为防制之术，起草者数易而后定。", process: "1912年3月8日参议院议决、11日公布《中华民国临时约法》凡七章五十有六条，主权属于国民全体，以参议院、临时大总统、国务员、法院行其统治之权，设国务总理与各部总长辅总统，特设法院，并列举人民之自由与权利，其增约法之权属之参议院。", impact: "此约法为共和政体之第一部临时宪法，其所以改总统制为内阁制者在于一人，然既为成文之根本法，此后约法存废与恢复遂为历次政争之口（1916、1917、1922三次恢复之约法），而国会之闭与宪法之争皆以是为其讼端。", figures: ["宋教仁","汪荣宝","张耀曾"], place: "南京、北京", state: "中华民国", sources: ["《中华民国临时约法》条文（1912年3月11日公布），见《（民国）法规汇编》","《（民国）参议院议决案汇编》","《民立报》1912年原载"], tags: ["临时约法","主权在民","内阁制"] }, related: ["cn--1911--i01", "cn--1913--i01"] },
  { id: "cn--1912--i02", track: "cn", year: 1912, yearApprox: false, dim: "institution", weight: 3, title: "同盟会改组与政党之立", summary: "秘密之会改为公开之党。", detail: { background: "共和既成，党人之在政府、议会与报馆者各执其途，秘密结社之格不复可用，统一、民社诸党并出以争议院之席。", process: "1912年春同盟会在南京开会议改组，8月北京之统一共和党、国民公党诸小会与同盟会合并为国民党，孙、黄任理事，宋教仁主其党务于议会，以政党内阁与议会多数为指；同时立宪旧人改为共和党、民主党，三党相竞于参、众两院之选举。", impact: "政党政治自是试行，选举之法于各省并举，国民党果于1913年得两院之多数，而此制之坏亦即在是年之刺案与解散；论民国初年之议会政治者，以1912、1913两年为其全部之试验，亦为其全部之结局。", figures: ["宋教仁","孙文","黄兴","黎元洪"], place: "南京、北京", state: "中华民国", sources: ["《国民党宣言》，见中国近代史资料丛刊《辛亥革命》","《宋教仁集》","《民立报》1912年原载"], tags: ["国民党","政党政治","改组"] }, related: ["cn--1913--p01", "cn--1912--i03"] },
  { id: "cn--1912--i03", track: "cn", year: 1912, yearApprox: false, dim: "institution", weight: 3, title: "壬子癸丑之学制与废读经", summary: "学校之系统一新，小学不读经。", detail: { background: "临时政府以教育为改政之最先，蔡元培长教育，延旧学之彦与新进之博士会同订定，谓当去忠君、尊孔之旨而养公民之德。", process: "1912年9月至1913年蔡元培主持订《学校系统令》与各校令（壬子癸丑学制），蒙学、小学、中学、大学之年限更定，初小四年为义务教育之目，师范与实业两途别为一系统，小学废止读经，女子与男子同校之格始立，1915年后又有修正案之改。", impact: "自是学堂之名与科举之遗尽改，教科书之编与国语之定皆循此格，商务、中华两书局以是有全国之市场；而废经一议在士绅中积怨甚深，1915年之尊孔、1925年之读经争论皆余波，论教育之近代化者以两三年间数令为其枢纽。", figures: ["蔡元培","蒋维乔"], place: "南京、北京", state: "中华民国", sources: ["《教育部公布学校系统令》原文，载《（民国）政府公报》","《蔡元培全集》","舒新城编《近代中国留学史》"], tags: ["壬子癸丑学制","废读经","教育部"] }, related: ["cn--1912--i02", "cn--1915--c01"] },
  { id: "cn--1912--e01", track: "cn", year: 1912, yearApprox: false, dim: "economy", weight: 2, title: "民国初年之公司热", summary: "一二年之间新厂与新号骤多。", detail: { background: "帝制既去，商民以实业可以救国相倡，政府设矿政、注册之章，商会与报馆推波其间。", process: "1912年至1913年间，新立之工厂、矿务、纺织、面粉与银行、信托之号以千计（农商部注册之数与报馆所记出入较大），其中集股不实、投机而倒者亦十居其半，沪、汉、津之市因之大起大落，至1913年二次革命之起而停滞。", impact: "公司之设与股票之市自是为民国常经之局，1910年橡皮风潮之余痛未忘而又一潮；论民族工业者每以此数年为上厂之始基，至欧战起而入口之货顿减，此数年所立之厂遂为1914至1920年之利源。", figures: ["张謇","周学熙"], place: "上海、汉口、天津", state: "中华民国", sources: ["《（民国）农商公报》所载注册统计","《时报》1912—1913年原载","《张謇全集》"], tags: ["公司","实业","注册"] }, related: ["cn--1914--e01", "cn--1910--e01"] },
  { id: "cn--1912--c01", track: "cn", year: 1912, yearApprox: false, dim: "culture", weight: 2, title: "报馆与学会之盛", summary: "言论之会遍于都市，报馆日增。", detail: { background: "约法以言论、出版、结社自由为文，党争与外交之案并至，报与社互为有无，上海、北京、天津为最多。", process: "1912、1913两年间，全国之日报与周刊之数骤增（各书所记多寡不一），报馆多附于党派，黄远生、邵飘萍以通讯之体名于世，学会、新闻学之研究与编译社并起，商务、中华两大书局以学校用书之代订而成巨业。", impact: "自是报馆为政治上不可去之一物，袁氏既忌之，1913年后查封与报人之祸相继，而报馆亦自是学会社、结联为一江湖；论民国言论之环境者以二年为最宽，此后之渐紧即由是而起。", figures: ["黄远生","邵飘萍","张謇"], place: "上海、北京、天津", state: "中华民国", sources: ["戈公振《中国报学史》","《黄远生遗著》","《民立报》1912—1913年原载"], tags: ["报馆","言论","新闻"] }, related: ["cn--1913--p01", "cn--1912--i02"] },
  { id: "cn--1913--p01", track: "cn", year: 1913, yearApprox: false, dim: "politics", weight: 4, title: "宋教仁之狱", summary: "北站三弹，国会之望随之而裂。", detail: { background: "国民党在两院得多数，宋教仁以政党内阁、责任之政府遍游东南演说，政府与党人之隙日见，赵秉钧之国务院与应夔丞之交通处尚有往来之电。", process: "1913年3月20夜宋教仁与黄兴、廖仲恺等将登北列车于上海北站，被枪伤，22日死，年三十一；应夔丞、洪述祖先后就逮，应宅所获之密电、凭证与汇款之单，沪上各报录而出之，其真伪与牵及何人，诉讼与后来研究之说不一。", impact: "一案而南方信其出于政府、北方疑其激成党乱，议会之望与法律之争同时失其可靠，孙文主速起兵而黄兴、国民党诸人多持法律，此后之两途即在此月定之；论民国政党政治之终者多以3月22日为结束之期。", figures: ["宋教仁","赵秉钧","应夔丞","洪述祖"], place: "上海北站、北京", state: "中华民国", sources: ["《民立报》1913年原载","《宋教仁集》","郭廷以《近代中国史纲》"], tags: ["宋案","政党政治","上海"] }, related: ["cn--1913--p02", "cn--1912--i02"] },
  { id: "cn--1913--p02", track: "cn", year: 1913, yearApprox: false, dim: "politics", weight: 4, title: "癸丑之役（二次革命）", summary: "湖口一纸文电，数省旋起旋仆。", detail: { background: "善后借款以未经国会同意为党人所攻，赣、闽、粤、湘之都督多由国民党任之，政府先后免其职，兵为备而饷不足。", process: "1913年7月12日李烈钧自江西湖口宣布独立，黄兴旋入南京任讨袁军总司令，15日程德全宣布江苏独立，安徽、上海、广东、福建、重庆、湖南相继响应，号曰二次革命；北洋之军由津浦、京汉两路而南，8月陷南昌，9月12日南京不守，黄兴、李烈钧走海外，孙文旋亦去国，两军之死伤与军用之费，各方册报多寡不一。", impact: "民党之有兵者尽，国民党于11月4日被解散，国会因不足人数而无形停止，江西、江苏之地方财政与兵事自此归于北洋系之督军；论者谓共和之试验以一战而终，其遗迹仅存于约法与国会之名。", figures: ["李烈钧","黄兴","孙文","柏文蔚"], place: "江西湖口、南京、长沙、广州", state: "中华民国", sources: ["《（民国）政府公报》所载免职与任令","《申报》1913年原载","郭廷以《近代中国史纲》"], tags: ["二次革命","癸丑","北洋南下"] }, related: ["cn--1913--p01", "cn--1913--e01"] },
  { id: "cn--1913--e01", track: "cn", year: 1913, yearApprox: false, dim: "economy", weight: 4, title: "善后大借款之约", summary: "两千五百万镑不经议院而订。", detail: { background: "临时政府以来之军费与赔款、行政之费皆仰于垫借，五国银行团自1912年冬开议，以盐税稽核与用人之权为条件，政府以国会且开而欲先成之。", process: "1913年4月26日国务总理赵秉钧、外交总长陆征祥以电令行事，与英、法、德、俄、日五国银行团签订善后借款合同，二千五百万镑、五厘、四十七年，以全国盐税为抵，设盐务稽核所于京师而用西人为会办，各省分所如之；参议院以未付议决为不当，众议院有弹劾之案，而款已交用，不能返也。", impact: "盐税自是外人得而稽核之，北京政府之财政以盐余为活，各省之截留与稽核所之争执遂为历年之交涉案；而此款实多数用于军费，南北之战以是速决，论民国财政之依附外人者以此为最大关键。", figures: ["赵秉钧","陆征祥","梁士诒"], place: "北京", state: "中华民国", sources: ["《改善中国财政借款合同》即善后大借款合同，见王铁崖编《中外旧约章汇编》","《（民国）政府公报》","郭廷以《近代中国史纲》"], tags: ["善后借款","盐税","五国银行团"] }, related: ["cn--1913--p02", "cn--1913--i01"] },
  { id: "cn--1913--i01", track: "cn", year: 1913, yearApprox: false, dim: "institution", weight: 3, title: "国会之开与正式大总统之选", summary: "四月开幕，十月选举，宪法未成而先选总统。", detail: { background: "临时约法以国会召集之期与宪法之成相系，而政府与党人争其先后，各省之选举事竣，两院之议员集于北京。", process: "1913年4月8日第一届国会开幕于北京，旋设宪法起草委员会于天坛；10月4日宪法未成而先选总统之案通过，6日两院开会选举，至第三次投票而袁世凯得当选之额，10月10日举行就职之礼；国会之被逼先选总统，其被围与投票之情形，报章所载与后来记述互有出入。", impact: "选在宪法之先，约法之所定者自是失其序，国民党议员虽多而无力拒之，未及一月而党除名、院停止；论民国议会政治之失败者，以10月6日之投票为最可注意之一日，此后国会两度恢复而皆不能自主其会议。", figures: ["袁世凯","汤化龙","张耀曾","吴景濂"], place: "北京", state: "中华民国", sources: ["《（民国）国会会议录》与《政府公报》","郭廷以《近代中国史纲》","《申报》1913年原载"], tags: ["第一届国会","天坛宪草","正式大总统"] }, related: ["cn--1912--i01", "cn--1914--p02"] },
  { id: "cn--1913--p03", track: "cn", year: 1913, yearApprox: false, dim: "politics", weight: 3, title: "西姆拉之会", summary: "英、中、藏三方会于印北，界案未了。", detail: { background: "拉萨之役以后，藏中之局久为英、俄所注，辛亥之秋藏地与川军相持，英请以三方会议而议藏政与商埠之界。", process: "1913年秋英、中国、西藏三方会议于印度之西姆拉，中国专使为陈贻范，英以英属印度之官为主席；会议以藏政之隶属与外、内藏之划分为议，1914年夏草约将签而藏方另与英人换文划定东北之界（后来所谓麦克马洪线之起），北京政府以未奉允准而电令专使勿签，草约遂不呈批。", impact: "西姆拉之约不成而界之换文长留为交涉之案，此后历次藏案皆以1914年之线为争论之端；会议以中国为一方而许西藏另为一主，论者谓此语之入于文牍，为后来主权与宗主权之争所自出。", figures: ["陈贻范"], place: "印度西姆拉", state: "中华民国、英国、西藏地方", sources: ["李剑农《近代中国外交史资料辑要》中卷","《（民国）政府公报》所载外部文电","郭廷以《近代中国史纲》"], tags: ["西姆拉","藏案","界务"] }, related: ["cn--1904--p02", "cn--1913--i01"] },
  { id: "cn--1914--p01", track: "cn", year: 1914, yearApprox: false, dim: "politics", weight: 3, title: "欧战之起与中国之中立", summary: "欧罗巴构兵，北京宣布局外中立。", detail: { background: "奥、塞之衅起于6月，7月底各国相继动员、宣战，英、法、俄与德、奥、意各为敌，远东之租界与铁路顿成关系之地。", process: "1914年8月6日大总统布告宣布局外中立，旋划胶州湾与莱州一带为战区，许交战国兵行其间；先此日本已照会德国索取胶州湾之让与，8月15日日本下最后通牒，中国政府以日本为盟友之情面而不能执问，中立区域之被侵者累电辩诘而止于文牍。", impact: "以中立之国而见战于其领土，此与1904年之局相类而其势异，欧战四年之间中国之出口、汇价与海关皆受其影响，1917年对德宣战之议即伏于此三年之中；论参战与欧战后期之机，皆以中立之时之不能自主为其因。", figures: ["曹汝霖","陆征祥"], place: "北京、胶州", state: "中华民国", sources: ["《（民国）政府公报》所载大总统布告","李剑农《近代中国外交史资料辑要》中卷","《申报》1914年原载"], tags: ["欧战","中立","胶州"] }, related: ["cn--1914--m01", "cn--1917--p03"] },
  { id: "cn--1914--p02", track: "cn", year: 1914, yearApprox: false, dim: "politics", weight: 3, title: "国会之停止与约法会议", summary: "议员之证追缴，别设会议以改约法。", detail: { background: "宋案与借款之狱既起，国民党议员之在院者多被指，癸丑之役败后，政府以除籍、发证为手段。", process: "1913年11月4日以总统命令解散国民党并追缴两院该党议员之证书，院以不足法定人数不能开会；1914年1月10日通令停止两院议员之职务，国会遂无形消灭，3月设约法会议于北京，以议订《中华民国约法》为事，5月1日公布新约法。", impact: "临时约法与国会同为具文，总统之权大增而立法之任归于一会，1915年之推戴与1916年之约法恢复之争皆由此出；论民国以后历次法统之争者，以此为第一次以命令废立法机关，其例既开则后之解散者不复以为异。", figures: ["袁世凯","顾鳌"], place: "北京", state: "中华民国", sources: ["《（民国）政府公报》所载命令","郭廷以《近代中国史纲》","《申报》1914年原载"], tags: ["解散国民党","国会停止","法统"] }, related: ["cn--1913--i01", "cn--1914--i01"] },
  { id: "cn--1914--i01", track: "cn", year: 1914, yearApprox: false, dim: "institution", weight: 3, title: "中华民国约法之成", summary: "五条改为总统一制，政事堂代内阁。", detail: { background: "约法会议之组织以政府所派与各省所举合，其议旨在改临时约法之内阁制为总统制，以收摄权之实。", process: "1914年5月1日公布《中华民国约法》，改国务院为政事堂而置国务卿，总统总揽统治之权、得制定官制、任免官吏、宣战媾和、发布与条约同意之命令，另设法院而其制未备。1914年12月更订大总统选举法，许大总统推荐继任者三人，藏于金匮。", impact: "约法之改而以一人为之枢纽，1915年之帝制即由此涂，袁氏既死，1916年之恢复临时约法与1917年之府院之争皆以两约法孰为有效为争之的；论民国宪法史者以此为约法分裂之始。", figures: ["袁世凯","徐世昌"], place: "北京", state: "中华民国", sources: ["《中华民国约法》条文（1914年5月1日公布），载《（民国）政府公报》","郭廷以《近代中国史纲》"], tags: ["袁记约法","政事堂","总统制"] }, related: ["cn--1914--p02", "cn--1916--p02"] },
  { id: "cn--1914--m01", track: "cn", year: 1914, yearApprox: false, dim: "military", weight: 4, title: "青岛之役与日兵登陆", summary: "德岛既下，日人沿路设署而不去。", detail: { background: "胶州湾自1898年为德人所租，欧战起而日本与英为盟，英国请其以舰协攻胶湾，德人拒日本之通牒，日本遂以兵取之。", process: "1914年9月2日以后日兵自龙口、莱州登陆，循而东，10月底合围青岛，11月7日德守军降；是役两军之死伤与华民之被兵，报册与后来所记出入较大，而日兵所过之潍县、济南一带征发供亿皆及于民，青岛既下，日本设民政署于车站与沿线数处。", impact: "德人在山东之权益由是移于日本，而民政署之设与沿路之驻兵为1915年二十一条与以后山东问题之本，1919年之拒签与1922年之解决皆缘此役；论山东案者每谓1914年11月7日为青岛德治之终、亦为日人之始。", figures: ["曹汝霖","加藤友三郎"], place: "山东青岛、龙口、潍县", state: "中华民国、日本、德国", sources: ["《（民国）政府公报》所载关于中立区之文电","李剑农《近代中国外交史资料辑要》中卷","《申报》1914年原载"], tags: ["青岛","日兵登陆","山东"] }, related: ["cn--1914--p01", "cn--1915--p01"] },
  { id: "cn--1914--e01", track: "cn", year: 1914, yearApprox: false, dim: "economy", weight: 4, title: "欧战期间之工业之利", summary: "洋货顿少，纱粉之厂乘时并起。", detail: { background: "欧战起而各国之出口于华者减，洋纱、洋布、面粉、火柴、卷烟之价俱昂，汇兑与银根亦随之而变。", process: "自1914年至1920年间，新设之纺织、面粉、缫丝、火柴、卷烟诸厂为数顿增，注册与资本之额在农商部册报与后来研究之间多有出入，申新、永丰诸公司以是起家，无锡、南通、汕头之纺织与面粉并盛，出口之粉且及于南洋与欧洲。", impact: "此六七年者，论者谓之民族工业之短暂春天，其利在洋货之不至而非在制度之改良，1921年后欧厂复生、日货竞争，纱、粉之利骤薄，多家倒折；机器、工程师与技工之练于此期者，则长留为中国工业之根本。", figures: ["张謇","荣宗敬","周学熙"], place: "上海、无锡、南通、天津", state: "中华民国", sources: ["汪敬虞编《中国近代工业史资料》第二辑","《（民国）农商公报》所载统计","《荣氏公司档案史料选编》"], tags: ["民族工业","欧战","纺织面粉"] }, related: ["cn--1912--e01", "cn--1915--e01"] },
  { id: "cn--1915--p01", track: "cn", year: 1915, yearApprox: false, dim: "politics", weight: 5, title: "二十一条之要求", summary: "五号二十一条，换文而定山东与南满之局。", detail: { background: "日本以参战之劳承德国在山东之利，欧战未结而欲定其远东之约，袁政府方谋帝制，恐外人之掣其肘。", process: "1915年1月18日日本公使日置益面递中国政府五号二十一条，第一号主山东、第二号主南满与东蒙、第三号主汉冶萍、第四号主沿海港湾岛屿不许让与他国、第五号主警察顾问军械借款等事；2月起谈判，5月1日日本提出修正，7日以最后通牒促复，9日中国政府答复，除第五号若干条留作日后协议外，其余照第一、二、三、四号订为条约与换文，8月交换。", impact: "此约成而举国哗然，商会、学生以5月9日为国耻之日，1915年之抵制日货与以后历次之国货运动皆本于此；第五号之留议未成而日本不以是废其谋，1931、1937年之东北与山东诸案，论者皆上原于此五号之约。", figures: ["日置益","陆征祥","曹汝霖","顾维钧"], place: "北京", state: "中华民国、日本", sources: ["《民四条约》与换文，见王铁崖编《中外旧约章汇编》","《申报》1915年原载","郭廷以《近代中国史纲》"], tags: ["二十一条","山东","南满"] }, related: ["cn--1914--m01", "cn--1915--e01"] },
  { id: "cn--1915--c01", track: "cn", year: 1915, yearApprox: false, dim: "culture", weight: 4, title: "《青年杂志》之创刊", summary: "一册以青年与伦理自任，后称《新青年》。", detail: { background: "共和八年而政象日非，一部分读书人以政治之改革不可几及，遂退而主张思想与伦理之变。", process: "1915年9月15日《青年杂志》创刊于上海，陈独秀任编辑，自第二卷起改名《新青年》，发刊之辞以自主、进步、进取诸义相勉，继以驳复古与礼教之文；1917年蔡元培长北京大学，陈独秀、胡适、钱玄同、刘半农诸人遂以杂志与大学讲堂相表里。", impact: "此杂志之盛在1918至1922之间，文学、伦理、政治三事皆由是册而相纠，读者遍于各校；论新文化运动之起点者定于是年九月，而言其影响于以后之思想与政党者亦自是册始。", figures: ["陈独秀","高一涵","易白沙"], place: "上海", state: "中华民国", sources: ["《青年杂志》第一卷原刊","《独秀文存》","《蔡元培全集》"], tags: ["新青年","陈独秀","杂志"] }, related: ["cn--1917--c01", "cn--1915--p02"] },
  { id: "cn--1915--p02", track: "cn", year: 1915, yearApprox: false, dim: "politics", weight: 4, title: "筹安会与国体之议", summary: "六士联名而会成，报章争之。", detail: { background: "欧战之世议及国体者渐多，美国古德诺之论文以中国宜改君主为言，译传于都下，杨度等因之结会。", process: "1915年8月14日杨度、孙毓筠、严复、刘师培、李燮和、胡瑛联名发起筹安会，以研究国体问题为名，通电各省征求同意，各省军政长官与团体相继电请改变国体；梁启超《异哉所谓国体问题者》之文出，报馆争载，政府旋令勿再讨论，9月各省推代表入京组织国民会议以投票决国体。", impact: "以一会而导一国体之变，其所谓公意者多出通电与代表之票，论者谓1915年八月以后之中国，凡政治之动作皆须自命为出自民意，而其意之果否无可考验，此风直至以后之历次投票而不改。", figures: ["杨度","严复","梁启超","古德诺"], place: "北京", state: "中华民国", sources: ["《申报》《晨报》1915年原载","《梁启超年谱长编》","郭廷以《近代中国史纲》"], tags: ["筹安会","国体","古德诺"] }, related: ["cn--1915--p03", "cn--1914--i01"] },
  { id: "cn--1915--p03", track: "cn", year: 1915, yearApprox: false, dim: "politics", weight: 4, title: "洪宪之建与云南之独立", summary: "承认帝位之令下，二十余日而南方举兵。", detail: { background: "国民会议之表决、推戴之牒文既成，内外之反对者在日本之二十一条与本国之心，而袁氏以为帝制可对外无碍。", process: "1915年12月12日以申令承认帝位，以明年为洪宪元年，设典礼处筹备登极之制；25日云南都督唐继尧、蔡锷、李烈钧等电请取消帝制、宣布独立，护国军分途入川、湘，贵州于1月上旬继之，各省之响应虽不多而北洋诸将之不为尽力已见。", impact: "八十三日之帝制自是而终，袁氏之望与北洋之纪纲同坏，段祺瑞之不肯并力、冯国璋诸将之联名通电皆以是月而见，中国之共和名器虽存而中枢之权威自此不复振，论民国军阀之局者多以此为始。", figures: ["袁世凯","蔡锷","唐继尧","段祺瑞"], place: "北京、昆明、贵阳、泸州", state: "中华民国", sources: ["《（民国）政府公报》1915年12月","《蔡锷集》","郭廷以《近代中国史纲》"], tags: ["洪宪","护国","云南独立"] }, related: ["cn--1916--p01", "cn--1915--p02"] },
  { id: "cn--1915--e01", track: "cn", year: 1915, yearApprox: false, dim: "economy", weight: 3, title: "抵制日货与国货之兴", summary: "商民以不购日货为争，国货之名遂立。", detail: { background: "二十一条之约成，日货入口之额方盛，商会、学生与报馆以购与不购为爱国之验，闽、粤一带先有焚日货之举。", process: "1915年二三月以后，上海、广州、汉口、天津诸埠商会决议不用日货、不载日船，日商之货多滞于关，出口之日货数量其年与次年之比较顿减（海关册报与日方统计之差殊极大）；同时华厂之出品以国货为号，劝工之会与国货陈列之所由是遍设于各埠。", impact: "抵货自1905年抵美之后至此为第二次而其效尤著，此后1919、1925、1931诸次皆循其法，商业之道德与外交之手段合为一事；然此风亦使华商之工厂得机会而骤扩，欧战与抵货并至，论者谓1915年后五年之工业即蒙其赐。", figures: ["虞洽卿"], place: "上海、广州、汉口、天津", state: "中华民国", sources: ["海关《十年报告（1912—1921）》","《申报》1915年原载","汪敬虞编《中国近代工业史资料》第二辑"], tags: ["抵制日货","国货","商会"] }, related: ["cn--1915--p01", "cn--1914--e01"] },
  { id: "cn--1916--p01", track: "cn", year: 1916, yearApprox: false, dim: "politics", weight: 3, title: "护国之役", summary: "滇军入川，数省相继宣布独立。", detail: { background: "云南既以上年十二月二十五日宣布独立，护国军以讨袁为名而兵不多，川、湘两路为其所必争，北洋之将帅多不肯出力。", process: "1916年春护国第一军由蔡锷率之入川，与曹锟、张敬尧之军战于泸州、叙州之间，相持数月；贵州于1月27日宣布独立，广西、广东、浙江、陕西、四川、湖南相继应之，先后反正者凡八九省（各省独立之先后与名义，各册多寡不一），袁氏之陆军总长段祺瑞不以全力进取，日本之态度又于其间为左右。", impact: "以护国为名之兵争不赖胜战而赖北洋之解体，自是军政之分立遂成格局，滇、黔、桂之军各为其省所私有，中央之号令不复行于南方；论民国军阀时代之起者，多以1916年三、四、五月之间为其断。", figures: ["蔡锷", "唐继尧", "李烈钧", "段祺瑞"], place: "云南、四川泸州、贵州、广西", state: "中华民国", sources: ["《（民国）政府公报》1916年", "《蔡锷集》", "郭廷以《近代中国史纲》"], tags: ["护国之役", "省独立", "北洋解体"] }, related: ["cn--1916--p02", "cn--1915--p03"] },
  { id: "cn--1916--p02", track: "cn", year: 1916, yearApprox: false, dim: "politics", weight: 5, title: "取消帝制与袁世凯之死", summary: "三个月之洪宪既撤，六月而袁氏殂。", detail: { background: "护国之兵起于南而北洋诸将多不应，江苏、江西等五将军之通电继之，日本与英、俄之态度亦渐显，袁氏之亲信始劝其退让。", process: "1916年3月22日以申令撤回承认帝位之案，去洪宪之号而仍称中华民国五年，其称皇帝者凡三月余，竟未登极；5月8日改总统府为国务院，任段祺瑞为国务卿以缓师，冯国璋主各省取消独立、袁氏退让之议；6月6日袁世凯病死于北京，年五十有七，副总统黎元洪于7日继任大总统。", impact: "一人之死而北洋无主，段祺瑞以国务院承其余而党与自分，西南之省以自主为常，此后之府院之争、约法之争与督军之横皆以是日起；论者谓袁氏之以帝制自覆，适为军阀之局开其门。", figures: ["袁世凯", "黎元洪", "段祺瑞", "冯国璋"], place: "北京", state: "中华民国", sources: ["《（民国）政府公报》1916年6月", "郭廷以《近代中国史纲》", "《申报》1916年原载"], tags: ["取消帝制", "袁世凯之死", "黎元洪继任"] }, related: ["cn--1916--i01", "cn--1916--p01"] },
  { id: "cn--1916--i01", track: "cn", year: 1916, yearApprox: false, dim: "institution", weight: 3, title: "约法与国会之恢复", summary: "临时约法复其旧，两院重集于北京。", detail: { background: "袁氏既殂，南方与国民党之要请以恢复约法、国会为继任之条件，黎元洪以副总统之资格入主，段祺瑞以国务院任其实，二者之界未明也。", process: "1916年6月29日以大总统申令仍照用临时约法，并召集旧国会议决一切未了之案，8月1日国会重开会于北京；宪法会议续筹制宪之议，迁延无成，至1917年6月而国会又解散；国务卿段祺瑞以院令行事，各省督军之任多由北洋系，而黎元洪以总统之名义居府，两府之电报往来自此相争。", impact: "约法既为恢复之文，则一切以约法为准之论得以兴，1917年府院之争即以约法上之权限为其讼本；而国会虽在，不能自制国务院，宪法亦竟未成，论民国宪政之有名无实者，以1916、1917两年为其最明之例。", figures: ["黎元洪", "段祺瑞", "汤化龙"], place: "北京", state: "中华民国", sources: ["《（民国）政府公报》1916年6月", "郭廷以《近代中国史纲》", "《申报》1916年原载"], tags: ["约法恢复", "国会重开", "府院"] }, related: ["cn--1917--p01", "cn--1912--i01"] },
  { id: "cn--1916--f01", track: "cn", year: 1916, yearApprox: false, dim: "figure", weight: 2, title: "蔡锷之死", summary: "护国主将殁于东渡就医之后。", detail: { background: "蔡锷自云南起兵主护国，喉疾已重，川事方定而请以就医东渡，段祺瑞之电召与四川之任交至。", process: "1916年夏蔡锷入日本福冈就医，喉科之治不效，8月辞去四川都督之任，11月8日殁于福冈，年三十四；1917年4月归葬于湖南长沙岳麓山，国会举国葬之礼，各省致祭者相属，梁启超为文表其志，其师说亦由是传。", impact: "蔡锷之死使护国之师失其望重之人，滇、黔之军自是各为其派，四川之局遂为诸督所争；而言论与学界以此一人之殁为共和人才可惜，少年之从军与从学者多以其事自励，1917年以后之讲演与纪念文字往往及之。", figures: ["蔡锷", "梁启超", "唐继尧"], place: "日本福冈、湖南长沙", state: "中华民国", sources: ["《蔡锷集》", "《（民国）政府公报》1916年、1917年", "《梁启超年谱长编》"], tags: ["蔡锷", "护国", "国葬"] }, related: ["cn--1916--p01", "cn--1916--p02"] },
  { id: "cn--1917--p01", track: "cn", year: 1917, yearApprox: false, dim: "politics", weight: 3, title: "府院之争", summary: "总统一府与国务院相持于宣战一案。", detail: { background: "欧战方殷，日本与英、法欲中国与之同进以杜德人之余焰，段祺瑞主之，以参战为名而借日款练兵，黎元洪与国会多持不可。", process: "1917年2月对德绝交之交涉起，国务院与参议院往复数四，5月19日参议院决议宣战案须待内阁改组而后议，督军团乃请愿围院，段祺瑞自请解其责；5月23日以大总统令免段祺瑞本职，段去天津，安徽、浙江、山东、陕西等省之督军团相继宣布独立，府院之势不可复合。", impact: "以约法之文而启两府之争，各省之督军遂得以联合为轻重，此民国政治之新物也；张勋之入京与复辟之变即起于免段令之后，论者谓府院之争为一因，而解决全出于兵，非出于法。", figures: ["黎元洪", "段祺瑞", "冯国璋", "倪嗣冲"], place: "北京、天津", state: "中华民国", sources: ["《（民国）政府公报》1917年5月", "《申报》1917年原载", "郭廷以《近代中国史纲》"], tags: ["府院之争", "宣战案", "督军团"] }, related: ["cn--1916--i01", "cn--1917--p03"] },
  { id: "cn--1917--p02", track: "cn", year: 1917, yearApprox: false, dim: "politics", weight: 3, title: "对德奥宣战", summary: "八月告德，十二月并对奥布告。", detail: { background: "段祺瑞既再任，复辟之变甫定，国会已散而临时参议之会将开，日本与英、法相约为之地，美国于1917年2月与德绝交、4月告德宣战。", process: "1917年8月14日以大总统布告对德国宣战，所有条约关系一时消灭；12月14日并对奥匈布告宣战；旋设参战事务处，练参战军，华工之往欧东者由是续有招募（前后赴欧华工之数，各方统计差异较大）；和议之会且开，中国政府以宣战之故得列席于会中，此段祺瑞与黎元洪两方所同欲者也。", impact: "宣战以加入战团为手段，而所借之款与所练之军皆成日后之争（参战军之费与对日借款之名数，各册记载出入较大），安福国会之立、徐世昌之任皆缘是而起；于对外则为和会之一席与其拒签，1919年巴黎之会中国专使得与，亦以是布告为其张本。", figures: ["段祺瑞", "陆征祥", "曹汝霖"], place: "北京", state: "中华民国", sources: ["《（民国）政府公报》1917年8月、12月", "李剑农《近代中国外交史资料辑要》中卷", "《申报》1917年原载"], tags: ["对德宣战", "参战军", "战胜国"] }, related: ["cn--1919--p01", "cn--1917--p01"] },
  { id: "cn--1917--p03", track: "cn", year: 1917, yearApprox: false, dim: "politics", weight: 4, title: "张勋复辟之役", summary: "辫军入京，十二日而北京见兵。", detail: { background: "府院之争急，黎元洪电召督军入京会议，张勋以辫军自徐州北来，以解散国会为条件，许之，6月入都，6月13日国会解散。", process: "1917年7月1日（农历五月十三）张勋与康有为等奉溥仪复位，易龙旗，颁上谕以设摄政、议政务，改部为府；段祺瑞旋在天津马厂誓师为讨逆军总司令，7月12日兵入北京，宫城之北起交火并有飞机掷弹，张勋避入荷兰使馆，辫军散，复辟凡十二日而败，黎元洪先已电令辞职，冯国璋入代理大总统。", impact: "复辟之败使清室之存废自是成为一问题，而段祺瑞以再造之功再掌国务院，拒旧国会之重开而召集临时参议院，约法之争由是再起；孙中山之护法军政府即以是年秋起于广州；论辫兵、亲贵与民国之关系者，以此十二日为最后一见。", figures: ["张勋", "溥仪", "康有为", "段祺瑞"], place: "北京、徐州、天津马厂", state: "中华民国", sources: ["《（民国）政府公报》1917年7月", "《申报》1917年原载", "郭廷以《近代中国史纲》"], tags: ["张勋复辟", "辫军", "讨逆"] }, related: ["cn--1917--p01", "cn--1917--i01"] },
  { id: "cn--1917--c01", track: "cn", year: 1917, yearApprox: false, dim: "culture", weight: 4, title: "文学革命之议", summary: "以白话代文言，一议起于杂志。", detail: { background: "前清之季严复、林纾之译以雅驯之文言行于士林，而报章之语体自别，学校新定之教科与儿童之读未能相应。", process: "1917年1月《新青年》刊胡适《文学改良刍议》，以不模仿、不忌俗语等八事为说；2月陈独秀《文学革命论》继之，举三大主义以相鼓，钱玄同、刘半农和之，林纾与蔡元培往复辩难（1919年春其辩最烈）；《新青年》自第四卷起概用语体并加标点，北大讲堂亦渐以白话。", impact: "文学之改与学校之课程、报章之文体相因而动，不十年而言文之正统遂替，白话之文成于教科、小说与论说之全部；其流及于国语之统一与平民识字之运动，而反对者所持之礼教与文统之说亦自此转成对旧文化之总攻击，论近代文体之一变者以是二年为其枢纽。", figures: ["胡适", "陈独秀", "钱玄同", "林纾"], place: "北京、上海", state: "中华民国", sources: ["《新青年》第三、四卷原刊", "《中国新文学大系》建设理论集导言", "《蔡元培全集》"], tags: ["文学革命", "白话", "新青年"] }, related: ["cn--1918--c01", "cn--1917--i01"] },
  { id: "cn--1917--i01", track: "cn", year: 1917, yearApprox: false, dim: "institution", weight: 3, title: "蔡元培长北京大学", summary: "兼容并包之说入大学，讲习之法随之。", detail: { background: "京师大学堂以来，学生以官阶为进身之阶，学堂之积弊与政争之牵动相连，教育总长蔡元培请先改其根本，乃有校长之命。", process: "1917年1月蔡元培任北京大学校长，延陈独秀为文科学长，胡适、陶孟和、马叙伦等以次入讲，李大钊继掌图书部，定学会与刊物之目，立文、理科之研究会，废死记之法而采自修与讲习并重，以兼容并包为名，男女同校之议亦起于是数年中。", impact: "北大自是为全国学府之首，而学生之干预国事亦以是增长，1919年五月四日之集即以北大为出发之地；其兼容并包之说，后来论大学者引为准则，而言政教关系者亦以此为学术与政治相涉之证。", figures: ["蔡元培", "陈独秀", "胡适", "李大钊"], place: "北京", state: "中华民国", sources: ["《蔡元培全集》", "《（民国）教育杂志》1917—1919年原载", "《国立北京大学廿周年纪念册》"], tags: ["北京大学", "蔡元培", "大学改制"] }, related: ["cn--1919--p02", "cn--1917--c01"] },
  { id: "cn--1917--d01", track: "cn", year: 1917, yearApprox: false, dim: "disaster", weight: 3, title: "顺直大水", summary: "秋霖数旬，直隶诸河并溢。", detail: { background: "直隶之水利久废，永定、北运、大清河之堤多圮，1917年夏秋霖雨连旬，山东、豫东同时并潦。", process: "1917年7月至9月顺天、直隶诸河泛滥，永定河决，京汉、津浦之路时断，灾县之数自数十至百余，其说不一；灾民之口与赈款之多寡，内务、财政两部门之查报与后来义赈之册互有出入；京中设筹赈处，津、沪之商会与外籍工部局亦捐募。", impact: "水灾与兵争、财政并至，京畿一带米价腾贵，而1918年之时疫随之；各省之筹赈与义赈自此有稽核之名，1920、1924、1931诸次大水之办赈章程多本于此，论近世荒政之渐成制度化者每及此次。", figures: ["熊希龄"], place: "直隶、顺天、山东", state: "中华民国", sources: ["《（民国）政府公报》1917—1918年", "《申报》1917年原载", "华洋义赈会筹赈报告"], tags: ["水灾", "顺直", "筹赈"] }, related: ["cn--1920--d01", "cn--1931--d01"] },
  { id: "cn--1918--c01", track: "cn", year: 1918, yearApprox: false, dim: "culture", weight: 3, title: "《狂人日记》之刊", summary: "借狂人之目以见礼教之噬人。", detail: { background: "周树人在绍兴、北京之间久治古物与碑帖，偶与钱玄同论及写稿之事，以「铁屋子」之喻自道其意（1922年《呐喊》自序追记），乃应《新青年》之呼。", process: "1918年5月《新青年》四卷五号刊《狂人日记》，假日记之体写狂人之所见，以「仁义道德」字缝中之「吃人」为归宿，末附「救救孩子」之语，署鲁迅，为用此名之始；其下《药》《明天》《孔乙己》诸篇相继，1923年辑为《呐喊》，白话小说自是立于文学之正。", impact: "此篇以小说为思想之具，其效在文体与眼光之同时一变，后来之读鲁迅者皆始于此，而论新文学之成绩者每以为白话文学最早之确证；1919年以后之学生与报馆多拟其体，短篇小说一途自是大兴。", figures: ["周树人", "钱玄同", "陈独秀", "胡适"], place: "北京", state: "中华民国", sources: ["《新青年》第四卷第五号原刊", "鲁迅《呐喊》1923年初版", "《鲁迅日记》"], tags: ["狂人日记", "鲁迅", "白话小说"] }, related: ["cn--1917--c01", "cn--1919--p02"] },
  { id: "cn--1918--p01", track: "cn", year: 1918, yearApprox: false, dim: "politics", weight: 3, title: "欧战之终与战胜之庆", summary: "十一月十一日停战，京师以战胜自居。", detail: { background: "1918年春德国在西线之攻势不效，美兵东渡者岁百万，保加利亚、土耳其、奥匈相继请休战，柏林之局亦动。", process: "1918年11月11日德国与协约国订停战之约，北京政府令放假三日，京师与各省开会庆祝，中央公园之讲演以「公理战胜强权」为目，并将东单之克林德碑移入公园改题「公理战胜」坊；12月全权代表陆征祥先赴欧，顾维钧、王正廷、施肇基、魏宸组诸人与焉，和会于1919年1月开幕。", impact: "举国以战胜自许而望和议之见直，此心此气即1919年五月风潮之积也；而中国于战时所得者仅华工之费与对日之借款，工业之盛与纱粉之利亦于1921年后随欧市之复而骤衰，庆胜之喜与失望之痛皆在此一年内相继而至。", figures: ["陆征祥", "顾维钧", "段祺瑞"], place: "北京、巴黎", state: "中华民国", sources: ["《（民国）政府公报》1918年11月", "《申报》1918年原载", "李剑农《近代中国外交史资料辑要》中卷"], tags: ["欧战结束", "战胜国", "巴黎"] }, related: ["cn--1919--p01", "cn--1914--e01"] },
  { id: "cn--1918--i01", track: "cn", year: 1918, yearApprox: false, dim: "institution", weight: 3, title: "安福国会与新总统之选", summary: "新院成于俱乐部之操，徐世昌当选。", detail: { background: "段祺瑞以临时参议会改选法，欲别成多数之院以代旧国会，皖系之徐树铮、王揖唐等因设俱乐部于北京安福胡同以主选举。", process: "1918年8月12日新国会开幕于北京，两院之选多出安福俱乐部之所定，世称安福国会；9月4日两院选举大总统，徐世昌当选，10月10日就职；其前孙中山已辞广州军政府总裁之职，岑春煊主之，南北各有一府；此院至1920年夏皖系败而解体。", impact: "以一手操选举而成多数，国会自是无独立之望，南北之分立亦因是各据其一院为法统，1922、1923两次恢复旧国会之议皆本此；徐世昌之任而段祺瑞之去，皆以安福之党与为轻重，论议会政治之败坏者以此次选举为其最著之例。", figures: ["徐世昌", "段祺瑞", "王揖唐", "徐树铮"], place: "北京", state: "中华民国", sources: ["《（民国）政府公报》1918年", "《申报》1918年原载", "郭廷以《近代中国史纲》"], tags: ["安福国会", "总统选举", "皖系"] }, related: ["cn--1919--c01", "cn--1917--p02"] },
  { id: "cn--1919--p01", track: "cn", year: 1919, yearApprox: false, dim: "politics", weight: 4, title: "巴黎和会与山东问题", summary: "会中不许中国之请，专使卒不签字。", detail: { background: "和会于1919年1月开于巴黎，与会者数十国而大权在英、法、美、意、日，中国以取消二十一条、收回胶州为请，日本以继承德国之权益为辞，英、法前有密约之许。", process: "1919年4月底会中依前约定以德国在胶州湾之权益让与日本，5月6日由大会通知中国专使，中国请保留签字，会议不允；6月28日陆征祥、顾维钧等不赴凡尔赛宫之签字，电政府以闻，另于9月与奥国单独订约。", impact: "拒签为近世中国外交第一次不以完全之败告终之举，和会之不许遂使山东问题延至1922年华盛顿之解决，中德战时之关系亦至1921年《中德协约》而后更；中国与国际联盟之席次及其后加入，皆起于1919年五、六月之交。", figures: ["陆征祥", "顾维钧", "施肇基", "王正廷"], place: "巴黎、北京", state: "中华民国", sources: ["《近代中国外交史资料辑要》中卷所收和会文件", "《（民国）政府公报》1919年", "王芸生《六十年来中国与日本》"], tags: ["巴黎和会", "山东", "拒签"] }, related: ["cn--1919--p02", "cn--1915--p01"] },
  { id: "cn--1919--p02", track: "cn", year: 1919, yearApprox: false, dim: "politics", weight: 5, title: "五四之役", summary: "学生起于五月四日，工商继于六月五日。", detail: { background: "山东问题之和议将定的消息自4月底传于京师，北大与各校学生结集会而拟辞，政府方与日本换新汇率之商，曹汝霖、章宗祥与日人之关系为众所指。", process: "1919年5月4日各校学生集于天安门，赴东交民巷不得入，乃趋赵家楼曹汝霖宅，章宗祥被伤，宅被焚，当日被逮者数十人（其数各报不一）；6月3、4两日捕街头讲演者，先后以数百计；5日以后上海商会罢市、工界罢工、学校罢课，津、宁、汉、粤、穗继之；10日政府免曹汝霖、章宗祥、陆宗舆本兼各职，28日拒签和约。", impact: "学生一途自是为政治上不可忽之力，各省之学联、刊物与社团蜂起，马克思主义与各种社会主义之译述亦以是年而盛；工商之罢市为近世商人之首次与学界同举，论国民革命之群众运动者以五四为其起算之点，而言思想之解放者亦即此日而分前后。", figures: ["曹汝霖", "章宗祥", "傅斯年", "陈独秀"], place: "北京、上海", state: "中华民国", sources: ["中国近代史资料丛刊《五四运动》，上海人民出版社", "《申报》1919年原载", "《每周评论》1919年原刊"], tags: ["五四运动", "学生", "罢市"] }, related: ["cn--1919--p01", "cn--1920--c01"] },
  { id: "cn--1919--c01", track: "cn", year: 1919, yearApprox: false, dim: "culture", weight: 3, title: "社团与学报之盛", summary: "学联、社团与刊物蜂起于一岁之间。", detail: { background: "五四风潮既起，学生以联合与刊号为自见之具，前此之学会、报馆多赖外力或官府，至此则一校一省各自为社。", process: "1919年1月北京大学新潮社出《新潮》月刊，7月1日少年中国学会成立于北京（王光祈、李大钊、周作人等与焉），《湘江评论》创刊于长沙（毛泽东主编），《天津学生联合会报》继之，各省学联之旬刊、周刊不可悉数；冬，北京设工读互助团，仿新村与互助之说，试行数月而散（社团与刊物之总数，各册所记多寡不一）。", impact: "此一年所立之社团与刊物，为1920年代政党、文学团体与社会运动之分流张本，工读、新村与无政府诸说亦由实验之败而退，马克思主义与苏俄之闻渐居其上；论近代青年之组织化者，以1919年为其起讫。", figures: ["王光祈", "李大钊", "毛泽东", "傅斯年"], place: "北京、长沙、天津、上海", state: "中华民国", sources: ["《新潮》月刊1919年原刊", "《湘江评论》1919年原刊", "《少年中国学会会务报告》"], tags: ["学生社团", "刊物", "工读互助"] }, related: ["cn--1919--p02", "cn--1919--c02"] },
  { id: "cn--1919--c02", track: "cn", year: 1919, yearApprox: false, dim: "culture", weight: 2, title: "杜威来华讲学", summary: "美哲人东来，讲席遍于京津宁沪。", detail: { background: "欧战既终，欧美之学者以观感东来，中国之教育界与哲学界方苦于主义之无师，江苏省教育会与北京大学因有延请之约，胡适、陶孟和任其事。", process: "1919年4月30日杜威抵上海，自5月起讲演于北京、南京、上海、杭州诸地，论教育、哲学与民主，历时两年余乃归，讲辞多由胡适、蒋梦麟诸人传译，报馆逐日录之；罗素于1920年秋亦至北京讲演，旋以病辍，孟禄于1921年秋来华考察教育（诸人讲演之场次与记录，各册互有详略）。", impact: "杜威之门与实验之说自是入于教育之文，1922年新学制与平民教育之运动皆承其气，讲演与翻译遂成思想输入之正途；而后之批者谓此风专重教育而疏于制度，论民国思想界之外源者每及之。", figures: ["杜威", "胡适", "蒋梦麟", "陶孟和"], place: "上海、北京、南京、杭州", state: "中华民国", sources: ["《杜威五大讲演》（1919年北京讲演记录）", "《晨报》1919—1921年原载", "《蔡元培全集》"], tags: ["杜威", "讲学", "实验主义"] }, related: ["cn--1919--c01", "cn--1922--i01"] },
  { id: "cn--1919--p03", track: "cn", year: 1919, yearApprox: false, dim: "politics", weight: 2, title: "南北和平会议之辍", summary: "上海开议六月而罢，两府仍各其一。", detail: { background: "1917年秋广州立护法军政府，与北京各署一府，欧战既终，外人劝和，湘、桂之军亦以罢兵为便，乃有议和之约。", process: "1919年2月20日南北代表会议开于上海，南方以唐绍仪为总代表，北方以朱启钤为总代表，所争在参战借款、解散参战军与国会之法统数端；5月北京学生风潮起，督军与安福系之电阻益厉，8月北方代表辞职，和议遂辍（会议之议案与往返电文，各册录有多寡）。", impact: "和议之不成使南北之分立长为常局，而各省之督军得以后拥兵而主持和战，1920年直皖之役、1921年广州之大总统府皆缘此局而生；论民国统一之难者，常以此会之辍为第一次可为而不为之例。", figures: ["唐绍仪", "朱启钤", "段祺瑞", "岑春煊"], place: "上海", state: "中华民国（北京、广州两府并立）", sources: ["《申报》1919年原载", "李剑农《近代中国外交史资料辑要》中卷", "郭廷以《近代中国史纲》"], tags: ["南北和议", "法统", "上海"] }, related: ["cn--1919--p02", "cn--1921--p02"] },
  { id: "cn--1919--e01", track: "cn", year: 1919, yearApprox: false, dim: "economy", weight: 3, title: "欧战后期之华资工厂", summary: "纱粉之利方厚，华商扩厂于各埠。", detail: { background: "欧战以来洋货之入口骤减、出口之土产见贵，1915年后之抵货风潮又为华商开一市场，银行与钱庄之借贷遂趋工业。", process: "1919年前后，上海、无锡、青岛、天津之华资纱厂与面粉厂迭有增机，荣氏之福新、茂新与申新系统、张謇之大生系统为其尤著者，日商亦于青、沪两埠续设纱厂以分其利（工厂之数、纱锭与资本之额，注册、海关与后来统计出入较大，未可归并为一说）。", impact: "此数年华商工业之骤扩，世称民族工业之黄金时代，其源在欧战之机会而非在制度之改良，故1921年后欧市既复、日厂竞兴，纱布之价一落而亏折、收售之案纷起；论中国工业之依赖外局者每引及之。", figures: ["张謇", "荣宗敬", "周学熙", "穆藕初"], place: "上海、无锡、青岛、天津", state: "中华民国", sources: ["汪敬虞编《中国近代工业史资料》第二辑", "海关《十年报告（1912—1921）》", "《申报》1919年原载"], tags: ["民族工业", "纺织", "面粉"] }, related: ["cn--1915--e01", "cn--1914--e01"] },
  { id: "cn--1920--c01", track: "cn", year: 1920, yearApprox: false, dim: "culture", weight: 3, title: "《共产党宣言》全译之刊", summary: "陈望道译本成于上海，一书而众传。", detail: { background: "1919年以来《新青年》与《每周评论》迭译马、恩之文，北京、上海之小组以读本课会员，全译之需由此而起。", process: "1920年8月陈望道自浙江分水（今武义一带）应《新青年》之约所译《共产党宣言》，由上海社会主义研究社排印出版，为是书全文汉译之始，其封面偶有讹题之说；同年9月起北京、广州之马克思主义研究会以此课读，重印多次（初版与重印之数，各册记载不一）。", impact: "此一译本定此后数十年常用之术语，共产党之纲领与宣言皆自其语句出，1921年以后之党员多由此书入门；而翻译出于留日与留法之学者，其文体亦为论说文之一变，后之论新文化之政治转向者每举此书为标志。", figures: ["陈望道", "陈独秀", "李汉俊"], place: "上海", state: "中华民国", sources: ["陈望道译《共产党宣言》，上海社会主义研究社1920年8月版", "《新青年》第八卷原刊", "中共中央党史研究室《中国共产党历史》第一卷"], tags: ["共产党宣言", "翻译", "马克思主义"] }, related: ["cn--1919--c01", "cn--1921--p01"] },
  { id: "cn--1920--p01", track: "cn", year: 1920, yearApprox: false, dim: "politics", weight: 3, title: "直皖之役与皖系之败", summary: "七日而京畿事定，段祺瑞去职。", detail: { background: "对日借款与参战军之成，直、奉诸督以皖系专权为病，1920年春西南与奉天之使交结于津，吴佩孚自湘南撤防北归，其势遂急。", process: "1920年7月14日直、皖两军在京津一带开衅，17日至19日皖军之西路溃，段祺瑞于22日辞职，徐树铮出走西北，安福俱乐部与段氏之参战军旋被解散，8月新国会自解，安福所举之徐世昌仍居总统之位（两军之胜负与日人之接济皖系，各册所述互有异同）。", impact: "皖系既败，直、奉共秉中枢，而段祺瑞所借之日款与其练兵之策并为后来之争，梁士诒、颜惠庆诸内阁皆缘款与军而见重于奉系；论民国派系政治者谓自是中央无复自主之军，政令随两系之离合为转移。", figures: ["段祺瑞", "吴佩孚", "曹锟", "徐树铮"], place: "北京、廊坊、松林店", state: "中华民国", sources: ["《（民国）政府公报》1920年7月", "《申报》1920年原载", "郭廷以《近代中国史纲》"], tags: ["直皖战争", "皖系", "安福"] }, related: ["cn--1918--i01", "cn--1922--p02"] },
  { id: "cn--1920--p02", track: "cn", year: 1920, yearApprox: false, dim: "politics", weight: 2, title: "湖南自治之议", summary: "湘人倡省宪，数省随之。", detail: { background: "护法之师久无成，湘军厌战，谭延闿代主湘局，以「湘人治湘」为解于南北之间，省宪之议遂起于学界与报界。", process: "1920年9月谭延闿任湖南督军，通电主各省自定宪法，11月设筹备机关，1921年省宪草成而交付讨论（1922年1月正式公布），浙江、广东、江苏、四川诸省相继言自治，1922、1923年间联省自治之议几为国会与舆论之一大讼端（各省制宪之成否与先后，各册出入较大）。", impact: "自治之说欲以省宪为国防与统一之基，而实际上多成督军自固之具，湖南之省宪卒不能禦1926年以后之北伐军；北伐后此议遂熄，论联邦式统一之不可行者，每以湘、粤两省之经历为证。", figures: ["谭延闿", "赵恒惕", "彭允彝"], place: "湖南长沙", state: "中华民国", sources: ["《湖南省宪法》1922年刊本", "《大公报》1920—1923年原载", "郭廷以《近代中国史纲》"], tags: ["联省自治", "省宪", "湖南"] }, related: ["cn--1921--m01", "cn--1920--p01"] },
  { id: "cn--1920--d01", track: "cn", year: 1920, yearApprox: false, dim: "disaster", weight: 3, title: "海原、固原大地震", summary: "冬夜地动，陇上数县几尽。", detail: { background: "甘肃东部之断带素号地震之区，村落多窑居，冬夜冻寒，人皆在室，故其灾尤重。", process: "1920年12月16日傍晚（农历十一月初七）甘肃海原、固原一带大震，山崩地裂，城郭、窑居之民多压，波及甘、宁、陕、豫数省；死亡之数自十余万至二十余万，各方统计差异较大，其以估算为多，核数之无术与兵争之隔碍皆使之然；1921年春官府与义赈陆续前往，外国之赈团与报馆亦有调查之文。", impact: "此次之震使中国始有近代地质与地震调查之注意，后来之地震带图与窑居之戒皆本于此；督军陆洪涛报于朝，京中义赈之会募于市，是年直、鄂、皖诸省并告水灾，统一救灾之会所由起；赈务之迟速与兵、匪之隔截亦为地方之讼，论西北之贫与交通之阻者每引是役为言。", figures: ["陆洪涛", "熊希龄"], place: "甘肃海原、固原", state: "中华民国", sources: ["国家地震局编《中国地震历史资料汇编》", "《申报》1920—1921年原载", "华洋义赈会筹赈报告"], tags: ["地震", "海原", "赈务"] }, related: ["cn--1917--d01", "cn--1920--i01"] },
  { id: "cn--1920--e01", track: "cn", year: 1920, yearApprox: false, dim: "economy", weight: 3, title: "纱布风潮与欧市之复", summary: "沪上投机骤起，纱价一夕而坠。", detail: { background: "1920年夏秋之交，欧战既终而外厂复市，纱布之入口渐多，上海之交易所与栈单之买卖方盛，钱庄之拆借日滥。", process: "1920年11月上海纱、丝、物品各交易所之投机最烈，标价日数易，商民争以栈单相买卖，12月初价格骤坠，倒号、停兑与歇业之厂相继而起，苏州、无锡、宁波之钱庄为之牵动，各业之亏折与票号之倒闭，海关与商会之册报互有出入；华资纱厂由是盈转亏者什伍，日商之厂亦同受其扰。", impact: "一战期间工业之盛自是而终，1921年以后各厂之拍卖、加押与日商之收买相寻而出，民族工业所谓黄金时代者以两年为断；论者谓其病在金融与市场之倚外，不在机器与人工，此说至1930年代不变。", figures: ["荣宗敬", "穆藕初", "聂云台"], place: "上海、无锡、苏州", state: "中华民国", sources: ["《上海钱庄史料》", "海关《十年报告（1912—1921）》", "《申报》1920年原载"], tags: ["纱布风潮", "投机", "钱庄"] }, related: ["cn--1919--e01", "cn--1920--i01"] },
  { id: "cn--1920--i01", track: "cn", year: 1920, yearApprox: false, dim: "institution", weight: 3, title: "小学国语之改", summary: "教育部通令，国民学校先用国语。", detail: { background: "文学革命之议已三年，报章与杂志之语体大行，而学堂之读犹禀文言，国语统一筹备会有年余之讨论。", process: "1920年1月北京政府教育部通令国民学校一、二年级之国文科目改用语体（谓之国语），4月令以三年之内遍及各级，并令师范与讲习所附设国语之科，同年刊定国语字母（注音字母）之次序（通令之月日与各省遵办之迟速，教育杂志与部档所载略有出入）。", impact: "一令之下，小学之教科、师范之课程与出版物之文体同时而变，白话自是立于启蒙之正，识字与读音之划一亦始有可循之据；而言旧文者以为并其文化之根，此后之学堂与礼教之争，其半也由此令而启。", figures: ["蔡元培", "吴敬恒", "黎锦熙"], place: "北京（通行全国）", state: "中华民国", sources: ["《（民国）教育杂志》第十二卷原载", "《蔡元培全集》", "黎锦熙《国语运动史纲》"], tags: ["国语", "小学教科", "教育部令"] }, related: ["cn--1917--c01", "cn--1922--i01"] },
  { id: "cn--1920--i02", track: "cn", year: 1920, yearApprox: false, dim: "institution", weight: 2, title: "机器工会之立", summary: "沪上先设产业工会，补习学校随之。", detail: { background: "欧战以来工厂与码头之工人日众，工时、学徒与工头之制为人所病，学生与记者往调查者渐多。", process: "1920年11月上海机器工会开成立会于霞飞路，发起者多《新青年》与星期评论社之同人，印刷、邮务诸业继之；北京方面1921年1月设长辛店劳动补习学校于京汉路之工厂，上海亦办半日学校与工人周刊（各工会之会员数与成立之月日，各册记载多异）。", impact: "工界自此有组织与文字，1921至1923年之罢工多由此种补习学校与工会生出，1923年二月京汉之役即其最著者；而工会之发动半由学生与党员之外助，故其后之工会常与政党同其起伏，论民众组织者以此为党与社会相联之始。", figures: ["陈独秀", "邓中夏", "李中"], place: "上海、北京长辛店", state: "中华民国", sources: ["《劳动界》周刊1920年原刊", "《（民国）上海地方志》工商篇", "《“一大”前后》，中国革命博物馆编"], tags: ["工会", "劳工运动", "补习学校"] }, related: ["cn--1921--p01", "cn--1923--p01"] },
  { id: "cn--1921--p01", track: "cn", year: 1921, yearApprox: false, dim: "politics", weight: 5, title: "中国共产党之成立", summary: "七月开会在上海，末移嘉兴之舟。", detail: { background: "1920年夏秋之间，北京、上海与旅日、旅法之小组已相继而立，共产国际之代表东来，刊物与补习学校亦已有基，乃有召集全国代表之议。", process: "1921年7月23日第一次全国代表大会开于上海法租界望志路之宅，出席代表以各地所记为十三人（其数与姓名各册互有出入），共产国际代表马林、尼科尔斯基到席；7月30日因巡捕搜查而辍会，末后一日移浙江嘉兴南湖之舟中行之以终，议定纲领与当前工作之决议，选中央局，陈独秀为书记；是年冬党员之数各地自报仅数十人。", impact: "自是于国民党和其余政党之外别有一以工厂、铁路与农运为任之组织，其初数年半在国民党与军阀之夹缝中，1923年之加入与1927年之分裂皆伏于此一纲；论中国革命之两途与其后之国共恩怨者，无不始于此会，而会址之舟亦由是成为纪念之地。", figures: ["陈独秀", "毛泽东", "董必武", "马林"], place: "上海、浙江嘉兴南湖", state: "中华民国", sources: ["中共中央党史研究室《中国共产党历史》第一卷（1921—1949）", "《“一大”前后》，中国革命博物馆编，人民出版社", "陈潭秋《第一次代表大会的回忆》（1936年）"], tags: ["中共一大", "建党", "共产主义小组"] }, related: ["cn--1920--c01", "cn--1920--i02"] },
  { id: "cn--1921--p02", track: "cn", year: 1921, yearApprox: false, dim: "politics", weight: 3, title: "广州总统府之建", summary: "非常国会举任，五月而开府。", detail: { background: "1918年军政府改总裁制后，孙中山辞任居沪，两年之间以著书与讲学自处，西南诸将各拥其地，护法之名几废。", process: "1921年4月国会非常会议在广州选举孙中山为非常大总统，5月5日就职，复设总统府，以陆荣廷、陈炯明分任桂、粤军务，议北伐与北伐之饷；7月非常国会通过助饷之案，桂系与粤军之隙自是并起（府制与所任人员，公报与报馆所记略有先后之差）。", impact: "一府之立使南北各举其一统之名，1922年陈炯明之变与1923年再立之大元帅府皆自此出；而欲以两广之财供北伐之师，其不可得也亦自此见，孙氏此后所以有改组党务、联俄与借农工之力之举。", figures: ["孙中山", "陈炯明", "陆荣廷", "马君武"], place: "广州", state: "中华民国（广州总统府）", sources: ["《孙中山全集》第五卷", "《（民国）政府公报》广州1921年", "郭廷以《近代中国史纲》"], tags: ["非常国会", "总统府", "北伐"] }, related: ["cn--1922--p03", "cn--1919--p03"] },
  { id: "cn--1921--c01", track: "cn", year: 1921, yearApprox: false, dim: "culture", weight: 2, title: "创造社之立", summary: "留日学生结社于东京，明年刊书。", detail: { background: "文学革命之后，新文学之成者少而模仿者多，留东之习医、习军学者以文艺自命，不屑与《新青年》诸人为一途。", process: "1921年7月郭沫若、郁达夫、成仿吾、张资平、田汉等在东京成立创造社，1922年5月出《创造季刊》，以抒情与自叙之体为尚，1924年设创造社出版部于上海，继有《创造周报》《洪水》之属（发起人先后与入社之数，社史诸说不同）。", impact: "创造社与文学研究会分新文学为人生与自我两路，其后又转向革命文学，1928年前后与鲁迅诸人成笔墨之争，至1930年左联之立而其人多为其骨干；论近代作家之结社与政见相随者，此社最可为例。", figures: ["郭沫若", "郁达夫", "成仿吾"], place: "日本东京、上海", state: "中华民国", sources: ["《创造季刊》1922年原刊", "郁达夫《创造社》（回忆之文）", "《郭沫若全集》"], tags: ["创造社", "文学团体", "抒情"] }, related: ["cn--1921--p01", "cn--1930--c01"] },
  { id: "cn--1921--m01", track: "cn", year: 1921, yearApprox: false, dim: "military", weight: 2, title: "援鄂之役与两湖之任", summary: "湘军以自治为名入鄂，直系乘之。", detail: { background: "王占元主鄂数年，饷绌兵哗之案三起，湘人以自治相号召，赵恒惕欲借鄂为省宪之外援，吴佩孚则欲得两湖为根本。", process: "1921年7、8月湘军以援鄂之名入鄂南，鄂军几溃，8月王占元去职，北京任王怀庆继之而不前，乃改任萧耀南为湖北督军、吴佩孚为两湖巡阅使，直军南下，湘军败归，岳州一带复为直系所据（两军之往返与伤亡，各册所载甚略）。", impact: "一役而湖北入直系之手，湖南孤立于两强之间，此后赵恒惕之自保专恃省宪与外援，1926年北伐军入湘而湘局立解；论者谓援鄂之役于自治为失计，于军阀之并兼为得计，省宪与兵争之不相容自此益明。", figures: ["赵恒惕", "吴佩孚", "王占元", "萧耀南"], place: "湖南、湖北", state: "中华民国", sources: ["《（民国）大总统选举与任命令》，见政府公报1921年", "《申报》1921年原载", "郭廷以《近代中国史纲》"], tags: ["援鄂之役", "两湖巡阅使", "湘军"] }, related: ["cn--1920--p02", "cn--1920--p01"] },
  { id: "cn--1922--p01", track: "cn", year: 1922, yearApprox: false, dim: "politics", weight: 4, title: "华盛顿会议与山东之解决", summary: "九国之约成而胶州还，路权徐议。", detail: { background: "巴黎之会中国拒签，山东悬案未了，美国以限制军备与远东为辞召集会议，日本以既有之权益为守，中国以一案一议为请。", process: "1921年11月12日会议开于华盛顿，12月13日英、美、法、日订四强之约而英日同盟以终；1922年2月4日《解决山东悬案条约》及附约签字，日本将青岛与胶州湾之旧租借地交还中国，胶济铁路由中国以国库券赎还（路价与年限之约文，中日两国之译本与后来核算出入较大），未交还前日人仍派车务、会计之员；2月6日九国关于中国之条约成，以尊重中国之主权、独立与领土、行政之完整并机会均等、门户开放为义。", impact: "山东一案自巴黎延至此会而了，为近世外交以众国合同之约收回租借地之仅见例（其条款之实行则自1922年12月至1923年陆续交接），而九国之约以机会均等为纲，此后关税、法权诸问题皆援之为据；论者谓华盛顿之局实以美、英之势抑日本之独进，中国之所得在约文而不在实力。", figures: ["施肇基", "顾维钧", "王正廷"], place: "华盛顿、北京", state: "中华民国", sources: ["《近代中国外交史资料辑要》中卷所收华盛顿条约全文", "王芸生《六十年来中国与日本》", "《申报》1922年原载"], tags: ["华盛顿会议", "九国公约", "山东悬案"] }, related: ["cn--1919--p01", "cn--1922--e01", "world--1921--p02"] },
  { id: "cn--1922--p02", track: "cn", year: 1922, yearApprox: false, dim: "politics", weight: 3, title: "第一次直奉之役与法统之复", summary: "直胜而奉关外自守，黎元洪再任。", detail: { background: "直皖既败，奉、直共秉中枢，梁士诒内阁以借款与路权见责于直，吴佩孚自洛通电促其去职，两军之冲突在山海关、京汉之间蓄势。", process: "1922年4月29日直、奉两军开衅于京汉、京绥之线，5月4日奉军败而退出长城，张作霖在东三省自设保安之署而关外之局遂成自立之势；6月徐世昌去任，曹锟以「法统重光」为说，6月11日黎元洪再任大总统，复行临时约法并召集旧国会（奉军之伤亡与关外自主之文告，各册所载互异）。", impact: "一岁之间而中枢再易，直系既胜而无所用之，乃有1923年大选之争；奉人自是不复奉北京之令，1924年再战于山海关而直局遂倾，论关外之自成一体与直系之骤盛骤败者，皆以此役为断。", figures: ["曹锟", "吴佩孚", "张作霖", "黎元洪"], place: "北京、山海关、洛阳", state: "中华民国", sources: ["《（民国）政府公报》1922年", "《大公报》1922年原载", "郭廷以《近代中国史纲》"], tags: ["直奉战争", "法统重光", "关外自主"] }, related: ["cn--1920--p01", "cn--1924--m01"] },
  { id: "cn--1922--p03", track: "cn", year: 1922, yearApprox: false, dim: "politics", weight: 3, title: "广州六月之变", summary: "粤军围总统府，登舟五十日而后去。", detail: { background: "陈炯明主粤，持联邦与保境之议，与孙中山之北伐方略日异，4月辞粤军总司令之任而所部仍驻惠州、广州之间，总统府与粤军之饷、械相逼。", process: "1922年6月16日粤军围观音山总统府并炮击越秀楼，孙中山登永丰舰（后改名中山舰）避之，自17日至8月9日在舰凡五十余日，命舰队与诸将响应而事不济，乃离粤赴沪；其部将叛军据广州，孙氏通电以陈炯明为讨，1923年1月滇、桂诸军东下，2月21日孙中山回广州设大元帅府（炮击之日与舰中天数，各记略有先后）。", impact: "倚军之策至此一败涂地，孙氏自是专意于党务之改组与农工之助力，1923年越飞之来、1924年三大政策之定皆缘此变；而永丰一舟与五十日之围成为党史与民国史同记之事迹，1925年改舰名为中山即本此。", figures: ["孙中山", "陈炯明", "永丰舰诸将姓氏各册不同"], place: "广州、上海", state: "中华民国（广州）", sources: ["《孙中山全集》第六卷", "《申报》1922年原载", "郭廷以《近代中国史纲》"], tags: ["六一六之变", "永丰舰", "粤军"] }, related: ["cn--1921--p02", "cn--1924--p01"] },
  { id: "cn--1922--i01", track: "cn", year: 1922, yearApprox: false, dim: "institution", weight: 3, title: "壬戌新学制之行", summary: "六三三之段定，学校之制自是相沿。", detail: { background: "1912年之学制仿自日本，民国以来议论百出，全国教育会联合会数年筹议，美国孟禄来华考察教育，实用主义与平民教育之说方盛。", process: "1922年11月北京政府以大总统令公布《学校系统改革案》，定初等六年、高等三年、高等中三年之段（世称六三三制），并立小学、中等、高等三段之通则与平民教育、职业补习之目，取消旧时之实业学堂独立一系而并入中等（令文与教育会联合会议案之出入，教育杂志所载有二本）。", impact: "此制至今为学校分段之张本，其效在中学之扩张、女学之得位与选课之渐行，而一代之教员与学生由此养成；论教育之美国化者以此定为界，1920年代以后之大学、师范与实业教育之消长，莫不以其条文为依归。", figures: ["孟禄", "蔡元培", "陶行知", "袁希涛"], place: "北京（通行全国）", state: "中华民国", sources: ["《（民国）教育杂志》第十四卷原载", "《学校系统改革案》1922年令文", "《蔡元培全集》"], tags: ["壬戌学制", "六三三", "教育改革"] }, related: ["cn--1920--i01", "cn--1919--c02"] },
  { id: "cn--1922--m01", track: "cn", year: 1922, yearApprox: false, dim: "military", weight: 3, title: "香港海员之罢工", summary: "一月起而春复工，沙田一夜见血。", detail: { background: "欧战之后船运之利厚而华员之薪薄，1921年海员工会已在广州立案，英国之船行不许其议薪，1922年1月全体辞职。", process: "1922年1月12日香港海员罢工起，二、三月间全港水陆各业继之，离港返广州者以万计；3月4日由九龙步行回省之众在沙田一带被华英兵警阻拦开枪，死伤之数官册与工会之报互异，港府旋宣布工会为非法并施检阅之令；3月8日港府允增薪、承认工会并释被捕者，乃复工，凡五十六日（所增之成数自一成五至三成）。", impact: "此为战后中国工界第一次以长时期之罢工而得增薪，海员与铁路、码头诸业自是相率立会，中国劳动组合书记部由此知群众之力可用；于港英一面则知工潮与民族之情绪不可复分，1925年省港之大罢工即循其轨而来。", figures: ["苏兆征", "林伟民", "陈潭秋"], place: "香港、广州沙田", state: "英属香港、中华民国", sources: ["《申报》1922年原载", "《工人周刊》1922年原刊", "中共中央党史研究室《中国共产党历史》第一卷"], tags: ["海员罢工", "沙田惨案", "工会"] }, related: ["cn--1920--i02", "cn--1923--p01"] },
  { id: "cn--1922--c01", track: "cn", year: 1922, yearApprox: false, dim: "culture", weight: 2, title: "学衡与努力之刊", summary: "一主人文之择，一主改良之评。", detail: { background: "文学革命之后五年，反对与修正者渐成一说，留美习文学者据白璧德之议以绳新说，留欧习地质者则以政治之评论自任。", process: "1922年1月《学衡》月刊创刊于南京，梅光迪、胡先骕、吴宓主之，以整理国故、融化西洋之有益者相标，于白话与文学革命多所驳正；同年4月《努力周刊》创刊于北京，胡适、丁文江等任之，先议「好政府主义」，继论制宪与统一诸案（两刊之撰文人与期数，各册目录小有出入）。", impact: "《学衡》一派使新文化之论不止于黑白之分，其于古籍、科学与传记之功力后来自见，1920—1930年代之学院派文字多出其途；《努力》则以学者而议政府，开「独立评论」一途之先，而后之论政治者以其无力而讥学者干政之难。", figures: ["梅光迪", "吴宓", "胡适", "丁文江"], place: "南京、北京", state: "中华民国", sources: ["《学衡》月刊1922年原刊", "《努力周刊》1922年原刊", "《胡适文存》第三集"], tags: ["学衡", "努力周刊", "好政府主义"] }, related: ["cn--1917--c01", "cn--1922--s01"] },
  { id: "cn--1922--s01", track: "cn", year: 1922, yearApprox: false, dim: "science", weight: 2, title: "中国地质学会之立", summary: "北京立会刊志，野外之学始有同人。", detail: { background: "农商部地质调查所自1916年积累标本与图说，外籍教师与留学生各据所见，尚无合群讲习之会，会之设自日本、欧美之学会取法。", process: "1922年中国地质学会成立于北京，章鸿钊、丁文江、翁文灏、李四光等为其创始会员，未几出《中国地质学会志》，以中外文并行刊载野外调查、地层与矿产之文，会友之调查自直隶、山西、云南渐及于东北与西北（会员之额与刊物之起始期，各册所载略异）。", impact: "自是中国之地层、构造与矿产之说始由本国学者自立，而会志亦成为国际引用之文，中央研究院地质研究所之设与其后之石油、煤田勘察皆由此出人；其法以实测与标本为凭，故1930年代兵争之际调查所与学会仍续行野外工作，论近代科学之生根者每举地质为最著之例。", figures: ["章鸿钊", "丁文江", "翁文灏", "李四光"], place: "北京", state: "中华民国", sources: ["《中国地质学会志》1922年起原刊", "《（民国）农商部地质调查所矿产报告》"], tags: ["地质学会", "地层", "科学团体"] }, related: ["cn--1909--s01", "cn--1922--c01"] },
  { id: "cn--1922--e01", track: "cn", year: 1922, yearApprox: false, dim: "economy", weight: 3, title: "青岛之接收与日厂之竞", summary: "旧德租借地还，胶济路以债票赎。", detail: { background: "德国据胶州时所设之矿路港厂，1914年为日本所夺，华府之约定以归还，而路、矿之产业须付价而后交。", process: "1922年12月10日中国政府接收青岛之行政，1923年1月1日接收胶济铁路及其附属之煤矿与地产（接收之次序与各段交接月日，交接册与报馆所记略异），所付之价以国库券分期偿还，未偿之先仍用日方之车务、会计人员；其时日商在青之纱厂大康、公大、钟渊之属迭有扩充，华厂之在青岛者与之争人工与销路。", impact: "胶济路与青岛之收回为华府会议在中国之唯一实效，然路矿之债与日厂之存使山东之经济仍系于外力，1925年青岛日商纱厂之工潮与五月之惨案即由是生；论收回租界与实业主权之间隔者，以青岛为最明之例。", figures: ["王正廷", "高恩洪"], place: "青岛、济南", state: "中华民国", sources: ["《近代中国外交史资料辑要》中卷所收山东悬案条约", "海关《十年报告（1922—1931）》", "《申报》1922年原载"], tags: ["青岛收回", "胶济铁路", "日商纱厂"] }, related: ["cn--1922--p01", "cn--1925--p02"] },
  { id: "cn--1923--p01", track: "cn", year: 1923, yearApprox: false, dim: "politics", weight: 4, title: "二七之役", summary: "京汉一路同歇，七日长辛店开枪。", detail: { background: "1921年以来铁路补习学校与工会遍于京汉沿线，总工会之设为其汇总，直方以「干涉军务」为戒，郑州之成立会未散而兵已至。", process: "1923年2月1日京汉铁路总工会在郑州开成立会，军警拦阻，4日全线总同盟罢工，交通、煤运与税课顿滞；7日长辛店、郑州、江岸（汉口北）三处军警同时开枪并以刺刀，江岸之林祥谦、施洋二人被杀，死伤之数由数十至数百，官方之册报与工会、报馆所记大相悬殊，捕人与封会之令继下；9日工会忍令复工以免无益之伤。", impact: "自是北方之工运转入地下，工会之公开活动几绝者数年，而中国共产党亦因是知单恃工界不可胜，乃有1923年六月之决议案主与国民党合作，1924年改组之事以是为其反推之力；论1920年代劳工运动与党派关系者，以二七为转折之点。", figures: ["林祥谦", "施洋", "项英"], place: "郑州、长辛店、汉口江岸", state: "中华民国", sources: ["《中共党史资料》所收京汉铁路罢工之文件", "《申报》1923年2月原载", "《“一大”前后》，中国革命博物馆编"], tags: ["京汉铁路", "二七惨案", "总同盟罢工"] }, related: ["cn--1922--m01", "cn--1924--p01"] },
  { id: "cn--1923--p02", track: "cn", year: 1923, yearApprox: false, dim: "politics", weight: 3, title: "曹锟之选与十三年宪法", summary: "宪法以双十日公布，选举以票价见讼。", detail: { background: "黎元洪复职之后，总统之任与宪法之成同时待决，直系欲以制宪为曹锟正位之名，国会内之制宪会与阁、府之争日烈，1923年6月军警索饷围府之案起而黎氏出走。", process: "1923年6月黎元洪离京，国会逐署之议不成；10月5日两院选举大总统，曹锟当选，议院外传以每票几何之说，天津之检厅并传钞其票据，报馆所记每票之数自千元至五千元不一；10月10日《中华民国宪法》公布，凡十四章百四十一条，为民国成立以来第一部正式宪法，同日曹锟就职（选举之人数与票价之传闻，各册异辞，未有确数）。", impact: "宪法之条文多取地方自治与司法独立之义，然因选举之讼而不为南与野所认，一年而段祺瑞入京，约法与宪法之统绪又绝；论者谓民国之失不在无宪法而在无行宪之势，十三年之宪法遂为议会政治结束时之一大反证。", figures: ["曹锟", "黎元洪", "吴景濂"], place: "北京、天津", state: "中华民国", sources: ["《中华民国宪法》1923年10月刊本", "《申报》1923年10月原载", "郭廷以《近代中国史纲》"], tags: ["十三年宪法", "大选", "贿选之讼"] }, related: ["cn--1916--i01", "cn--1918--i01"] },
  { id: "cn--1923--m01", track: "cn", year: 1923, yearApprox: false, dim: "military", weight: 2, title: "临城之劫车与使团之牒", summary: "浦路上掳外侨，中外因此议路警。", detail: { background: "1922年直、奉之役既过，鲁南一带散兵与匪群凭抱犖崙之险，津浦路之行车无护，外侨之旅行日多而报案亦日积。", process: "1923年5月6日津浦路之北行列车至临城以南被劫，中外乘客被掳数十人，英、美之侨死者数人（死伤与被掳之名数，公司、领事与地方之报互异）；北京与驻外使团前后照会、通牒数四，要求惩办、赔恤并整顿路警，山东方面以招降赎人为了案，孙美瑶之众受编而旋散，督办、镇守使以次免职（赎金之数与所提之官，各册记载不一）。", impact: "此案使列强得以护路为名议组织路警之制，津浦路之警察与卫队由是渐操于外人，论民国路权之侵蚀者每举此案；同时地方之匪与兵之相杂亦见，鲁南之民自是不以官军为可依，其后之红枪会与民间武装由此而盛。", figures: ["孙美瑶", "王芝祥", "胡汝麟"], place: "山东临城、北京", state: "中华民国", sources: ["《（民国）国务院档案》，见中国第二历史档案馆藏档", "申报》1923年5月原载", "李剑农《近代中国外交史资料辑要》中卷"], tags: ["临城劫车", "路警", "赔恤"] }, related: ["cn--1922--p02", "cn--1923--p02"] },
  { id: "cn--1923--s01", track: "cn", year: 1923, yearApprox: false, dim: "science", weight: 2, title: "层累说之古史", summary: "以辩难之法读古书，禹字之解为端。", detail: { background: "康有为《孔子改制考》于清末以托古之说出经典，清末以来之辨伪与疑古之风相续，民国十三年前后钱玄同与顾颉刚往复论之。", process: "1923年顾颉刚《与钱玄同先生论古史书》刊于上海《读书杂志》第九号，举时代愈后、传述之古史愈早之义，谓三代之古史多出后世之附益，遂有「层累地造成的中国古史」之称；1926年起《古史辨》以辑录辩难之文印行，继辑至数编，学界之风为之一变（《古史辨》之编次与出版之岁月，诸家目录略有异同）。", impact: "此说使古籍由信而征，凡先秦之史皆须审其成书之先后，古史与考古、金石之学因此并兴，1928年以后之殷墟发掘亦受其气；而持异议者谓其以文字之证破三代之信，近于自坏其国史，论古史之可信与可疑者自是成两途。", figures: ["顾颉刚", "钱玄同", "王国维"], place: "上海、北京", state: "中华民国", sources: ["《读书杂志》第九号，1923年原刊", "顾颉刚编《古史辨》第一册", "崔述《考信录》"], tags: ["古史辨", "层累说", "考信"] }, related: ["cn--1922--c01", "cn--1928--s01"] },
  { id: "cn--1924--p01", track: "cn", year: 1924, yearApprox: false, dim: "politics", weight: 4, title: "国民党第一次全国代表大会", summary: "容共之议定，反帝之宣言出。", detail: { background: "广州六月之变后孙氏改组党务，1923年10月设临时中央执行委员会，《孙文越飞宣言》之约成，苏联之顾问与款械相继而来，共产党员以个人身份加入之议久经往复。", process: "1924年1月20日至30日中国国民党第一次全国代表大会开于广州高等师范之礼堂，孙中山为主席，代表百数十人（人数各省所报不同），李大钊、毛泽东、谭平山等共产党员预会并当选执行、监察之职；大会通过《中国国民党第一次全国代表大会宣言》，重释三民主义为对外废除不平等条约、对内平民得享民权之义，并确定容共与联俄之实（宣言起草与最后审定之人，各说不同）。", impact: "一代之党势自是转为以宣传与民众为具，党部、青年与农工之组训同时而兴，黄埔之立即其后第一事；而两党之同处一党，界说与党纲之不相能，1925年之区分案、1927年之分裂皆伏于此会之宣言与组织。", figures: ["孙中山", "胡汉民", "廖仲恺", "李大钊"], place: "广州", state: "中华民国（广州）", sources: ["《中国国民党第一、二次全国代表大会会议史料》", "《孙中山全集》第九卷", "《申报》1924年原载"], tags: ["国民党一大", "容共", "宣言"] }, related: ["cn--1924--i01", "cn--1923--p01"] },
  { id: "cn--1924--i01", track: "cn", year: 1924, yearApprox: false, dim: "institution", weight: 4, title: "黄埔军官学校之设", summary: "开学于长洲，教习与政治并重。", detail: { background: "革命倚客军而屡败，孙氏乃有自练党员之军之议，苏联之教官与器械既至，1924年5月中国国民党陆军军官学校成立于广州对岸之长洲岛。", process: "1924年5月校定，6月16日开学，孙中山到校宣布训词，蒋中正任校长，廖仲恺任党代表，何应钦、王柏龄等分掌教务、教育，政治部以戴季陶、周恩来先后主之（1924年冬周恩来任主任）；课程以军事与党义并重，设党代表与政治部之制，学生以第一、二期为基，分校与训练团继设于长沙、武汉、南昌诸地（第一期之录取与在校之数，校史诸说略有出入）。", impact: "一校自是成民国军政之根源，其出身与师生之谊变而为派系之目，1926年之北伐军与1927年以后之国民革命军皆以是为骨干；而党代表、政治部之法为军中有党部与政工之始，此后国共两军之制度同源而异流，论近代军政关系者必始于此校。", figures: ["蒋中正", "廖仲恺", "周恩来", "何应钦"], place: "广州黄埔长洲", state: "中华民国（广州）", sources: ["《黄埔军校史料》，广东革命历史博物馆编", "《申报》1924年原载"], tags: ["黄埔军校", "党代表", "政治部"] }, related: ["cn--1924--p01", "cn--1926--m01"] },
  { id: "cn--1924--p02", track: "cn", year: 1924, yearApprox: false, dim: "politics", weight: 3, title: "北京之变与溥仪出宫", summary: "冯军回师，清室之尊号以废。", detail: { background: "第二次直奉之师起于1924年9月，吴佩孚之兵尽在山海，直系之第三军总司令冯玉祥自热河间道回师，直局遂溃。", process: "1924年10月23日冯玉祥之军回入北京，围总统府而逐曹锟，黄郛摄行内阁之事；11月5日京畿卫戍之队入故宫，溥仪及其眷属迁出，同日公布《修正清室优待条件》，凡五条，废除皇帝之尊号而以民国待总统之礼相接，宫内之府产悉归公有而宗庙、陵寝许其奉守；11月24日段祺瑞入京任临时执政，孙氏应召北上（出宫之日与所订条数，报馆与后来之册略同）。", impact: "皇帝之号自是始尽，宫禁之财物与典籍归于公有，1925年故宫博物院之设即因此；而北京之局不出于法统而出于兵，段氏之临时执政与孙氏之国民会议主张并争名器，1925、1926年之北方政争与奉、直之复合皆由此启。", figures: ["冯玉祥", "溥仪", "黄郛", "段祺瑞"], place: "北京", state: "中华民国", sources: ["《（民国）政府公报》1924年11月", "《修正清室优待条件》1924年令文", "《申报》1924年原载"], tags: ["北京政变", "溥仪出宫", "临时执政"] }, related: ["cn--1924--m01", "cn--1925--i01"] },
  { id: "cn--1924--m01", track: "cn", year: 1924, yearApprox: false, dim: "military", weight: 2, title: "第二次直奉之役", summary: "山海相持，奉军入关而直军崩。", detail: { background: "1922年之败奉人志在报复，浙江之任改易而江苏之局亦动，直、奉相持于长城之内外，两军之筹饷皆以盐税与借款为继。", process: "1924年9月15日直、奉开衅，山海关、九门口之线相持月余，伤亡与失踪之数直、奉各报互异；10月北京之变作，直军第三军回师，前线之军遂溃，吴佩孚自海道南归，奉军入关而张作霖之威北被于直、鲁，齐燮元在江苏之军亦以是解（卢永祥旋亦去苏，江苏之局再变）。", impact: "一战而直系之根本去，奉、冯共拥临时执政，而两军之不相能自是益显，1925年冬郭松龄之反奉与1926年之直、奉复合对冯皆本于此；北方之督军更置如传舍，论北洋之亡者以此役为终始之界。", figures: ["张作霖", "吴佩孚", "冯玉祥", "郭松龄"], place: "山海关、九门口、北京", state: "中华民国", sources: ["《（民国）陆军部档案》", "《大公报》1924年原载", "郭廷以《近代中国史纲》"], tags: ["第二次直奉战争", "山海关", "奉军入关"] }, related: ["cn--1922--p02", "cn--1924--p02"] },
  { id: "cn--1925--p01", track: "cn", year: 1925, yearApprox: false, dim: "politics", weight: 5, title: "孙中山之逝世", summary: "总理殁于北京行辕，遗嘱以革命未成为属词。", detail: { background: "孙中山北上应段祺瑞之召，1924年12月抵北京，主开国民会议以谋统一，而善后会议之制已定，孙氏忧愤，入春病不能兴，医言肝病。", process: "1925年3月12日上午孙中山殁于北京铁狮子胡同行辕，年六十；前有遗嘱一篇，由汪精卫执笔、孙氏口授而签名，以「革命尚未成功，同志仍须努力」为属词，另有家事遗嘱；北京中央公园行吊，广州开会追悼，灵柩暂厝西山碧云寺，至1929年6月奉安于南京紫金山（治丧之处与奉安之年月，党国文献与报馆所记同）。", impact: "一人之死而广州、北京两方皆失其名器，此后之广州政府以汪精卫、蒋中正分主党务与军务，1926、1927年之交党中正统之争即缘总理事席之谁属；而北上宣言以废约、召集国民会议为号，遂为此后十年在野诸团体共同之口号。", figures: ["孙中山", "汪精卫", "宋庆龄", "段祺瑞"], place: "北京、广州、南京紫金山", state: "中华民国", sources: ["《孙中山全集》第十一卷", "《（民国）政府公报》1925年3月", "《申报》1925年原载"], tags: ["孙中山逝世", "遗嘱", "奉安"] }, related: ["cn--1924--p02", "cn--1925--p05"] },
  { id: "cn--1925--p02", track: "cn", year: 1925, yearApprox: false, dim: "politics", weight: 5, title: "五卅之案", summary: "租界捕房开枪，三罢之风遍于全国。", detail: { background: "1925年春上海日商纱厂之工人争执不已，5月15日厂中职员枪杀顾正红于日商内外棉七厂，狱成而各界之请愿、讲演继之，公共租界以扰乱治安为戒。", process: "1925年5月30日学生、工人在南京路一带讲演，老闸捕房捕人，众聚索释，巡捕开枪，死伤之数官方之报与工会、报馆所记互异；6月1日上海总工会成立，工、商、学同行罢工、罢市、罢课，公共租界戒严，各国驻军续至；北京、广州、汉口、青岛诸城相继示威，六月间案之波及者二十余省（死亡之名数自数十至百余，说者不一，未有确数）。", impact: "此案使治外法权、租界与驻兵皆为公共之问题，收回运动由此而急，1926、1927年之交汉口、九江租界之收回即其余波；工商之联合与总商会之立场分化亦为人所论，论者谓五卅为五四之后第二次全国风潮，而此次之主力在工不在学生。", figures: ["顾正红", "刘少奇", "李立三", "蔡和森"], place: "上海公共租界", state: "中华民国", sources: ["《五卅运动》资料丛刊，上海人民出版社", "《申报》1925年原载", "《（民国）政府公报》1925年6月"], tags: ["五卅惨案", "三罢", "租界"] }, related: ["cn--1925--p03", "cn--1927--p04"] },
  { id: "cn--1925--p03", track: "cn", year: 1925, yearApprox: false, dim: "politics", weight: 3, title: "省港之罢工", summary: "香港罢工而封锁，沙基一夜又见血。", detail: { background: "五卅之耗至粤，港、粤之工与商素相倚，省港之工人以罢工为对外之举，广州政府亦欲借之以收租界之利。", process: "1925年6月19日香港华工总同盟罢工，返广州者数万，23日广州工、农、兵、学在沙基示威，自沙面之英、法兵开枪，死数十人（沙基之数目各册异辞）；省港罢工委员会立，苏兆征、邓中夏主之，设检查与封锁之制，断香港之供给，凡十六个月，至1926年10月国民政府以北伐改策，乃停封锁而渐复工。", impact: "封锁一举使香港之转口与市面大损，亦使广州得自抽饷源以济军，1926年以后之财政半赖此；华工自是成一有组织的团体，1927年广州之变与1929年中东路之事，其工运线索皆由此出；论以罢工为外交之具者，以此为最著之成效。", figures: ["苏兆征", "邓中夏", "汪精卫"], place: "香港、广州沙基", state: "英属香港、中华民国（广州）", sources: ["《（民国）政府公报》广东1925年", "《申报》1925年原载", "中共中央党史研究室《中国共产党历史》第一卷"], tags: ["省港罢工", "封锁香港", "沙基惨案"] }, related: ["cn--1925--p02", "cn--1926--m01"] },
  { id: "cn--1925--p04", track: "cn", year: 1925, yearApprox: false, dim: "politics", weight: 3, title: "廖仲恺之刺", summary: "党部门前中枪，三驾马车之势由成。", detail: { background: "廖仲恺主粤之财政与农工，左右党、政、军三方，与黄埔之将校及加伦之顾问相善，胡汉民、许崇智各与其人有隙，暗杀之警数见。", process: "1925年8月20日廖仲恺出国民党中央党部之门遇刺，中枪数处，越日而殂；国民政府设特别委员会查办，蒋中正、许崇智、谭延闿任之，旋以涉案之名解除许崇智之兵柄，许走上海，胡汉民奉使赴苏俄，粤局之权由是分归汪、蒋（供词与涉案之人，党国之记录与后来之记述出入甚大）。", impact: "廖死而汪、蒋并立于党、军两途，1926年之中山舰案与1927年之宁、汉相峙皆可上溯于是；农工之部与省港之款无人继其总持，政府之财政遂专倚军政，论广州时期党政军之分合者以是案为关键。", figures: ["廖仲恺", "蒋中正", "许崇智", "谭延闿"], place: "广州", state: "中华民国（广州国民政府）", sources: ["《（民国）政府公报》广州1925年8月", "《申报》1925年8月原载", "尚明轩《廖仲恺》"], tags: ["廖仲恺案", "特别委员会", "粤局"] }, related: ["cn--1925--p05", "cn--1926--p01"] },
  { id: "cn--1925--p05", track: "cn", year: 1925, yearApprox: false, dim: "politics", weight: 3, title: "广州国民政府之改组", summary: "大元帅府撤，委员会合党与政府。", detail: { background: "大元帅府之制以一人总揽，饷、械与外交皆凭私谊，滇、桂诸军各驻其地，党员在政府任事者无统一之名分，改组之议起于总理事后。", process: "1925年7月1日国民政府在广州成立，采委员合议制，汪精卫为主席，同日军事委员会立，所属诸军一律改称国民革命军（先是六个军之额，后来递增至十数个军）；9月广州全省统一军令、财政之案行，10月两广联合之局成，11月谭延闿、程潜、李宗仁、李济深各率其军受编（改组令文与军队编额之先后，公报与军册互有详略）。", impact: "以党治国之制自此有府、有委、有军之三合，1926年之北伐与1927年之南京、武汉分争皆由是府发之；而委员会之制至宁、汉合而后变，训政之制即本其经验而扩大，论民国以党统政之始者每举是年。", figures: ["汪精卫", "胡汉民", "谭延闿", "廖仲恺"], place: "广州", state: "中华民国（广州国民政府）", sources: ["《（民国）政府公报》广州1925年7月", "《中国国民党历次代表大会及中央全会资料》", "郭廷以《近代中国史纲》"], tags: ["国民政府", "委员制", "国民革命军"] }, related: ["cn--1925--p04", "cn--1926--m01"] },
  { id: "cn--1925--e01", track: "cn", year: 1925, yearApprox: false, dim: "economy", weight: 4, title: "关税与法权之两会议", summary: "十三国会商加税，五使调查领事裁判。", detail: { background: "华盛顿之会许中国议加附税，并约各国派员调查领事裁判权之实况，北京政府以财政支绌欲借二五附税与裁厘相交换，而国内战事方亟。", process: "1925年10月26日关税特别会议开于北京，与会者十四国（国数与列名先后，部档与报馆所载小异），议许中国自若干年起增收附加税，条件是裁废厘金与实行条约之范围；同时法权调查会议（各国之司法委员）自1925年冬来华历查各埠，1926年冬以其报告致之北京，谓中国之法律、司法须先从改良，而后可以议废。", impact: "二五附税之案因北方之兵与国会议之未终而无成行，其议至1928、1929年改约而后见诸实行；法权之报则成中国要求改约之反面证据，1929年以后废约之运动与1943年新约之成皆以两会议之结果为其公论之起点。", figures: ["顾维钧", "颜惠庆", "施肇基"], place: "北京", state: "中华民国", sources: ["关税特别会议文件，见《近代中国外交史资料辑要》中卷", "法权调查会议之报告译本", "海关《十年报告（1922—1931）》"], tags: ["关税会议", "法权调查", "附税"] }, related: ["cn--1922--p01", "cn--1928--p02"] },
  { id: "cn--1925--i01", track: "cn", year: 1925, yearApprox: false, dim: "institution", weight: 3, title: "故宫博物院之立", summary: "宫禁之财归公，十月初十开院。", detail: { background: "1924年冬清室优待条件既修正，宫禁之物须有点查、保管与公开陈列之任，善后之会由此设，学者与报馆争之尤力。", process: "1925年10月10日故宫博物院成立于北京紫禁城之内廷，以易中庭、外廷之殿宇为陈列之所，点查之册陆续印行，古物、图书、文献分馆保管（点查所得器物、图书之总数，馆册与后来清点之目互有出入）；1930年以后院务改隶于国民政府，1933年以兵事而有文物南迁之举。", impact: "宫禁之私产自是归之公，皇家之收藏始为全国可游、可考之所，近世博物馆与档案、图书馆之业因是并兴；而点查与保管之责使后来之文物迁徙与追索有册可稽，论战时文物南迁与战后之归还在案者，皆以本院之册为张本。", figures: ["李石曾", "易培基", "马衡"], place: "北京", state: "中华民国", sources: ["《故宫物品点查报告》1925年排印本", "《故宫博物院月刊》原载", "《（民国）政府公报》1925年10月"], tags: ["故宫博物院", "点查", "公产"] }, related: ["cn--1924--p02", "cn--1937--e01"] },
  { id: "cn--1925--c01", track: "cn", year: 1925, yearApprox: false, dim: "culture", weight: 2, title: "清华国学研究院之立", summary: "四导师聚于清华，讲席不主一宗。", detail: { background: "清华以庚子赔款之余设校，旧制偏于西学之预备，吴宓、梁启超等议立研究院以整国故而用新法，乃有四大导师之名。", process: "1925年秋清华学校设国学研究院，聘王国维、梁启超、赵元任为导师，李济以讲师任考古之讲（陈寅恪以1926年夏至同任导师），讲席不以一宗为主，而以读书、著述与田野、图书之用相勉，学生之额不满百，毕业者数十人（导师之次序与招生之数，院册与记述诸家微异）。", impact: "此院只四年而止，然其诸生多成一代之学人，古史、音韵、考古与西北之史地皆蒙其泽，1928年中央研究院历史语言研究所之规模与其相袭；论新学术之由大学转归研究所者，每以清华国学院为始例。", figures: ["王国维", "梁启超", "赵元任", "吴宓"], place: "北京清华园", state: "中华民国", sources: ["《清华学堂章程》与研究院记录，见清华校史资料", "《王国维全集》", "《清华周刊》1925—1927年原载"], tags: ["清华国学研究院", "导师制", "庚款"] }, related: ["cn--1925--i01", "cn--1928--s01"] },
  { id: "cn--1925--c02", track: "cn", year: 1925, yearApprox: false, dim: "culture", weight: 2, title: "《生活》周刊之刊", summary: "职业社出一周刊，后十年而成大众之文。", detail: { background: "中华职业教育社以职业与修养之文自给，周刊之体便宜于市肆传布，1925年秋其刊始行于上海。", process: "1925年10月《生活》周刊创刊于上海，初由职业社诸人任之，1926年邹韬奋接主编，改论社会、政治之文稿为读者通信与问题之讨论，发行额由数千而递增至十万份以上（销数逐年之报，社册与广告商所估互异），1932年更设生活书店以行书刊。", impact: "由职业一隅之书而为全国之读物，此刊定此后三十年之杂志体式，即小事、通信与短论相间；邹韬奋所立之读者服务与发行办法亦为民营出版之规范，1930年代救亡之声浪得此种刊物而速，论大众传媒与政见之相推者每取为例。", figures: ["邹韬奋", "黄炎培", "胡愈之"], place: "上海", state: "中华民国", sources: ["《生活》周刊1925年起原刊", "邹韬奋《经历》", "《（民国）上海出版史料》"], tags: ["生活周刊", "邹韬奋", "期刊"] }, related: ["cn--1925--c01", "cn--1931--p01"] },
  { id: "cn--1925--m01", track: "cn", year: 1925, yearApprox: false, dim: "military", weight: 2, title: "郭松龄之反奉", summary: "一军回戈向沈阳，日本出面而事败。", detail: { background: "郭松龄本东北第三军之将，从冯玉祥有密约，恶张作霖再用兵于关内，1925年冬其师驻滦州、迁安之间，反命之谋既定。", process: "1925年11月下旬郭松龄在滦州起兵反奉，号东北国民军，沿北宁路而北，奉军前线之师多不应，12月初逼近新民、沈阳；日本以南满之守备队出兵于铁路附属地，禁军队之往来，12月下旬郭军粮弹不继而溃，郭氏夫妇在辽中一带被获遇害（奉、郭两军之胜负与日本干涉之时日，中、外所记出入较大）。", impact: "一战而奉军之元气未伤，张作霖自是倚日以自固，1926年与冯、直之构兵更急；郭死而东北军中之异见者不复自立，其部下多人后随杨宇霆、张学良之更张而见用，论奉系之存亡与日本之关系者以此案为最明之证。", figures: ["郭松龄", "张作霖", "冯玉祥", "杨宇霆"], place: "滦州、新民、辽中", state: "中华民国", sources: ["《（民国）奉天军档》", "《申报》1925年12月原载", "《大公报》1925年原载"], tags: ["郭松龄反奉", "滦州", "日本干涉"] }, related: ["cn--1924--m01", "cn--1926--p03"] },
  { id: "cn--1926--p01", track: "cn", year: 1926, yearApprox: false, dim: "politics", weight: 4, title: "中山舰之变", summary: "一舰夜动，三月初广州戒严。", detail: { background: "国民政府与苏联顾问之共事日久，黄埔之党军以政治部为枢纽，关于两党之界说与军队之隶属者屡见讼端，永丰舰改名中山舰在1925年春。", process: "1926年3月18日中山舰自广州驶赴黄埔，19、20日之间传闻甚异，20日清晨广州城戒严，中山舰被缴械，李之龙被捕，各署之共产党员与苏联顾问之住处同时受监视，工人纠察队之械被收；苏联方面自莫斯科遣布勃诺夫使团来粤，最后以顾问让步、共产党人辞职为了案（三月十八、十九两日之命令与往返，档案与记述诸本互殊，未有定说）。", impact: "一役而黄埔与政治部、党与苏联顾问之势分，5月中央执行委员会通过整理党务之案，共产党员在国民党组织部长官之额与任免之程序皆有明限；论者谓中山舰之案实为1927年四月十二日之张本，而北方之舆论犹未知两党之隙已至此。", figures: ["蒋中正", "李之龙", "汪精卫", "鲍罗廷"], place: "广州、黄埔", state: "中华民国（广州国民政府）", sources: ["《（民国）政府公报》广州1926年3月", "《申报》1926年3月原载", "《鲍罗廷在中国》之报告与日记"], tags: ["中山舰事件", "整理党务案", "广州戒严"] }, related: ["cn--1925--p04", "cn--1927--p01"] },
  { id: "cn--1926--p02", track: "cn", year: 1926, yearApprox: false, dim: "politics", weight: 3, title: "三一八之案", summary: "执政府前开枪，京师学生死数十人。", detail: { background: "1926年春大沽口之冲突起，冯军与奉军相持，日舰介入而奉军败退，各国以天津之约相责，北京群众以废除八国之牒为号，连日请愿于执政府之前。", process: "1926年3月18日北京各校学生与市民在天安门开会后赴铁狮子胡同执政府请愿，卫队开枪并以刺刀，死者数十人、伤者百倍，名数自数十至二百余不等，执政府以暴徒阑入为辞（死伤之名与卫队受命之由，官报与后来之记录全不相合）；清华之朱自清、鲁迅之杂文同时纪其事。", impact: "一纸之官报不能掩众口，执政府自是不复有可信之名，4月而段祺瑞去位，北方之政府更由张、吴与顾维钧之手；此后京师学生之请愿与纪念皆以是案为标，论民国政府之自弃其民者每以是日为最暗之例。", figures: ["段祺瑞", "朱自清", "杨德群", "刘和珍"], place: "北京铁狮子胡同", state: "中华民国", sources: ["《（民国）政府公报》1926年3月", "《申报》1926年3月原载", "《晨报》1926年原载"], tags: ["三一八惨案", "执政府", "学生请愿"] }, related: ["cn--1926--p03", "cn--1925--p01"] },
  { id: "cn--1926--m01", track: "cn", year: 1926, yearApprox: false, dim: "military", weight: 5, title: "北伐之誓师", summary: "七月广州誓师，十月而武昌下。", detail: { background: "两广既一，唐生智在湘求援，吴佩孚之兵南下，孙传芳在中立与助直之间摇摆，广州政府以三个月内定湖湘为约。", process: "1926年7月9日国民革命军在广州誓师北伐，蒋中正任总司令，第八、四、六军先入湘；8月下旬第四军之叶挺独立团与第八军破吴军于汀泗桥、贺胜桥，9月6、8日克汉阳、汉口，围武昌两月，10月10日下之；江西之役自9月至11月而孙传芳之众大溃，北伐军之额由十万而骤增，沿途之农工与商会多为之导（两军之员额与伤亡，军册、报馆与各方所报互异）。", impact: "半年而长江以定，北京政府之号令不出河北，1927年之宁、汉对峙与国民政府之北迁皆由是起；而军事之速亦使党务、政治随之不及整理，1927年春之工农运动、租界之交涉与党、军之相倾，皆以是年之胜为其所从生。", figures: ["蒋中正", "叶挺", "唐生智", "加伦"], place: "广州、长沙、汀泗桥、武昌", state: "中华民国（广州国民政府）", sources: ["《北伐战争》资料，见中国人民政治协商会议全国委员会文史资料选辑", "《（民国）政府公报》广州1926年", "郭廷以《近代中国史纲》"], tags: ["北伐", "汀泗桥", "武昌之克"] }, related: ["cn--1926--p01", "cn--1927--p01"] },
  { id: "cn--1926--p03", track: "cn", year: 1926, yearApprox: false, dim: "politics", weight: 2, title: "执政府之废与北方之局", summary: "段祺瑞去位，北京之府无所承。", detail: { background: "三一八之案后京师之舆论不容于执政府，奉、两方各以兵相临，冯玉祥之国民军在西北，直、鲁之军退于南方，段氏之令不出城。", process: "1926年4月20日段祺瑞通电去临时执政之任，执政府废，北京之政由摄阁与诸督分任之，胡惟德、顾维钧先后署其事，皆仰奉天之命；秋，张作霖、吴佩孚之军入关，张宗昌据山东，1927年6月张作霖乃组织军政府而任安国军大元帅（摄阁之先后与任事之月日，公报与报馆所记小异）。", impact: "中枢既废而内阁徒存，北洋之统绪至是名义俱尽，1928年之易帜遂无所承；北方之兵各以其省为守，税、路与外款之权散于督军之手，论北京政府之末路者以1926年四五月为其断，而外交之文书仍由一二总长撑持数年。", figures: ["段祺瑞", "顾维钧", "张作霖", "吴佩孚"], place: "北京、天津、沈阳", state: "中华民国（北京）", sources: ["《（民国）政府公报》1926年4月", "《晨报》1926年原载", "郭廷以《近代中国史纲》"], tags: ["执政府", "摄阁", "北洋末路"] }, related: ["cn--1926--p02", "cn--1928--p03"] },
  { id: "cn--1927--p01", track: "cn", year: 1927, yearApprox: false, dim: "politics", weight: 5, title: "四月十二日之变", summary: "上海缴工纠之械，两党由是分途。", detail: { background: "北伐军至江西而鄂、湘之工农运动大起，上海之工人纠察队已两度响应，国民党内关于共产分子之去留自中山舰案后日烈，蒋氏与列强之交涉亦渐成。", process: "1927年4月12日晨，上海之军队与青帮之众骤缴工人纠察队之械，13日闸北开会抗议，宝山路一带军队开枪，死伤数百（是旬被杀、被捕之名数自数百至数千，官电、工会与报馆之册互异，未有确数），汪寿华、陈延年、赵世炎诸人死之；15日广州、南京与两湖同时清党，各地之工会、农会封印者相属。", impact: "两党自是分国、分军、分民而相攻，此后十年之苏区与围剿之局以此日为始；而上海之商会、报馆与帮会之参预，使此后之百货与工运同受其制，1927年以后之上海市社会局与工会之组织皆循是而来，论国民革命之分裂者无不如是写。", figures: ["蒋中正", "汪寿华", "陈独秀", "李济深"], place: "上海、广州、南京", state: "中华民国", sources: ["《申报》1927年4月原载", "《（民国）政府公报》南京1927年", "中共中央党史研究室《中国共产党历史》第一卷"], tags: ["四一二", "清党", "工人纠察队"] }, related: ["cn--1926--p01", "cn--1927--p02"] },
  { id: "cn--1927--p02", track: "cn", year: 1927, yearApprox: false, dim: "politics", weight: 4, title: "七一五与宁汉之合", summary: "武汉分共，八月而宁、汉同为一府。", detail: { background: "四一二月后两府各称中央，唐生智之军与张发奎之众相持于湘、鄂之间，共产分子在武汉政府内犹居各部，冯玉祥自郑州会议后倾向南京。", process: "1927年7月15日武汉中央常务委员会决议分共，共产党员退出政府，苏联顾问先后北归（鲍罗廷于7月下旬离鄂）；8月7日汉口开会，定土地革命与武装抵抗之方针；9月宁、汉合流而两府之中央合一，11月广州另立中央之议亦不成，12月桂系与唐生智之战起，武汉之府实已无所施其令。", impact: "分共而后国民党始成一党，而党内之派系又分数统，汪、蒋之进退与桂系之盛衰皆在此一年内；对共产党而言，八七之议由城市而转向乡村与军队，1927年秋以后之起义与苏区之设皆本此决，论十年内战之起者以七一五与其会议为转折。", figures: ["汪精卫", "唐生智", "张发奎", "瞿秋白"], place: "武汉、南京、上海", state: "中华民国", sources: ["《中国国民党历次代表大会及中央全会资料》", "《中共中央文件选集》第三册，中央档案馆编", "《申报》1927年原载"], tags: ["七一五分共", "八七会议", "宁汉合流"] }, related: ["cn--1927--p01", "cn--1927--m01"] },
  { id: "cn--1927--p03", track: "cn", year: 1927, yearApprox: false, dim: "politics", weight: 3, title: "南京政府之成立", summary: "四月十八定都，一府与武汉并立。", detail: { background: "北伐军之重心自粤而移于江，蒋氏之军事与财政皆以沪、宁为根，4月上海之商界与列强领事各有成说，迁都之议遂决。", process: "1927年4月18日国民政府在南京成立，通电定首都，以胡汉民、伍朝枢、王宠惠诸人分主党政、外交与法制，军事委员会与总司令之署相继而设；5月政府明令清党，各省政府之任次第举行，而北方之张作霖以军政府拒之，中国自此同时有三府并立之局（就职与令文之日，公报与报馆有先后之差）。", impact: "南京既为府，则外交之承认、财政之关余与债款之整理皆以是为对象，1928、1929年改约与收回税源之运动由是发之；而党务之实权早分于军事与财经之两手，1928年之训政、1931年之约法与1947年之宪法，其制度之端皆在此岁之府中定其规模。", figures: ["胡汉民", "王宠惠", "蔡元培", "张静江"], place: "南京", state: "中华民国", sources: ["《（民国）政府公报》南京1927年", "《申报》1927年4月原载", "郭廷以《近代中国史纲》"], tags: ["南京政府", "定都", "清党令"] }, related: ["cn--1927--p02", "cn--1928--p02"] },
  { id: "cn--1927--p04", track: "cn", year: 1927, yearApprox: false, dim: "politics", weight: 4, title: "汉口九江租界之收回", summary: "汉口、九江两英界于一月内接收。", detail: { background: "五卅之后长江一带之反英情绪未衰，北伐军入鄂而工会之权日重，英人于汉口、九江之界防以兵力，冲突之数起。", process: "1927年1月3日汉口英租界前有聚众之案，英兵鸣枪，4、5日国民政府外交部派员接收界内之警察与行政；6日九江之英界以同一法收回（汉、浔两地之接交手续与月日，部报与英档略有先后）；2月19日外部与英使订交还之约，3月15日设汉口英租界管理局。", impact: "租界之收回自是始于英，而条约以交接手续为之，华员与警制次第更置，1929、1930年天津、镇江诸处之租界亦以是例而归；论者谓此役之所以能成，半由武汉之民与工会，半由英、日之不相为用，而收回之后市政之权、界内之债务与外侨产业之讼，则历十年而未了。", figures: ["陈友仁", "徐谦", "孙科"], place: "汉口、九江", state: "中华民国（武汉国民政府）", sources: ["《近代中国外交史资料辑要》中卷所收英约", "《申报》1927年1月原载", "海关《十年报告（1922—1931）》"], tags: ["收回租界", "汉口英界", "九江英界"] }, related: ["cn--1925--p02", "cn--1927--p03"] },
  { id: "cn--1927--m01", track: "cn", year: 1927, yearApprox: false, dim: "military", weight: 5, title: "南昌之役", summary: "八月一日举兵于豫章，十月而潮汕失。", detail: { background: "武汉分共之后，叶挺之十一军、贺龙之二十军尚在张发奎麾下，张已就粤任，二军之将领与共产分子有西行会合之谋，南昌之守备单弱。", process: "1927年8月1日周恩来、贺龙、叶挺、朱德、刘伯承等在南昌举兵，所部约二万人（各册所记之数自万余至二万不等），先歼城内之守军，旋以中国国民党革命委员会为名；8月3日起南行入赣边，9月下旬三河坝、汕头之役迭败，主力散，朱德、陈毅收其残部数千转走湘南，贺、叶由海道赴香港。", impact: "一役之败而其军之建制与政治机关之制俱存，1928年春朱、毛会于井冈山，红军之始由此为断，八一自是定为建军之节；南昌之政府以叛名其众而加兵于湘、赣，论国共两军之分立与其后十年之战，以是日为其始点。", figures: ["周恩来", "贺龙", "叶挺", "朱德"], place: "南昌、三河坝、汕头", state: "中华民国", sources: ["《八七会议》前后之文件，中央档案馆编", "《申报》1927年8月原载", "中共中央党史研究室《中国共产党历史》第一卷"], tags: ["南昌起义", "三河坝", "革命委员会"] }, related: ["cn--1927--p02", "cn--1927--m02"] },
  { id: "cn--1927--m02", track: "cn", year: 1927, yearApprox: false, dim: "military", weight: 3, title: "秋收与广州之役", summary: "湘赣上山，十二月广州又举事。", detail: { background: "八七之议定暴动之方针，湘、鄂、赣边之农军以秋收为号，广东之农会与工人纠察队亦经三河坝之败后潜聚，张发奎与桂系相逼于粤。", process: "1927年9月9日后湘赣边界之工农革命军起，攻长沙不克，毛泽东率其余部上井冈山（10月），立哨与给养之所；海陆丰之农军于9、10月两度举事，11月设县之苏维埃；12月11日张太雷、叶挺、叶剑英等在广州举事，称广州公社，三日而桂、张之军入城，死焚者甚众（广州之被杀者，官方与报馆之数互异）。", impact: "由城市而山，由暴动而据点，此数月中道路之变实为红军与根据地之始；广州之败则使党在粤之工人组织大损，此后十年之广东反为党务与农运之边缘，而张发奎之部旋与桂系不合，1928年之粤局屡为军事委员会所筹。", figures: ["毛泽东", "张太雷", "叶剑英", "彭湃"], place: "湘赣边井冈山、海陆丰、广州", state: "中华民国", sources: ["《井冈山革命根据地》党史资料，中共党史资料出版社", "《申报》1927年12月原载", "中共中央党史研究室《中国共产党历史》第一卷"], tags: ["秋收起义", "井冈山", "广州公社"] }, related: ["cn--1927--m01", "cn--1928--p01"] },
  { id: "cn--1927--i01", track: "cn", year: 1927, yearApprox: false, dim: "institution", weight: 2, title: "晓庄之乡村师范", summary: "都门外设师范，以教村童兼治村事。", detail: { background: "平民教育之运自1923年行于都市，陶行知以为不合于农，谓欲化农民先农化，与同仁筹设试验之校于南京城外。", process: "1927年3月试验乡村师范学校开学于南京晓庄，陶行知任校长，以中心小学之环绕为学制，学生自营住所、耕种与村落之卫生、自卫诸事，以教学做合一为纲；数年内扩充至数十村，1930年4月因粤、汉之案被封闭而改组（校舍、田地与学员之数，校刊之册与后来记述略异）。", impact: "晓庄之制定为后来乡村师范与乡治之张本，1930年代乡村建设诸团体多有其门人，教、富、强、卫并举之说即由此而著；论民国教育之由城市而向农村者，以此校为一转关，其封闭亦示教育运动与地方军政之不可分。", figures: ["陶行知", "孟禄", "朱经农"], place: "南京晓庄", state: "中华民国", sources: ["《陶行知全集》第一卷", "《第一次中国教育年鉴》1934年", "《申报》1930年原载"], tags: ["晓庄学校", "乡村教育", "教学做合一"] }, related: ["cn--1920--i01", "cn--1930--i01"] },
  { id: "cn--1927--x01", track: "cn", year: 1927, yearApprox: false, dim: "explore", weight: 2, title: "中瑞西北之考察", summary: "一约而中外国同行，自阴山而至塔里木。", detail: { background: "瑞典人斯文·赫定数度入新、蒙测路，前此之考察多赖外款与外方之权，1926年其请再入而北京学界拒之，乃有成约之议。", process: "1926年秋中国学术团体协会与赫定订约，合组西北科学考察团，中外同人各半，徐旭生为中方团长，1927年5月由包头出发，分道考察内蒙、新疆、甘肃之气象、地质、史地与考古，凡六七年，居延之汉简、楼兰之遗文与罗布淖尔之水道皆出其途（所得文物、标本之目与年代之先后，团报与后来之报告互有详略）。", impact: "此约为近世中国不许外人独行考察之始，主权与学术并计，此后之中外合考皆取其例；所得汉简与地理、气候之文，为后来史学与地质之据，而航测之图亦归政府参用，论科学考察之国家化者每以此团为首例。", figures: ["斯文·赫定", "徐旭生", "黄文弼"], place: "包头、居延、塔里木", state: "中华民国", sources: ["《西北科学考察团之报告》，见中瑞合刊之考察丛书", "黄文弼《罗布淖尔考古记》", "《申报》1927—1933年原载"], tags: ["西北考察", "居延汉简", "考察主权"] }, related: ["cn--1922--s01", "cn--1927--i01"] },
  { id: "cn--1927--e01", track: "cn", year: 1927, yearApprox: false, dim: "economy", weight: 3, title: "武汉金融之停兑", summary: "中央银行纸票不行，市面闭户数旬。", detail: { background: "武汉既为政府之府，军费专倚印票与筹款，湘、鄂之农会又禁谷米之出境，商业之信俱摇，上海、汉口之汇兑日紧。", process: "1927年3、4月间武汉中央银行之纸币信用渐坠，4月政府令停止兑现，市肆闭户，现金外逃于沪、港，汉口之洋行与钱庄各闭其账（币券之行用额与比价之落，银行、海关与报馆之册出入极大）；7月以后政府以清查、公债与禁运之令相救，而票值迄未复，12月以后武汉金融全倚南京之整理。", impact: "一府之财政以军事为归而失信于市，其影响及于两湖之谷米、纱布与农工之薪，此例后为1935年法币与1948年金圆券之讨论所屡引；论纸币与政权之相须者，以为武汉之停兑实示一国之银行不可恃兵而立，亦为宁、汉分府财政各殊之最明证。", figures: ["宋子文", "张静江"], place: "汉口、长沙", state: "中华民国（武汉国民政府）", sources: ["海关《十年报告（1922—1931）》", "《申报》1927年原载", "《上海银行周报》1927年原刊"], tags: ["停兑", "纸币", "战时财政"] }, related: ["cn--1927--p02", "cn--1929--e01"] },
  { id: "cn--1927--f01", track: "cn", year: 1927, yearApprox: false, dim: "figure", weight: 2, title: "王国维之死", summary: "昆明湖一纵，遗书以世变为词。", detail: { background: "王国维自日本还国，以清华国学研究院之讲席为任，于甲骨、金石与词曲之学皆有成说，而心中旧室与北局之逼，忧疑日积。", process: "1927年6月2日（旧历五月十三）王国维自颐和园鱼跃矶入昆明湖死，年五十一，遗书有「五十之年，只欠一死，经此世变，义无再辱」之语；1929年葬于清华园之北，其遗稿与碑文为同门所辑（所以死者之说，有罗振玉之词与后来诸家之推，迄无定论）。", impact: "一死而旧学之统与学术之变并成议论，陈寅恪铭其碑曰「独立之精神，自由之思想」，遂为后来论学者与政争者引用之常语；甲骨与古史之学由是失其一师，而1928年以后殷墟之发掘与古器物之研究，其法与其人之学相表里，论近代学术之承继者每及之。", figures: ["王国维", "罗振玉", "陈寅恪", "梁启超"], place: "北京颐和园、清华园", state: "中华民国", sources: ["《王静安先生遗书》", "陈寅恪《王静安先生遗书序》", "《申报》1927年6月原载"], tags: ["王国维", "遗书", "学者"] }, related: ["cn--1925--c01", "cn--1928--s01"] },
  { id: "cn--1928--p01", track: "cn", year: 1928, yearApprox: false, dim: "politics", weight: 3, title: "二次北伐与济南之案", summary: "五三之日济南见血，北伐绕道而前。", detail: { background: "宁、汉既合，冯、阎之军皆受编，奉军退出京、津而张作霖北归，日本以在满蒙之权益恐为北伐所侵，欲阻河北之兵，乃先由青岛驻兵于济南。", process: "1928年4月国民革命军二次北伐，5月1日入济南，3日军与日兵冲突，日兵杀中国军民，山东交涉公署蔡公时及署员被戕，7日日本提出条件五款，9、10两日攻城，国军绕道北上，6月初张作霖死而济南犹为日兵所驻（死伤之名自数百至数千，日方之报与中方所记全不相合），至1929年3月始交还。", impact: "济南一案使北伐之成带有对外之创，1929年3月济南交还而日兵撤，而1928年以后之对日情绪与1931年之局面由此相接；论北伐之所以成者，谓其不以胜战而以奉军之自溃与张氏之死，论对日之所以败者，又谓此役实为其渐。", figures: ["蒋中正", "蔡公时", "何应钦", "张宗昌"], place: "济南、北京、太原", state: "中华民国", sources: ["王芸生《六十年来中国与日本》", "《申报》1928年5月原载", "《（民国）政府公报》1928年"], tags: ["二次北伐", "五三惨案", "蔡公时"] }, related: ["cn--1926--m01", "cn--1928--m01"] },
  { id: "cn--1928--m01", track: "cn", year: 1928, yearApprox: false, dim: "military", weight: 3, title: "皇姑屯之爆", summary: "专车过奉天北郊，大帅受创而殂。", detail: { background: "北伐之师而进，京、津之奉军次第退，张作霖决意出关，日方以其不肯签字而怨已深，关东军之参谋独主其谋。", process: "1928年6月4日晨张作霖乘专车由北京还奉天，抵皇姑屯车站之东，日本守备队预安之药爆发，车毁身受重伤，归署而逝（同日沈阳之日本守备队向城郊进兵而未动）；奉天当局秘其丧，悬大帅之像于节署，至6月中旬张学良间道自北京还，7月初就任东三省保安司令而局始定。", impact: "一爆而奉系之主更，张学良自是以反日之意为内政之据，1928年底之易帜与1929年中东路之擅废皆由是出；而关东军之独断成例，1931年九月之夜亦循其轨，论九一八之背景者必上及皇姑屯，且日本军阀与文官政府之不相俟于中国事，自是愈显。", figures: ["张作霖", "张学良", "杨宇霆", "河本大作"], place: "奉天皇屯、沈阳", state: "中华民国", sources: ["《（民国）奉天军档》", "《大公报》1928年6月原载", "王芸生《六十年来中国与日本》"], tags: ["皇姑屯事件", "秘丧", "张作霖之死"] }, related: ["cn--1928--p03", "cn--1925--m01"] },
  { id: "cn--1928--p02", track: "cn", year: 1928, yearApprox: false, dim: "politics", weight: 4, title: "关税自主之改约", summary: "七月新税则行，八国先认中国之税。", detail: { background: "华盛顿之会许中国议加附税而条件和未就，南京政府既成，以改订新约为对外之纲领，美、英、法、意、比、丹、荷、葡、瑞典诸国各有旧约之当改。", process: "1928年7月7日公布进口税则，划货品为数等，华货与外货之税并增；7月25日中美率先订新约，承认中国之关税自主，接着以德、意、英、法、葡、荷、比、丹、瑞典诸国次第订约或照会承认（约文之繁简与税率之差，外部之册与各国之蓝皮报告书互异，而二五附税之制至是渐废）。", impact: "关税之额自是跃为财政之柱，1929、1931、1933年税则数有增加，中央之岁入半赖此，而外货入口为之少杀，日、英之商屡起诉讼；论者许改约为不战而收权利，又病其未能并废租界、驻兵与内河之特权，自是此后对外之争转于法权、航政与租地数端。", figures: ["宋子文", "王正廷", "蔡廷干"], place: "南京、上海", state: "中华民国", sources: ["《中华民国条约汇编》所收1928年新约", "《（民国）政府公报》1928年7月", "海关《十年报告（1922—1931）》"], tags: ["关税自主", "改订新约", "税则"] }, related: ["cn--1925--e01", "cn--1929--e01"] },
  { id: "cn--1928--p03", track: "cn", year: 1928, yearApprox: false, dim: "politics", weight: 4, title: "东北易帜", summary: "尾月而悬青天白日之旗，关外归一。", detail: { background: "皇姑屯之后张学良新立，日本以满蒙之新约相促，杨宇霆、常荫槐主与南京相抗，关内之府则遣使劝其早定，奉、阎之兵又环相伺。", process: "1928年12月29日张学良、张作相、万福麟等通电，东三省及热河同日去五色旗而悬青天白日满地红之旗，服从南京政府，改东北保安委员会为东北边防军司令长官公署，以张学良任之；1929年1月杨宇霆、常荫槐在帅署被杀，热河、吉林之任次第更置（易帜之通电日与各省接防之先后，公报与报馆所记微异）。", impact: "北伐之局以是一纸电文而终，民国之域形式复归于一，而日本在满蒙之权益与南满铁路之驻兵一仍其旧，1931年之役即自是生；东北之军政自此半隶于中央而半自成系统，1928年以后之华北与西北皆循此例，论统一之有其名无其实者必及易帜。", figures: ["张学良", "张作相", "杨宇霆", "王正廷"], place: "沈阳、南京、北平", state: "中华民国", sources: ["《（民国）政府公报》1928年12月", "《文史资料选辑》所收易帜诸回忆", "《大公报》1928年12月原载"], tags: ["东北易帜", "统一", "奉系"] }, related: ["cn--1928--m01", "cn--1929--p01"] },
  { id: "cn--1928--s01", track: "cn", year: 1928, yearApprox: false, dim: "science", weight: 3, title: "中央研究院之立与殷墟之发", summary: "国家设研院于沪，秋始掘安阳之墟。", detail: { background: "北大与诸研究所之积习在于讲授而疏于创造，蔡元培主教育会议，以研究机关立于政府之侧为当，傅斯年、顾颉刚诸人各主其一。", process: "1928年中央研究院成立于南京，蔡元培任院长；其历史语言研究所先于3月在广州立所，傅斯年主之，10月董作宾首次发掘安阳殷墟之小屯，至1937年凡十五度发掘；地质、气象、物理、化学、工程诸所与静生生物调查之学亦先后布置（历次发掘之坑数与所得甲骨、器物之目，所内报告之册具有次第）。", impact: "殷墟之发掘使甲骨、铜器与遗址互证，商代之信始由地下而立，1923年以来层累之说至是得其一新对手，史语所自是为全国考古之中枢；研究院之设又定此后国家科学之制，其所属之台、所虽经迁徙，学者与毕业生仍相继不辍，李四光、翁文灏、竺可桢皆由此途。", figures: ["蔡元培", "傅斯年", "董作宾", "李济"], place: "南京、广州、安阳殷墟", state: "中华民国", sources: ["《中央研究院院务报告》1928年起", "《殷墟发掘报告》，中央研究院历史语言研究所", "《申报》1928年原载"], tags: ["中央研究院", "殷墟发掘", "研究所"] }, related: ["cn--1922--s01", "cn--1927--f01"] },
  { id: "cn--1929--p01", track: "cn", year: 1929, yearApprox: false, dim: "politics", weight: 3, title: "中东路之役", summary: "东北擅收路权，苏军两路来犯。", detail: { background: "中东铁路本中、苏合办，1928年底易帜之后，东北当局以路权与共产之宣传为两病，7月乃派员查禁各地之署与栈，逐苏方之人员。", process: "1929年7月10日东北当局以兵收中东铁路之权，免苏方之局长，查封领事署、商号与学社，捕侨民；苏维埃政府先以照会相责，旋断交，8、9两月以海军与航空之队由黑河、满洲里、同江三路并进，东北军之防线屡破，同江之航队几尽，11月以后满洲里、扎赉诺尔之线又破；12月22日双城子之议成，伯力之定约仍复合办之旧（两军之胜负与伤亡，苏方、东北各报全不相合）。", impact: "一役而东北之军失其可信之力，日本窥之益明，论者以九一八之易成与此役之败状有关；于内则张学良以胜败未名而得统一之功，苏方亦暂敛其在新、满之活动，中东路之产权与合办之制至1933年售于伪满而后绝。", figures: ["张学良", "莫德惠", "加伦"], place: "满洲里、同江、伯力", state: "中华民国", sources: ["《中东路事件》之交涉文件，见《近代史料》之辑刊", "《（民国）政府公报》1929年", "《申报》1929年原载"], tags: ["中东路事件", "中苏冲突", "伯力议"] }, related: ["cn--1928--p02", "cn--1929--e01"] },
  { id: "cn--1929--e01", track: "cn", year: 1929, yearApprox: false, dim: "economy", weight: 2, title: "世界恐慌之及于中国", summary: "纽约之风潮东来，丝价、银价并坠。", detail: { background: "1929年以前美国之市面与信用俱溢，10月纽约股票骤跌，各国之金融随之，中国之生丝、茶叶、豆饼与钨、锑之属皆以是失其外市场。", process: "1929年10月后外洋之银价、丝价同时而落，华南之茧与湖州之丝农损失尤重，上海之出口货值连续三年递减（递减之数自三成至五成，海关与商会之册互异，且多折价之差），1931、1932年各国以金本位之故竞售其货于中国，入口之超入由是益大，钱庄之拆借与地契之质当相继而困。", impact: "恐慌使中国之农村金融与世界之市面初次密系，其后之废两改元、法币与统制外汇皆以是役为其鉴，美国1934年购银之案更使白银流出，论1930年代币制改革之所以急者，每上及1929年之秋；而丝、茶之败亦使民族工业由纺织而重归面粉、卷烟与化学。", figures: ["徐新六", "马寅初", "钱永铭"], place: "上海、广州、无锡", state: "中华民国", sources: ["海关《十年报告（1922—1931）》与1929—1933年贸易报告", "《上海银行周报》1929年原刊", "《申报》1929年原载"], tags: ["世界恐慌", "出口之减", "银价"] }, related: ["cn--1928--p01", "cn--1930--m01"] },
  { id: "cn--1929--x05", track: "cn", year: 1929, yearApprox: false, dim: "explore", weight: 4, title: "周口店之头盖骨", summary: "十二月二日得北京猿人完骨一具。", detail: { background: "周口店之掘自1921、1923两度启其端，1926年以后由中美之款与两机关合任其事，而主权与出土之归属屡经勘辨。", process: "1929年12月2日（日期两说）中国地质调查所与协和医学院合作之发掘在北平西南周口店第一地点得北京猿人之第一个头盖骨，主持现场者为裴文中，德日进司其鉴定；1936年贾兰坡续得其二、三完骨，石器与用火之迹并出于其层（出土之日与层位之名，所内报告与后来之记略有出入）。", impact: "北京猿人之名由是为世界古人类学所据，周口店成中国境内最重要之人类化石地，其层位、石器与用火之证为1930年代以后旧石器与人类学研究立一基准；1937年兵起后标本之箱运与失踪，为后来数十年之悬案。", figures: ["裴文中","德日进","贾兰坡"], place: "北平西南周口店（今北京房山）", state: "中华民国", sources: ["《中国古生物志》丙种周口店诸册（Palaeontologia Sinica）","《中国地质调查所汇报》1929—1936年","《申报》1929年12月原载"], tags: ["北京猿人","周口店","头盖骨"] }, related: ["cn--1928--s01", "cn--1929--x06"] },
  { id: "cn--1929--x06", track: "cn", year: 1929, yearApprox: false, dim: "explore", weight: 2, title: "广汉之玉器与三星堆", summary: "田父淘沟得玉一堆，古蜀之器由是见。", detail: { background: "成都平原东北之广汉当马牧河之滨，其地之遗器旧为田亩所及而人不知贵。", process: "1929年春广汉县三星镇之农民燕道诚淘沟得玉石一堆，自是流于市；华西边疆研究学会之美国馆员葛维汉闻而调查，1934年地方与大学之机关往其地发掘（出土之器数与其地之范围，当时之报与后来之报告多寡互异），其地后以三星堆之名显。", impact: "一坑之玉使成都平原之古蜀遗存入于学界，1930年代之调查与后来之发掘相承而为西南青铜、玉器系统之端；初出之器多归私家与外国之藏，为民国文物外流之案又添一事。", figures: ["燕道诚","葛维汉"], place: "四川广汉三星镇（今三星堆遗址一带）", state: "中华民国", sources: ["《华西边疆研究学会杂志》1930年代原载","《考古学报》所收广汉遗址之调查发掘报告","《四川省志·文物志》"], tags: ["三星堆","玉器","广汉"] }, related: ["cn--1929--x05"] },
  { id: "cn--1930--m01", track: "cn", year: 1930, yearApprox: false, dim: "military", weight: 4, title: "中原大战", summary: "豫、鲁千里之场，六月而北局定。", detail: { background: "编遣之议起于1929年正月，桂、冯、阎各以其军为轻，汪精卫之改组派与西山会议派合而倡扩大会议，1930年春反者之约成，兵集于津浦、平汉之线。", process: "1930年4月阎锡山、冯玉祥、李宗仁诸军与中央军相拒于中原，战事沿平汉、津浦、胶东之线展转数月，晋、西北之军与何应钦、刘峙、朱绍良诸路相持，9月18日张学良电请罢兵并派军入关，反者之局遂溃，11月阎、冯各解其军（各方之兵额与死伤，中央、晋、西北三方之册出入极大，说者至以数十万为言）。", impact: "一战而地方之军权尽归中央之整编，而张学良以入关之劳得华北之政，1931年之对日与石友三之再叛皆余波也；中原之民以兵灾与旱、蝗相仍，1930年代之豫、鲁村落的破落即自是起，论民国统一之卒成于兵者以此役为最后一战。", figures: ["阎锡山", "冯玉祥", "张学良", "李宗仁"], place: "开封、济南、太原、北平", state: "中华民国", sources: ["《（民国）陆军作战经过》之档册", "《大公报》1930年原载", "《申报》1930年原载"], tags: ["中原大战", "编遣", "东北军入关"] }, related: ["cn--1929--p01", "cn--1930--p01"] },
  { id: "cn--1930--p01", track: "cn", year: 1930, yearApprox: false, dim: "politics", weight: 3, title: "第一次围剿之役", summary: "赣南之军却，中央之议由是定。", detail: { background: "1929年春朱德、毛泽东之军入赣、闽之边，1930年以军团之制聚于赣西，中央与地方之党部尚主会攻城市之说，而富田之案起于其冬。", process: "1930年11月至1931年1月中央军以九重围剿赣南，毛、朱之军退却诱敌，12月龙冈之役歼其一师，获其师长张辉瓒；1931年5月第二次之役、7月至9月第三次之役皆以退却诱敌，莲塘、东固、高兴圩诸处连战而诸路军退（两役之歼获与兵员之数，双方之报互异，皆逾其实）。", impact: "以少数之众胜众而据一隅，红军之有根据地与游击、运动之配合至是成例，中央之路线自是渐移于军队之中，1931年冬之府与1933年之失策皆伏于此；江西之民在两兵之间受其征发与封击，后来之调查多言其苦，论苏区与围剿之相循者以此三年为始。", figures: ["毛泽东", "朱德", "鲁涤平", "张辉瓒"], place: "江西吉安、龙冈、宁都", state: "中华民国", sources: ["《中共中央文件选集》第七册，中央档案馆编", "《（民国）政府公报》1931年", "《申报》1930—1931年原载"], tags: ["围剿", "龙冈之役", "赣南苏区"] }, related: ["cn--1931--p01", "cn--1930--m01"] },
  { id: "cn--1930--c01", track: "cn", year: 1930, yearApprox: false, dim: "culture", weight: 3, title: "左翼作家联盟之立", summary: "一联盟立于上海，文学遂有阵营。", detail: { background: "创造社、太阳社与鲁迅之笔墨相非者三年，共产党员之在文界者奉国际之新令，主作家之联合与理论之一致，乃有筹备之约。", process: "1930年3月2日中国左翼作家联盟成立于上海，鲁迅、夏衍、冯乃超、田汉等与焉，定纲领与理论之目，继有左翼社会科学家、美学家、戏剧家、音乐家诸联盟，中国自由运动大同盟与左翼文化总同盟又相继而立，《萌芽》《拓荒者》《文学月报》为其刊（发起人盟员之数与先后，盟内诸家之回忆互异）。", impact: "自是文界之分以阵营而不易泯，1930年代之小说、戏剧与翻译多受其影响，毛泽东1940年之文论亦本其经验而扩大；而一联盟之立又使作家入党、入政为常，1935年后之文统由是成，论近代文学与政党组织之合流者以左联为关键之点。", figures: ["鲁迅", "夏衍", "冯乃超", "周扬"], place: "上海", state: "中华民国", sources: ["《萌芽月刊》1930年原刊", "《申报》1930年3月原载", "《“左联”回忆录》，中国社会科学出版社"], tags: ["左联", "革命文学", "上海"] }, related: ["cn--1921--c01", "cn--1937--p01"] },
  { id: "cn--1930--i01", track: "cn", year: 1930, yearApprox: false, dim: "institution", weight: 2, title: "乡村建设之运动", summary: "一在定县，一在邹平，以教救穷。", detail: { background: "平民教育之运自1923年行于都市，晏阳初以为必入县乃可施，梁漱溟则以文化之失为根本，两途各设其区。", process: "1926年晏阳初以平教之试验移于河北定县，1929年平教会之总会亦移驻其地，办生计、教育、卫生、公民四目，推行村学、乡学与表证之农户；1931年梁漱溟在山东邹平办乡村建设研究院，以乡学、村学合政与教，至1933年前后全国言乡建之团体与设处岁有增加（其数依会议与刊物之统计，多寡不一，无从归并为一说）。", impact: "乡建之运以不倚兵而倚教，故其成在试验而难在推广，定县之卫生与识字、邹平乡学之组织皆为后来者所取法，而1935年以后之政令与兵役皆用其方法；论中国近世治乡之策不入于保甲即入于合作者，每以此两区为其例，1937年兵起而后两区俱废。", figures: ["晏阳初", "梁漱溟", "陶行知"], place: "河北定县、山东邹平", state: "中华民国", sources: ["晏阳初《定县实验区之经验》之报告", "梁漱溟《乡村建设理论》", "《（民国）内政公报》1933年"], tags: ["乡村建设", "定县", "邹平"] }, related: ["cn--1927--i01", "cn--1931--d01"] },
  { id: "cn--1931--p01", track: "cn", year: 1931, yearApprox: false, dim: "politics", weight: 5, title: "九一八之变", summary: "一夜而沈阳失，四月而三省尽。", detail: { background: "日本在满之军以路警与权益自任，1931年夏间之案数起，中村之事、万宝山之垦与韩人之案皆为借口，关东军之参谋先定以兵解决之议。", process: "1931年9月18日夜，南满铁路之柳条湖段爆破，关东军遂攻沈阳北大营与城，东北军以不抵抗之令故，19日晨沈阳陷；未几长春、吉林次第入于日兵之手，11月下旬齐齐哈尔、锦州以空城失，1932年2月哈尔滨陷，数月之间辽、吉、黑三省尽（驻军之进退与不抵抗之命所自出，奉令者、报馆与日方之档各为其说，迄无定论）。", impact: "三省之军械、工厂、仓粮与铁路忽为日本所有，国际联盟之调查与退会之议由是起，1932、1933年之交国联之报告终无所施，而日本以此定其满蒙之方针；国内自是言救亡与言剿共之先后成为一讼，1935、1936年之学生运动与西安之变皆推原于此役，论八年之战者以此夜为首日。", figures: ["张学良", "板垣征四郎", "李顿", "王以哲"], place: "沈阳北大营、长春、锦州", state: "中华民国", sources: ["《申报》1931年9月原载", "《国联调查团报告书》中文译本", "《大公报》1931年9月原载"], tags: ["九一八", "不抵抗", "东北沦陷"] }, related: ["cn--1937--m01", "cn--1931--d01"] },
  { id: "cn--1931--d01", track: "cn", year: 1931, yearApprox: false, dim: "disaster", weight: 4, title: "江淮大水", summary: "百数十县同时告灾，苏、皖之野成泽。", detail: { background: "1930年之中原兵起，堤防久不修，是年入夏江、汉、淮、运并霖，七、八月水势大至，中游之省以舟为居。", process: "1931年七八月间长江、淮河、运河之水同时盛涨，皖、苏、赣、鄂、湘、豫、鲁诸省告灾，灾县之数多至百数十，江苏一省且几无完区；死亡之数自十余万至数十万不等，说者多寡悬殊，水次与淹没之顷亦各册异辞（政府之灾务局、赈务委员会、各省之册报与后来统计之推估，口径本不相同）；1932年春以工代赈之堤工始，华洋义赈与各国之赈团并募于市。", impact: "此次之灾使全国之经济大绌，米、麦入口与白银外流相逼，1932、1933年市面之疲与田赋之欠半缘于此，中央之赈务机关自是稍立规模，1935年之水灾、1938年之黄河改道皆沿其议；论民国荒政与水利之不能相离者，每以江淮大水为其最显之例。", figures: ["熊希龄", "庄得之", "许世英"], place: "江苏、安徽、江西、湖北", state: "中华民国", sources: ["《（民国）内政部救济水灾委员会报告》1931年", "《申报》1931年原载", "华洋义赈会筹赈报告"], tags: ["江淮大水", "灾县", "以工代赈"] }, related: ["cn--1917--d01", "cn--1920--d01"] },
  { id: "cn--1932--m05", track: "cn", year: 1932, yearApprox: false, dim: "military", weight: 3, title: "一二八淞沪之役", summary: "一月二十八日夜闸北开战，血战三月。", detail: { background: "东北既失，平津之议南移，上海之日本驻军以护侨与查货为名数与华民相犯，第一·二八之夜衅遂启。", process: "1932年1月28日夜日军由虹口向闸北进犯，第十九路军（蔡廷锴、蒋光鼐、戴戟）拒战，全城响应，上海之工人别组义勇之队；2月下旬日军总攻庙行、江湾、蕴藻浜之线，血战数日；3月1日日军自浏河登陆，侧背受逼，十九路军移驻第二线；是年上海之民物损失与两军之伤亡，中、日两方及后来诸书所记差异极大。", impact: "此役为中国军在全国既战以后第一次之都市坚守，全国之捐款与报章之纪载相属于途，而上海之防自此有约所束；4月29日虹口公园之爆，白川义则受创毙命，行凶者为朝鲜人尹奉吉，此案与是役同为1930年代中日关系之枢。", figures: ["蔡廷锴","蒋光鼐","戴戟","盐泽幸一","白川义则"], place: "上海闸北、庙行、江湾、浏河", state: "中华民国", sources: ["《十九路军淞沪抗战史料》（政协文史资料）","《申报》1932年1—3月原载","日本防卫厅战史室《中国事变陆军作战史》"], tags: ["一二八","淞沪抗战","十九路军"] }, related: ["cn--1932--p05", "cn--1937--m02"] },
  { id: "cn--1932--p05", track: "cn", year: 1932, yearApprox: false, dim: "politics", weight: 3, title: "淞沪停战之协", summary: "五月五日约成，上海之防两受其束。", detail: { background: "战起以后，国联之决议与列强之调停屡言停战，英、美之使驻沪相促，而日方亦欲以其兵北顾。", process: "1932年5月5日中日两方代表在上海立停战之协，定两军停止冲突、日军退回一月二十八日以前之位置，中国之军队则不得在划定之线内常驻，而日本之海军陆战队仍得依旧约驻于租界之区（协文之别字与换文之先后，两方所刻略有详略之异）；同年十九路军奉调入闽。", impact: "一约而上海之防有空，国联之调查与决议成具文，1933年日本退会之局由此；而十九路军之入闽与1933年之闽变相接，停战之约遂不能留其在沪之兵，1937年八月之役即在此约所束之地上重开。", figures: ["汪精卫","宋子文","重光葵"], place: "上海、南京、日内瓦", state: "中华民国", sources: ["王铁崖编《中外旧约章汇编》第三册所收淞沪停战协定","《（民国）政府公报》1932年5月","《申报》1932年5月原载"], tags: ["淞沪停战协定","国联调停","十九路军"] }, related: ["cn--1932--m05"] },
  { id: "cn--1932--p06", track: "cn", year: 1932, yearApprox: false, dim: "politics", weight: 3, title: "中国民权保障同盟之立", summary: "十二月上海立会，以狱政与政治犯为事。", detail: { background: "既战以后之上海，言论与人身之禁并严，文化界与实业界之数人欲以公开之会为其救。", process: "1932年12月中国民权保障同盟在上海成立，宋庆龄、蔡元培、杨铨、鲁迅、胡适诸人任其事，史沫特莱预议，会中以释放政治犯、废除会审公堂之遗制与视察监狱为三目，1933年春数营营救之事并上书请愿。", impact: "此为1930年代唯一公开活动之民权团体，其营救与调查之文多存于当时之报册；1933年6月杨铨遇刺以后，同盟之活动遂辍，1936年之救国会与1940年代之宪政请愿皆引其次第为先例。", figures: ["宋庆龄","蔡元培","杨铨","鲁迅"], place: "上海", state: "中华民国", sources: ["《中国民权保障同盟史料》（上海档案馆藏档案之辑刊）","《申报》1932年12月原载","《蔡元培全集》"], tags: ["民权保障同盟","政治犯","狱政"] }, related: ["cn--1933--f05"] },
  { id: "cn--1933--m05", track: "cn", year: 1933, yearApprox: false, dim: "military", weight: 3, title: "长城诸口之守", summary: "榆关至多伦，一年之间冀察热相持。", detail: { background: "热河既于1933年春入于日军之手，山海关与长城诸隘为平津之屏，华北之军始受命而守。", process: "1933年1月3日榆关之役起，何柱国一旅拒战；3月犯喜峰口、古北口、冷口诸隘，第二十九军以白刃当炮，中央军徐庭瑶、关麟征诸部继进，相持逾月；5月下旬冯玉祥、吉鸿昌、方振武在张家口立察哈尔民众抗日同盟军，7月初复多伦，旋为南京方面所迫而解（此军之起讫与其部众之数，各记互异）。", impact: "长城诸口之守为全国既战以后正面之第一御侮战，报章与国联皆以是重估中国军之气；而塘沽之约成，冀东之门渐启，1935年之局即自是出。", figures: ["宋哲元","何柱国","冯玉祥","吉鸿昌"], place: "河北山海关、喜峰口、古北口、冷口，察哈尔多伦", state: "中华民国", sources: ["《长城抗战》（政协文史资料选辑）","《中华民国史》","日本防卫厅战史室《中国事变陆军作战史》"], tags: ["长城抗战","喜峰口","察哈尔同盟军"] }, related: ["cn--1933--p05", "cn--1932--p05"] },
  { id: "cn--1933--p05", track: "cn", year: 1933, yearApprox: false, dim: "politics", weight: 3, title: "塘沽之协定", summary: "五月三十一日停战之约成于塘沽。", detail: { background: "长城诸口既不能久守，而平津在日军飞机炮火之地，政府以停战为便。", process: "1933年5月31日熊斌与冈村宁次在塘沽立停战之协，定两军停战、中国之军队不越宁河、芦台、平泉、喜峰口之线而东，其北为非战区，由是冀东之县不驻中国之军（约文与所划之线，日方之报与中方之公布略有详略之异，其未经全文公布一节，两方所记相同）。", impact: "此约划出冀东之不驻兵区，1935年之冀东防共自治政府与1937年之作战皆资此隙；停战之约亦使中央军得入河北而地方之局又变，1935年冀察之制为其结局。", figures: ["熊斌","冈村宁次","何应钦"], place: "河北塘沽、北平", state: "中华民国", sources: ["王铁崖编《中外旧约章汇编》第三册","《（民国）政府公报》1933年6月","《申报》1933年5月原载"], tags: ["塘沽协定","非战区","冀东"] }, related: ["cn--1933--m05", "cn--1935--p05"] },
  { id: "cn--1933--p06", track: "cn", year: 1933, yearApprox: false, dim: "politics", weight: 3, title: "闽省之变与人民革命政府", summary: "十一月二十日福州立府，十九路军与之俱。", detail: { background: "十九路军自上海之役调闽，与南京以饷与权相持，而反蒋之议在粤桂、在上海者日相凑。", process: "1933年11月20日蔡廷锴、蒋光鼐、陈铭枢、李济深等在福州立中华共和国人民革命政府，定年号而以「对外取消不平等之约、对内许人民之权利、计口授田、联共反蒋抗日」为纲，分闽境为数省（四省之名与分区之界诸记不一）；南京方面以空军与入闽之军应之，1934年1月福州不守，李济深走香港，陈铭枢出洋。", impact: "一月余之政权以兵败而终，而十九路军自此不复为一枝自立之众，其将领多主抗日与反蒋之议至1936年以后不绝；人民革命政府之纲领与1930年代之「第三条路」之议相接，为1945年以后民主党派之兴留其一源。", figures: ["李济深","陈铭枢","蔡廷锴","蒋光鼐"], place: "福建福州、泉州", state: "中华民国（闽省政权）", sources: ["《（民国）政府公报》1933年12月","《文史资料选辑》所收福建事变诸回忆","《剑桥中华民国史》"], tags: ["福建事变","人民革命政府","十九路军"] }, related: ["cn--1932--p05"] },
  { id: "cn--1933--s05", track: "cn", year: 1933, yearApprox: false, dim: "science", weight: 3, title: "侯德榜《制碱》之书", summary: "英文成书刊于纽约，索尔维之法不复为秘。", detail: { background: "永利碱厂自1926年在塘沽出碱以后，与英商卜内门之竞争数载不解，制碱之细节向为欧厂所讳。", process: "1932年至1933年间侯德榜以英文撰《制碱》（Manufacture of Soda Ash: Pure and Applied）成，1933年在纽约刊行，具述氨碱之法与华厂之实况；范旭东主永利之厂与碱业之会，其「红三角」牌之碱由是得有对外之争据（成书与刊版之年，诸记有1932、1933两异）。", impact: "此书成而东亚之制碱术自立其说，中国化学工程之学始有对外之文本；1937年以后永利诸厂西迁入川，五通桥、永利之新厂皆用其法，论近代化工之自主者每以侯德榜为首出。", figures: ["侯德榜","范旭东"], place: "天津塘沽、美国纽约", state: "中华民国", sources: ["侯德榜《制碱》（1933年纽约版）","《中国近代工业史资料》第二辑","《天津工业史资料》"], tags: ["制碱","永利","侯德榜"] }, related: ["cn--1937--e01"] },
  { id: "cn--1933--f05", track: "cn", year: 1933, yearApprox: false, dim: "figure", weight: 3, title: "杨杏佛之遇刺", summary: "六月十八日上海亚尔培路见刺。", detail: { background: "中国民权保障同盟自1933年春数营救政治犯、请视察监狱，南京方面以其为患，报章之责言相寻。", process: "1933年6月18日中央研究院总干事杨铨（杏佛）自沪寓出门，在亚尔培路遇刺死，年五十；同日其子受伤，会中诸人闻耗会葬，宋庆龄、蔡元培、鲁迅皆往（主使与执行者之名，政府之公报与报章、同盟方面之吊文全不相合）。", impact: "一死而公开之民权组织不复振，而蔡元培之祭文与鲁迅之杂文由是存学术人与政权相抗之一事；1936年之救国会狱与1940年代之宪政请求，皆追念及此。", figures: ["杨铨","蔡元培","鲁迅","宋庆龄"], place: "上海", state: "中华民国", sources: ["《申报》1933年6月原载","《蔡元培全集》所收祭文","《鲁迅书信集》（1933年诸函）"], tags: ["杨杏佛","民权保障同盟","暗杀"] }, related: ["cn--1932--p06"] },
  { id: "cn--1934--m05", track: "cn", year: 1934, yearApprox: false, dim: "military", weight: 4, title: "中央红军之长行", summary: "十月出赣南，湘江一役损失过半。", detail: { background: "1933年10月起国军以堡垒、公路与封锁之法进剿中央苏区，广昌之役红军当正面之冲而受创。", process: "1934年7月寻淮洲、粟裕率红七军团北上为抗日先遣队；10月中下旬中央红军主力由赣南于都、信丰之间突围西行，11月至12月初在湘桂边界之湘江受国军南北合击，损失过半（出发之日、随行之员与沿途之减额，各方所记多寡大异）；1935年1月占遵义。", impact: "中央苏区自此不入红军之手，而长行之道由赣而湘、黔、滇、川、康、甘，历时一年余，为中共军政史上最大之迁动；此役之中途变计与遵义之会相为表里，1935年以后之路线即在此间定之。", figures: ["博古","李德","周恩来","朱德","彭德怀"], place: "江西于都、信丰，湖南、广西边界之湘江", state: "中国共产党（中央苏区）", sources: ["《中国共产党历史》第一卷","《毛泽东年谱（1893—1949）》","《中国人民解放军战史》"], tags: ["长征","湘江","第五次围剿"] }, related: ["cn--1935--m05"] },
  { id: "cn--1934--c05", track: "cn", year: 1934, yearApprox: false, dim: "culture", weight: 3, title: "大众语之讨论", summary: "文言可兴与否，上海诸刊争及大众之语。", detail: { background: "白话之制既定于1920年，1934年春夏之间上海忽有尊文言、倡「本位文化」之议，学者报馆相与辩之。", process: "1934年上海诸刊物就文言与白话之得失为争，继以「大众语」立讨论之的，陈望道、胡愈之、叶绍钧、陈子展与鲁迅诸人先后作文，主以民众口头之语为文、以拉丁化之新文字助其普及；同年9月《太白》半月刊创刊，为其议之机关之一（论争之起讫与诸文之先后，报册所载互有详略）。", impact: "白话之制至是由书面之通用进为大众之语之议，1935年以后之拉丁化运动与1940年代延安之文艺大众化皆承其题；而本年之文言复兴论亦为1930年代后期「国文」政策之张本。", figures: ["陈望道","鲁迅","胡愈之","叶绍钧"], place: "上海", state: "中华民国", sources: ["《申报·自由谈》1934年原载","《太白》创刊号（1934年9月）","《鲁迅全集》第六卷所收诸文"], tags: ["大众语","白话文","文言复兴"] }, related: ["cn--1920--i01", "cn--1917--c01"] },
  { id: "cn--1934--a05", track: "cn", year: 1934, yearApprox: false, dim: "art", weight: 3, title: "《渔光曲》之映与参展", summary: "六月首映于上海，翌年获奖于莫斯科。", detail: { background: "电影自1920年代末有有声之制，上海之联华影业公司以写实之片自异于旧派之戏。", process: "1934年6月联华之《渔光曲》在上海首映，蔡楚生编导，王人美、韩兰根主之，以渔民之子与租界之贫为事，其主题歌遍传于市；1935年在莫斯科之国际电影展览会得荣誉奖，为华语片国际得名之始（获奖之名目与年次，中、苏两方之记载略异）。", impact: "连映之日数与捐款之额使制片家知写实之有市，1930年代中叶之电影高潮由是而兴；此片与其人之去取为1949年以后之电影体制所承，论华语片之参展外国者以此为首。", figures: ["蔡楚生","王人美","韩兰根"], place: "上海、莫斯科", state: "中华民国", sources: ["《渔光曲》本事与说明书（联华影业公司，1934年）","《申报》1934年原载","《中国电影发展史》"], tags: ["渔光曲","联华影业","电影参展"] }, related: ["cn--1935--a05"] },
  { id: "cn--1934--e05", track: "cn", year: 1934, yearApprox: false, dim: "economy", weight: 3, title: "白银外流与银根之紧", summary: "美国购银而银价骤涨，上海银根先涸。", detail: { background: "中国以银为币，世界银价之低使汇兑久不安；1934年春美国以购银法案自抬其价。", process: "1934年5、6月美国购银之法行，纽约银价骤涨，上海银楼之银条出口大增，华洋银根并紧，市面之物价与地价同落，工商业之亏折相寻；银行数度提准备率而不济，10月政府增银元出口之税，1935年复申禁银出口之令（出口之数与税率之更定，海关册报与财政部之报不一）。", impact: "银荒为1935年法币之改与白银国有之直接缘由，中国之币自是与世界银价脱钩；论1930年代中国经济之转折者，多以美国购银与中国法币为同一事之两面，而1934—1935年之农村与市面之困亦由此出。", figures: ["孔祥熙","张嘉璈"], place: "上海、南京、华盛顿", state: "中华民国", sources: ["海关《十年报告（1932—1941）》","《（民国）中央银行月报》1934年","《申报》1934年原载"], tags: ["白银风潮","购银法案","银根"] }, related: ["cn--1935--e05"] },
  { id: "cn--1935--m05", track: "cn", year: 1935, yearApprox: false, dim: "military", weight: 4, title: "遵义之议", summary: "一月十七日会毕，军政之责为之易人。", detail: { background: "湘江之败后红军之损失过半，行军之方向与指挥之责并起异议，将领多不以为然。", process: "1935年1月15日至17日中共中央在贵州遵义开政治局扩大会议，责第五次反围剿以来军事上之错误，增选毛泽东为政治局常委，取消博古、李德之最高军权（1935年3月复有更置之「三人团」），会中并议红军之去向与川黔滇边之根据（会议之日期、出席与发言之名录，1940年代之回忆与后来查定之册略有出入）。", impact: "遵义之会为中共军政史上最大之一变，毛泽东自此参与最高军政之决策，四渡赤水、北进与1945年之组织皆承此局而来；张闻天代博古之任、军事之责分属数人诸节，各方所记亦有详略之异。", figures: ["毛泽东","博古","周恩来","张闻天"], place: "贵州遵义", state: "中国共产党", sources: ["《遵义会议文献》","《中国共产党历史》第一卷","《毛泽东年谱（1893—1949）》"], tags: ["遵义会议","长征","军事指挥"] }, related: ["cn--1934--m05", "cn--1935--p05"] },
  { id: "cn--1935--p05", track: "cn", year: 1935, yearApprox: false, dim: "politics", weight: 4, title: "华北之局与冀察之制", summary: "梅何之口头解决成，冀东、冀察两政并立。", detail: { background: "塘沽之约以后冀东不驻中国之军，察东之事件又数起，日方以「华北特殊化」为谋。", process: "1935年夏河北、察东之案相继，6、7月间梅津美治郎与何应钦之口头解决成，河北省内之党部与中央军渐移其北（此节未立成文之约，两方后来所载互异）；11月25日殷汝耕在蓟县立冀东防共自治政府，与南京之政令相抗而南京未加削；12月中旬冀察政务委员会成，宋哲元任委员长，冀、察与平、津之政半归地方。", impact: "一年之内华北之政三分：北平之委员会、冀东之伪府与察北之驻兵，1937年七七之役即在此地；而学生之请愿与国民政府之处置亦以是年为大变，论「华北事件」者每合1935年六七月与十一二月两段而观之。", figures: ["宋哲元","殷汝耕","梅津美治郎","何应钦"], place: "北平、天津、河北蓟县、察哈尔", state: "中华民国", sources: ["《（民国）政府公报》1935年11月","《剑桥中华民国史》","《中华民国史》"], tags: ["华北事变","冀东防共自治政府","冀察政务委员会"] }, related: ["cn--1933--p05", "cn--1936--p06"] },
  { id: "cn--1935--e05", track: "cn", year: 1935, yearApprox: false, dim: "economy", weight: 4, title: "法币之改与白银国有", summary: "十一月之令行，三行之钞定为法币。", detail: { background: "1934年银荒之后币制之议在政府与各银行往复经年，英籍财政顾问李滋罗斯于1935年秋来华。", process: "1935年11月上旬政府宣布法币之政策：以中央、中国、交通三行（1936年以后加农民银行）之钞为法币，完粮纳税与交易皆用法币，禁止银元之流通而收其银，白银归于国有；同年以售银与美、英相约为助（收存与售换之额，财政部之册与海关之报不一），翌年行准备之制。", impact: "币制自是统一，1927年以来各行各钞、各省各洋之局为一变，政府得通货以支军费，1937年以后之战时财政即倚此具；而法币之额与准备既不相称，1940年代之通货膨胀与1948年金圆券之败亦自此开其端。", figures: ["孔祥熙","宋子文","贝祖诒"], place: "上海、南京", state: "中华民国", sources: ["《（民国）财政部财政年鉴》","《（民国）政府公报》1935年11月","海关《十年报告（1932—1941）》"], tags: ["法币政策","白银国有","币制改革"] }, related: ["cn--1934--e05", "cn--1948--e01"] },
  { id: "cn--1935--a05", track: "cn", year: 1935, yearApprox: false, dim: "art", weight: 3, title: "聂耳与《义勇军进行曲》", summary: "为电影制歌，一年之后其人已殁。", detail: { background: "1934年以后上海之左翼文化以电影、戏剧与歌曲为最广之途，电通影业与百代唱片相与为用。", process: "1935年电通公司之影片《风云儿女》以田汉作词、聂耳作曲之《义勇军进行曲》为其主题歌，是年春起灌片、传唱于城乡；聂耳（1912年生）于同年7月17日在日本神奈川鹄沼游泳溺死，年二十三（录音与首映之日先后，报册所载微异）。", impact: "一曲成为抗战中传唱最广之歌，其词与谱并为其后数十年之礼仪乐歌所本；田汉、聂耳之交与其人之死，为1930年代上海文化圈之大事，论近代歌曲之政治作用者以聂耳为最要之人之一。", figures: ["聂耳","田汉"], place: "上海、日本鹄沼", state: "中华民国", sources: ["《电通》半月刊（1935年）所收歌曲与本事","《申报》1935年7月原载","《聂耳全集》"], tags: ["义勇军进行曲","聂耳","电影歌曲"] }, related: ["cn--1934--a05", "cn--1938--a01"] },
  { id: "cn--1935--s05", track: "cn", year: 1935, yearApprox: false, dim: "science", weight: 3, title: "气象与地震之观测", summary: "站台布于东南，鹫峰之录始于民国十九年。", detail: { background: "中央研究院气象研究所自1928年立于南京，竺可桢主之，站台之布为其首务；北平西山鹫峰地震台则李善邦任其事。", process: "1935年前后气象研究所在东部与西南布站台百余处（名额逐年有增，具见其所出之年报），日集三时之报以绘天气之图、为旱涝之验；鹫峰地震台自1930年起记录，为中国自建地震台之最先，其记录逐年印送中外之会，至1937年而辍；同年南京、上海诸台各存其册。", impact: "此网与此台为中国近代气象、地震观测之根据，竺可桢关于中国气候之诸文以此为料，1930年代之交报与灾荒之研究皆赖其数；鹫峰之记录为世界之地震年鉴所采，中国之台站制度至1949年以后循其名目而扩。", figures: ["竺可桢","李善邦"], place: "江苏南京、北平西山鹫峰", state: "中华民国", sources: ["中央研究院气象研究所《年报》（1930年代）","《竺可桢全集》","鹫峰地震台记录（1930年代印本）"], tags: ["气象观测","地震台","鹫峰"] }, related: ["cn--1928--s01", "cn--1937--s01"] },
  { id: "cn--1936--p05", track: "cn", year: 1936, yearApprox: false, dim: "politics", weight: 3, title: "两广之变", summary: "六月出师号曰抗日，九月以和议解。", detail: { background: "华北之局日蹙而「剿共」之兵未罢，粤、桂之军与南京以饷权相持经年，西南两委员会之制半独立。", process: "1936年6月，西南政务委员会与粤桂诸将以抗日救国西南联军之名出师北上，陈济棠、李宗仁、白崇禧任之，世称两广事变；7月以后粤汉之线相持，南京以款与任分其部，陈济棠之军多解，9月上旬桂局以和议定（出师之名目、两军之额与粤省之交接，桂方之报与政府公报互异），政府旋许其抗日之请而缓其进兵。", impact: "一事以和解终，而粤省之政自是归中央，南方军事之割据不复成集团；而以抗日为名之争预告1936年12月之局，论两广事变者每以为西安之变先声。", figures: ["陈济棠","李宗仁","白崇禧","蒋介石"], place: "广东、广西、湖南", state: "中华民国", sources: ["《（民国）政府公报》1936年7月","《申报》1936年6月原载","《剑桥中华民国史》"], tags: ["两广事变","西南联军","粤桂"] }, related: ["cn--1936--p06"] },
  { id: "cn--1936--p06", track: "cn", year: 1936, yearApprox: false, dim: "politics", weight: 5, title: "西安之变", summary: "十二月十二日临潼劫留统帅，二十余日而解。", detail: { background: "东北军与第十七路军调在陕「剿共」而屡败，将士思归，张学良自1936年春与共产党以密使往来，延安之谈成于4月。", process: "1936年12月12日西安之兵在临潼劫留蒋介石，张学良、杨虎城电请改组政府、停止内战、一致抗日诸端；南京主战与主和两议并发，12月中下旬宋美龄、宋子文飞陕，中共之周恩来等到西安与会，12月24日前后蒋允停战之语而后可出，25日蒋与张学良同机还南京（通电之文与所允之词，各方所记不相合）。", impact: "一月之间内战之危与对日之机并见，蒋之被扣与还京定1937年春以后两党重开之谈，抗战由是得其时月；而张学良送蒋还京后长期见拘，杨虎城先免其任、后遇害于1949年，西安之案遂为民国政争中诸说并存之大事。", figures: ["张学良","杨虎城","蒋介石","周恩来","宋子文"], place: "陕西西安、临潼", state: "中华民国", sources: ["《（民国）中央日报》1936年12月原载","《西安事变》（政协文史资料选辑）","《毛泽东年谱（1893—1949）》"], tags: ["西安事变","临潼","停止内战"] }, related: ["cn--1937--p01", "cn--1936--p05"] },
  { id: "cn--1937--m01", track: "cn", year: 1937, yearApprox: false, dim: "military", weight: 5, title: "卢沟桥之变与平津之陷", summary: "七月七日夜宛平开战，月余而平津失守。", detail: { background: "自1935年冀察之局成，日军常在平郊演习，第二十九军宋哲元部任平津之防，摩擦之数岁屡见。", process: "1937年7月7日夜，日军在卢沟桥附近演习，日方称失踪一小队兵要求入宛平城搜查，为中国驻军所拒，遂炮击城东与卢沟桥阵地（失踪兵之是否越城，中日两方之记载互异）；8日续攻，9日双方停战地方谈判，而日军续调师团入华北。7月下旬谈判破裂，25日攻廊坊，28日总攻南苑，第二十九军副军长佟麟阁、第一三二师师长赵登禹阵亡，30日天津陷，北平于8月8日入日军之手。", impact: "此为全国抗战开始之点，7月17日蒋介石在庐山发表谈话，定地无分南北、人无分老幼之应战之议；8月以后平汉、津浦两路之兵并动，一隅之事变遂不自限于一隅。", figures: ["宋哲元","佟麟阁","赵登禹","蒋介石"], place: "河北宛平卢沟桥、北平、天津", state: "中华民国", sources: ["日本防卫厅战史室《中国事变陆军作战史》","《中华民国史》第三卷","《中央日报》1937年7月原载"], tags: ["七七事变","卢沟桥","第二十九军"] }, related: ["cn--1937--p01", "cn--1937--p02"] },
  { id: "cn--1937--p01", track: "cn", year: 1937, yearApprox: false, dim: "politics", weight: 4, title: "国共合作之成与红军之改编", summary: "共赴国难之宣言既发，两党重立于共同对日之约。", detail: { background: "西安事变以后两党重开谈判，七七起后改约之期已迫，蒋介石与周恩来在庐山往返数回。", process: "1937年8月下旬国民政府军事委员会下令将陕北红军主力改编为国民革命军第八路军，9月11日改称第十八集团军而习称八路军，朱德、彭德怀任正副总指挥；9月22日中央通讯社发表《中共中央为公布国共合作宣言》，23日蒋介石发表谈话，承认中国共产党之合法地位；10月起南方八省之游击队陆续编为国民革命军陆军新编第四军，叶挺任军长，1938年1月军部设于南昌。", impact: "两党自1927年分裂后重立于共同对日之约，十年内战之局以是转换；而编制、防地、指挥数端之未决者，并为1939年以后两次摩擦之根。", figures: ["蒋介石","毛泽东","周恩来","朱德","叶挺"], place: "南京、庐山、延安", state: "中华民国", sources: ["《中共中央为公布国共合作宣言》（1937年9月22日发表）","《毛泽东年谱（1893—1949）》","《中华民国史》第三卷"], tags: ["第二次国共合作","八路军","新四军"] }, related: ["cn--1937--m01", "cn--1937--p02"] },
  { id: "cn--1937--p02", track: "cn", year: 1937, yearApprox: false, dim: "politics", weight: 3, title: "洛川之议与十大纲领", summary: "陕北定应战之方，减租减息与敌后之策并出。", detail: { background: "红军改编以后，中共须自定其作战与政治之方针，华北之局已不可久守。", process: "1937年8月22日至25日中共中央在陕北洛川举行政治局扩大会议，通过《抗日救国十大纲领》，主全面的全民族抗战，凡减租减息、改良民生、废除一党之训政诸条皆在其内；军事上定独立自主之山地游击战为方针，分兵创建敌后之根据地。", impact: "此后八路军分由雁门、太行而东，晋察冀、晋冀鲁豫诸边区相继而立，敌后之战场与正面之战场并行；纲领中关于政权与减租诸条，与国民党之方针对，为战时两党关系之争端。", figures: ["毛泽东","朱德","彭德怀","林彪"], place: "陕北洛川", state: "中国共产党（陕甘宁边区）", sources: ["《中共中央文件选集》第11册","《毛泽东年谱（1893—1949）》","《中国共产党历史》第一卷"], tags: ["洛川会议","十大纲领","敌后游击"] }, related: ["cn--1937--p01"] },
  { id: "cn--1937--m02", track: "cn", year: 1937, yearApprox: false, dim: "military", weight: 4, title: "淞沪之役", summary: "八月十三日开战，血战三月而上海陷。", detail: { background: "上海为华中华南之门，驻沪日军与保安队久相峙，国民政府欲在首都门户之外主动一战以移其兵锋。", process: "1937年8月9日虹桥机场之变起，13日日军由虹口向闸北进犯，第九集团军等部还击，抗战以来最大之会战由是开始；9月起日军续登陆于宝山、川沙、太仓一带，中国军前后投入数十师，张治中、朱绍良、陈诚相继主持，10月末谢晋元一团守苏州河北之四行仓库；11月5日日军迂回金山卫北岸，防线遂裂，12日中国军西撤，上海除租界外全陷。", impact: "中国军虽败而未溃，得时月以迁工厂、整军队，且使日军由平汉之纵击改为溯江之横击，论者谓此后武汉之守与工厂之内迁皆缘此役；双方兵力与伤亡之数，中日两方及后来诸家统计差异极大。", figures: ["张治中","陈诚","谢晋元","松井石根"], place: "上海闸北、宝山、金山卫", state: "中华民国", sources: ["日本防卫厅战史室《中国事变陆军作战史》","《中华民国史》第三卷","《申报》1937年8月原载"], tags: ["淞沪会战","四行仓库","金山卫"] }, related: ["cn--1937--m03", "cn--1937--e01"] },
  { id: "cn--1937--m03", track: "cn", year: 1937, yearApprox: false, dim: "military", weight: 5, title: "南京之陷与大屠杀", summary: "十二月十三日国都陷，六周之内屠杀叠起。", detail: { background: "淞沪既败，松井石根之上海派遣军沿太湖以北西进，首都之处守与撤退之序未定。", process: "1937年11月20日政府宣布移驻重庆，12月上旬日军分路趋南京，唐生智奉令守城；13日中华门、下关一带陷，守军突围者半、被俘者众；自13日起约六星期内，城内及近郊之屠杀、劫掠、奸污叠起，11月22日所设之安全区国际委员会（德国商人拉贝任主席）及各收容所分处避难之民（收容之数诸记不一）。", impact: "国都之陷与其下之暴行为抗战中最大之惨案，战后远东国际军事法庭与南京军事法庭皆就南京之屠杀为判决，谷寿夫于1947年3月被处刑；至被难总计数，法庭判决书所认有二十万人以上（不计焚尸灭迹者）之说，南京当局之调查与判决词则作三十万人以上，日方诸家统计更少，各方记载出入极大，此条但著判决文书所列之数与其异。", figures: ["唐生智","松井石根","谷寿夫","拉贝"], place: "江苏南京、下关、江东门", state: "中华民国", sources: ["《远东国际军事法庭判决书》","张宪文主编《南京大屠杀史料集》","《拉贝日记》","南京军事法庭《谷寿夫一案判决书》（1947年）"], tags: ["南京","大屠杀","安全区"] }, related: ["cn--1937--m02", "cn--1938--m02"] },
  { id: "cn--1937--e01", track: "cn", year: 1937, yearApprox: false, dim: "economy", weight: 4, title: "沿海工厂之内迁", summary: "机器溯江而入川，后方由是有工矿。", detail: { background: "上海、无锡、镇江之纺织、面粉、机器、化工诸厂当华商工业之大半，战起即在炮火之下。", process: "1937年8月以后，上海愿迁之厂相率立迁移之会，机器拆运者由招商局与民生实业之船沿江西运至武汉、宜昌，再由小轮过三峡入川，汉口、宜昌之滩岸为之一塞；至1938年春，迁入西南诸省之纱锭、机器、化工、兵工诸厂陆续复业，重庆、昆明、桂林、西安由是各有工矿区（先后内迁厂家之数，当时之册报与经济部后来之统计口径不同，多寡相差数倍）。", impact: "此为中国工业第一次有计划之西移，战时后方之军需与民用得以不竭，工业偏在沿海之局亦以是稍改；1938年以后再经湘桂之退，已迁之厂有再迁者，然途中损失已多。", figures: ["卢作孚","范旭东","侯德榜"], place: "上海、武汉、宜昌、重庆", state: "中华民国", sources: ["《中华民国史》第三卷","汪敬虞编《中国近代工业史资料》第二辑","《申报》1937—1938年原载"], tags: ["工厂内迁","民生实业","战时工业"] }, related: ["cn--1937--m02", "cn--1942--x01"] },
  { id: "cn--1937--s01", track: "cn", year: 1937, yearApprox: false, dim: "science", weight: 3, title: "钱塘江桥之成", summary: "自行设计施工之公铁两用大桥通车。", detail: { background: "沪杭、浙赣之间以钱塘江为隔，渡江惟轮渡，两路之联络久为工程界所计。", process: "1934年茅以升任钱塘江桥工程处处长，1935年4月开工，以射水法打桩、以沉箱越流沙，钢梁与混凝土墩合为双层之用；1937年9月26日铁路桥先成通车，11月17日公路桥通车，而日军已由沪杭路北上，12月23日深夜桥被自行炸毁以阻西进。", impact: "此为中国工程师自行设计、自行施工之第一座跨越大川之公铁两用桥，其射水打桩与浮运铁梁诸法后为桥工所沿用，1946年起修复、翌年复通；论近代中国桥梁工程者每以是桥为标志。", figures: ["茅以升","罗英"], place: "浙江杭州闸口、六和塔下", state: "中华民国", sources: ["罗英《中国桥梁史料》","《茅以升传》","《（民国）钱塘江桥工程处报告》"], tags: ["钱塘江桥","茅以升","桥工"] }, related: ["cn--1937--m02"] },
  { id: "cn--1938--m01", track: "cn", year: 1938, yearApprox: false, dim: "military", weight: 3, title: "台儿庄之捷", summary: "鲁南巷战逾旬，日军北退，为开战首胜。", detail: { background: "日军由津浦路与由青岛两路趋徐州，欲合于鲁南，第五战区以李宗仁任之。", process: "1938年3月中旬日军第10、第14师团分犯临沂、滕县，川军第二十二集团军守滕县三日，第一二二师师长王铭章阵亡；3月下旬至4月上旬孙连仲部守台儿庄城内，第三十一师之团与日军巷战，汤恩伯军团由侧背击入；4月上旬日军濑谷、坂本两支队北退，辎重之获为开战以来中国军最大的一次。", impact: "此为中国军在正面战场上的第一次大胜，日军不可战胜之说以是而破，武汉之空气为之一变；然5月日军大举反扑，19日徐州陷，台儿庄之胜终不能改鲁苏之局。", figures: ["李宗仁","孙连仲","王铭章","汤恩伯"], place: "山东台儿庄、滕县、临沂", state: "中华民国", sources: ["《中华民国史》第三卷","李宗仁口述《李宗仁回忆录》","日本防卫厅战史室《中国事变陆军作战史》"], tags: ["台儿庄","徐州","第五战区"] }, related: ["cn--1938--m02"] },
  { id: "cn--1938--m02", track: "cn", year: 1938, yearApprox: false, dim: "military", weight: 4, title: "武汉之会战与广州之陷", summary: "溯江三月而武汉弃，大亚湾一登而粤门塞。", detail: { background: "南京以后以武汉为军政之重心，日军以西溯长江为唯一之捷径，政府机关与工厂早已西运。", process: "1938年6月起日军由安庆溯江，马当、湖口、田家镇诸要塞以沉塞之木石与岸炮为守而先后不能支；7月起北线日军犯南浔路，瑞昌、德安相持经月；10月12日日军由广东惠阳、大亚湾登岸，21日广州陷，武汉之侧背遂裂，25、26日汉口、武昌相继入日军之手。", impact: "武汉之失使抗战由战略之守转入相持，日军战线过长、兵力不足之病并见；华南之陷又断粤汉与香港之海口，国际补给之路此后半在滇越、滇缅一线，1939年以后滇南之防皆缘此而急。", figures: ["陈诚","薛岳","蒋介石","冈村宁次"], place: "安徽安庆、江西湖口、田家镇、湖北武汉、广东广州", state: "中华民国", sources: ["日本防卫厅战史室《中国事变陆军作战史》","《中华民国史》第三卷","《毛泽东年谱（1893—1949）》"], tags: ["武汉会战","大亚湾","战略相持"] }, related: ["cn--1938--d01", "cn--1937--m03"] },
  { id: "cn--1938--d01", track: "cn", year: 1938, yearApprox: false, dim: "disaster", weight: 4, title: "花园口之决", summary: "以水当兵而河口不收，三省遂成泽国。", detail: { background: "日军由开封而南，欲合于郑州以截平汉之路，豫东之平原无险可守。", process: "1938年6月上旬（日期诸记有六日、九日两异），第一战区命部在郑州以北之黄河大堤花园口决堤放水；决口既成，黄水由贾鲁河、颍河、淮河东下，不能约束，豫、皖、苏三省沿河之地尽成泛区，河身自此由淮入江，改道者九年。", impact: "日军之追击为水所阻而平汉之南段得以暂存，然黄泛跨数十县，田庐之没与其后之数年饥、疫相仍，论战时灾荒者以是役与1942年河南之饥相连；死亡与损失之数，当时报册、赈务机关与后来调查多寡悬绝，各方记载差异较大。1946年起堵口复堤，翌年河归故道。", figures: ["蒋介石","商震","蒋在珍"], place: "河南郑州花园口、黄泛区（豫皖苏三省）", state: "中华民国", sources: ["《（民国）政府公报》1938年6月","《中华民国史》第三卷","《（民国）黄河水利委员会报告》"], tags: ["花园口","黄河改道","黄泛区"] }, related: ["cn--1938--m02", "cn--1942--d01"] },
  { id: "cn--1938--p01", track: "cn", year: 1938, yearApprox: false, dim: "politics", weight: 3, title: "汪精卫之「艳电」", summary: "响应近卫之声明，自昆明出河内。", detail: { background: "武汉既弃，主和之议在汪一派渐不能抑，12月29日日方近卫声明以善邻友好、共同防共、经济提携为词。", process: "1938年12月18日汪精卫偕其属自昆明飞河内，29日发「艳电」主张以近卫声明为据重开和议，30日各报转载；国民党中央议决开除汪之党籍并明令申讨，1939年3月河内之寓被刺，曾仲鸣死之，汪遂赴上海与日方续订条件。", impact: "此电为民国政治之一大转折，1940年3月南京之政权由此而立；主战与主和之辨以是定名，战后之附逆与汉奸之诉皆据1938、1939年往复之文书为断。", figures: ["汪精卫","蒋介石","近卫文麿","梅思平"], place: "云南昆明、越南河内、上海", state: "中华民国", sources: ["「艳电」原文（1938年12月30日各报刊载）","《中华民国史》第三卷","《（民国）政府公报》1939年"], tags: ["艳电","近卫声明","汪派"] }, related: ["cn--1940--p01", "cn--1938--i01"] },
  { id: "cn--1938--c01", track: "cn", year: 1938, yearApprox: false, dim: "culture", weight: 3, title: "中华全国文艺界抗敌协会", summary: "武汉立会，文章入伍与下乡之议由起。", detail: { background: "战起以后文艺界由沪汉港各处会于一地，各派之隔未忘而救亡之议相同，乃有统一团体之筹。", process: "1938年3月27日中华全国文艺界抗敌协会在武汉开成立会，郭沫若、茅盾、老舍、阳翰笙、夏衍诸人任理事，老舍任总务部主任主会务，提出文章入伍、文章下乡之口号；5月会刊《抗战文艺》创刊，武汉弃守后迁重庆，会中分赴延安、昆明、桂林者渐多。", impact: "此为抗战中范围最广之文艺团体，报告文学、街头剧、演唱与壁报由是盛行，通俗与宣传之并重开一代风气；1938年至1945年之文艺界分野（重庆与延安）即于此会中见其端。", figures: ["老舍","郭沫若","茅盾","阳翰笙"], place: "湖北武汉（后迁重庆）", state: "中华民国", sources: ["《抗战文艺》创刊号（1938年）","王瑶《中国新文学史稿》","《老舍全集》附年表"], tags: ["文协","抗战文艺","老舍"] }, related: ["cn--1938--a01"] },
  { id: "cn--1938--c02", track: "cn", year: 1938, yearApprox: false, dim: "culture", weight: 3, title: "《论持久战》之刊", summary: "延安言抗战之全程，以三阶段为纲。", detail: { background: "平津、淞沪既败，亡国与速胜两说并在，后方与军中皆须一定之论。", process: "1938年5月毛泽东在延安抗日战争研究会所作之讲演写成《论持久战》刊行，以敌小我大、敌退步我进步、敌寡助我多助、敌强我弱之四对照为据，定战略防御、相持、反攻三段之说，而以政治动员与游击战争为相持之具；同年经《解放》周刊与新华日报社排印，重庆、桂林各有翻印之本。", impact: "三段之说与兵民为胜利之本之语自此为中共抗战论之纲，亦为1938年以后论战局者引用最多之文本；其说与蒋方以空间换时间、持久消耗之策有同有异，两党之战略论至此各立其统。", figures: ["毛泽东"], place: "陕西延安", state: "中国共产党（陕甘宁边区）", sources: ["《毛泽东选集》第二卷所收《论持久战》（1938年5月）","《解放》周刊1938年原载","《毛泽东年谱（1893—1949）》"], tags: ["论持久战","三个阶段","政治动员"] }, related: ["cn--1938--m02", "cn--1938--c01"] },
  { id: "cn--1938--i01", track: "cn", year: 1938, yearApprox: false, dim: "institution", weight: 3, title: "国民参政会之开幕", summary: "各党各派同堂议政，抗战建国纲领通过。", detail: { background: "国防参议会之议未果，政府乃设参政会以容党外之声，参政员由遴选与聘用合成。", process: "1938年7月6日第一届会在武汉开幕，参政员二百人上下，汪精卫任议长、张伯苓副之，中共方面之毛泽东、秦邦宪、董必武、林祖涵、吴玉章皆列名；会议通过《抗战建国纲领》，设诸委员会，其后每半年一会，1938年以后多在重庆开。", impact: "此为民国以来第一次容各党派公开议政之机关，决议虽无立法之权而言论之空间以是稍开，1939年至1944年之宪政请愿皆援此为据；中共诸参政员亦借此与各方往还。", figures: ["汪精卫","张伯苓","毛泽东","董必武"], place: "湖北武汉（以后在重庆开会）", state: "中华民国", sources: ["《（民国）政府公报》1938年7月","《国民参政会资料》","《中华民国史》第三卷"], tags: ["国民参政会","抗战建国纲领","各党派"] }, related: ["cn--1946--p01"] },
  { id: "cn--1938--a01", track: "cn", year: 1938, yearApprox: false, dim: "art", weight: 3, title: "鲁迅艺术学院之立", summary: "延安设校训文艺之干，四系并立。", detail: { background: "延安既为中共之地，宣传与文艺干部之训练须有常设之机关，内来之作家、音乐家渐多。", process: "1938年春毛泽东、周恩来、林伯渠、徐特立、成仿吾、艾思奇、周扬等联名发起，4月10日在延安行成立典礼（开学日期诸记略有异），吴玉章任院长，设文学、音乐、美术、戏剧四系，分本科与短期训练班；1938年冬冼星海到延安任音乐系主任。", impact: "鲁艺为抗战中中共一系文艺干部之源，《黄河大合唱》诸作出于其教职员与学员之间，此后延安文艺之形式与1942年之讲话皆自此出；其学制与课程亦为1949年后艺术院校之一源。", figures: ["毛泽东","周恩来","吴玉章","冼星海","成仿吾"], place: "陕西延安", state: "中国共产党（陕甘宁边区）", sources: ["《新中华报》1938年原载","《毛泽东年谱（1893—1949）》","《中国共产党历史》第一卷"], tags: ["鲁艺","延安","文艺干部"] }, related: ["cn--1938--c01"] },
  { id: "cn--1939--m01", track: "cn", year: 1939, yearApprox: false, dim: "military", weight: 3, title: "诺门罕之役与北进之挫", summary: "哈拉哈河一战，苏军得势而日人气绌。", detail: { background: "满、蒙之界久有争端，1938年张鼓峰之案新定，日军在哈拉哈河东岸试苏、蒙之守备。", process: "1939年5月11日起两军在小诺门罕互犯，六、七月相持，8月20日苏军以炮兵与装甲兵团总攻，日军第23师团受创，9月初战止，16日苏日在莫斯科订停战协定；双方兵力与伤亡之数，苏、日两方之册差异极大。", impact: "此役使日本陆军之北进说一挫，对苏转为守势而南进之议由是得势，中国之正面战场少北顾之忧；1941年4月苏日中立之约与其后援华之渐辍，皆可上接于是。", figures: ["朱可夫","梅津美治郎"], place: "兴安盟诺门罕、哈拉哈河（今内蒙古新巴尔虎左旗一带）", state: "中华民国", sources: ["《新中华报》1939年原载","朱可夫《记得一生》","日本防卫厅战史室《中国事变陆军作战史》"], tags: ["诺门罕","哈拉哈河","北进南进"] }, related: ["cn--1939--p01"] },
  { id: "cn--1939--p01", track: "cn", year: 1939, yearApprox: false, dim: "politics", weight: 3, title: "欧战之起与远东之局", summary: "英法对德宣战，远东由是趋紧。", detail: { background: "中国之抗战半倚英法在亚洲之守备与海路，而欧洲之局日急。", process: "1939年9月1日德军入波兰，3日英、法对德宣战；4日日本外相有田八郎声明不以欧战牵动对华之战事，英法则以欧洲为急而有远东妥协之趋；中国宣布对欧战守局外之中立，而补给愈倚美、苏与滇越、滇缅两路。", impact: "欧战之起使日本之南进有据，1940年滇越、滇缅两路之闭与汪派「日本必胜」之说皆乘此而来；论战时中国外交由依赖英法转向依恃美苏者，以1939年9月为分段之点。", figures: ["有田八郎","王宠惠","蒋介石"], place: "重庆、伦敦、东京", state: "中华民国", sources: ["《申报》1939年9月原载","《（民国）政府公报》1939年9月","《剑桥中华民国史》"], tags: ["欧战","中立","国际补给"] }, related: ["cn--1940--x01"] },
  { id: "cn--1939--f01", track: "cn", year: 1939, yearApprox: false, dim: "figure", weight: 3, title: "白求恩在晋察冀", summary: "加拿大医生前线治伤，以感创卒于唐县。", detail: { background: "1938年初加拿大医生诺尔曼·白求恩受加拿大、美国两党之派遣来华，先后到武汉、延安，请以在前线行医。", process: "1938年秋白求恩入晋察冀边区任军医顾问，立流动医疗队、卫生材料厂与医护训练之班，1939年随军转于雁门、冀西之间；当年11月为伤员手术时创口感染，12日卒于河北唐县（所在之村与病名诸记小异）。", impact: "12月21日毛泽东作《纪念白求恩》一文，以其为国际之义与尽职之范，此文入后来之课本而传数十年；白求恩所定之手术队与训练法为边区之卫生制度留其规模，1940年代外国医务者与记者之来边区者多循其途。", figures: ["白求恩","毛泽东","聂荣臻"], place: "晋察冀边区（河北唐县、阜平）", state: "中国共产党（晋察冀边区）", sources: ["《毛泽东选集》第二卷所收《纪念白求恩》（1939年12月21日）","《白求恩传》","《新中华报》1939年11月原载"], tags: ["白求恩","晋察冀","军医"] }, related: ["cn--1940--m01"] },
  { id: "cn--1940--m01", track: "cn", year: 1940, yearApprox: false, dim: "military", weight: 4, title: "百团之役", summary: "八月破正太路，华北之交通为之一摇。", detail: { background: "1939年以后日军在华北以据点、碉堡与封锁沟行囚笼之政，正太、同浦诸路为其血脉，边区之地日蹙。", process: "1940年8月20日起八路军与晋察冀诸部同时破正太路及诸道，桥梁、隧道与井陉煤矿多被毁，继攻据点与县城；9月以后日军回击，10月关家垴之役血战数日，12月初战事乃息；参战之团数、破坏之里数与歼敌之数，中共之报与日方之记差异极大。", impact: "此役使华北之敌后由守势转为出击，日方以治安强化与烧杀之扫荡应之，1941、1942两年为边区最苦之期；而重庆方面之猜忌亦以是深，1941年1月皖南之变即其后之事。", figures: ["彭德怀","左权","刘伯承","聂荣臻"], place: "山西正太路、平定、辽县，河北平山", state: "中国共产党（晋察冀边区）", sources: ["《彭德怀自述》","《中国人民解放军战史》","《中国共产党历史》第一卷"], tags: ["百团大战","正太路","敌后破袭"] }, related: ["cn--1941--p01"] },
  { id: "cn--1940--p01", track: "cn", year: 1940, yearApprox: false, dim: "politics", weight: 3, title: "南京「国民政府」之立", summary: "三月三十日汪氏设府，与重庆相对。", detail: { background: "艳电以后，汪方与日方在上海、东京往复订条件经年，日本以收拾时局须一中国人之政权。", process: "1940年3月30日汪精卫在南京宣称为国民政府，以和平、反共、建国为词，与北平、南京两伪组织合流；11月30日与日方订《中日基本关系条约》并换文，日本承认其政权而驻兵之权不废。", impact: "自是有一南京与一重庆之对，苏南、华北之清乡与掠夺其下之粮炭人力都据此约而行；1945年以后之附逆与汉奸之诉，其据即此两年往复之文书。", figures: ["汪精卫","周佛海","梅思平","褚民谊"], place: "江苏南京", state: "汪精卫政权", sources: ["《周佛海日记》","《远东国际军事法庭判决书》","《中华民国史》第三卷"], tags: ["汪伪","南京","中日基本条约"] }, related: ["cn--1938--p01"] },
  { id: "cn--1940--x01", track: "cn", year: 1940, yearApprox: false, dim: "explore", weight: 3, title: "滇越、滇缅两路之闭", summary: "法让日军入越，英闭缅路数月。", detail: { background: "沿海口岸既尽入于敌，中国之国际补给惟恃滇越铁路出海防、滇缅公路出仰光两途。", process: "1940年6月法国败降后，日本胁迫法属印支当局封锁中越运道，9月下旬日军进据河内、海防，滇越之路遂绝；7月中旬英国应日方之请封闭滇缅公路，至10月始议重开（闭路之期有三月与数月两说），油料、五金之进口骤减。", impact: "外援一时有塞，抢购物资与限运之令并起，后方物价以是益涨；此困为1942年远征军入缅与驼峰空运之谋所自始，论战时国际交通者以1940年夏为转折。", figures: ["蒋介石","宋子文"], place: "云南昆明、河口，英属缅甸仰光", state: "中华民国", sources: ["《（民国）政府公报》1940年","《申报》1940年原载","《中华民国史》第三卷"], tags: ["滇缅公路","滇越铁路","国际补给"] }, related: ["cn--1942--x01"] },
  { id: "cn--1941--p01", track: "cn", year: 1941, yearApprox: false, dim: "politics", weight: 3, title: "皖南之变与军部之重建", summary: "北移之众受围茂林，叶挺被扣。", detail: { background: "1940年秋冬皓电、齐电以黄河以南之部队北移为责，新四军移防之路线与时日两方之议未合。", process: "1941年1月4日新四军军部及皖南部队约九千人奉令北移，自泾县云岭取道茂林、星潭；数日间受国军第三十二集团军各部拦击，血战逾旬，部队大部损失，军长叶挺被扣，副军长项英出走后为部属所杀；17日军事委员会宣布新四军「叛变」、撤销其番号，20日中共中央军委令在盐城重立军部，以陈毅代军长、刘少奇为政治委员。", impact: "此为两党合作以来最烈之冲突，统一战线之名虽存而实分；中共由是益求华中之独立经营，1942年之整风亦起于此事后，而美、英、苏之责言使重庆知内争有碍于外援。", figures: ["叶挺","项英","陈毅","刘少奇","顾祝同"], place: "安徽泾县茂林、江苏盐城", state: "中华民国", sources: ["《中共中央为皖南事变发表的命令和谈话》（1941年1月20日）","《毛泽东年谱（1893—1949）》","《中华民国史》第三卷"], tags: ["皖南事变","新四军","国共摩擦"] }, related: ["cn--1940--m01", "cn--1941--p02"] },
  { id: "cn--1941--p02", track: "cn", year: 1941, yearApprox: false, dim: "politics", weight: 3, title: "太平洋战起与对日宣战", summary: "十二月九日发布布告，并宣战德意。", detail: { background: "1941年夏以后美日续谈而美国冻结日本与中国在美之款、禁售石油，日本以南进决，中国之外援已全系于美英之向背。", process: "1941年12月8日（夏威夷为7日）日军袭珍珠港并犯南洋，美、英相继对日宣战；9日国民政府发布对日宣战布告，并宣布对德国、意大利立于战争地位，同日中共中央发表声明主组织反法西斯之国际同盟；1942年1月1日二十六国之《联合国家宣言》签于华盛顿，中国预其列。", impact: "自是中国之抗战列于世界大战之全局，1942年之美、英借款与1943年废约之新约、开罗之会皆基于是；而英方请中国之军入缅，盟邦间指挥与供给之关系新起，是年春远征军之役由是而始。", figures: ["蒋介石","林森","罗斯福","东条英机"], place: "重庆、华盛顿、珍珠港", state: "中华民国", sources: ["《（民国）政府公报》1941年12月","《联合国家宣言》（1942年1月1日）","《毛泽东年谱（1893—1949）》"], tags: ["珍珠港","对日宣战","联合国家宣言"] }, related: ["cn--1942--x01", "cn--1943--p02", "world--1941--m03"] },
  { id: "cn--1941--i01", track: "cn", year: 1941, yearApprox: false, dim: "institution", weight: 3, title: "陕甘宁边区施政纲领", summary: "三三制与人权财权定为成文之纲。", detail: { background: "边区之政向以指示与条例行之，皖南以后须有告全区之成文纲领，而根据地政权须容党外之人。", process: "1941年5月《陕甘宁边区施政纲领》公布，以三三制、保障人民之人权与财权、减租减息、发展生产与普及教育为条，定边区参议会为最高政权机关；同年11月边区第二届参议会开会，党外人士李鼎铭任政府副主席并提出精兵简政之案，12月中央以明令行之。", impact: "此纲领为民国区域政权中少见之成文施政文本，其人权、财权各条与选举之法为各根据地所取则，1949年之《共同纲领》亦存其影；三三制与精兵简政二事自此为边区之定制，并为1944年以后联合政府之主张张本。", figures: ["李鼎铭","毛泽东","谢觉哉"], place: "陕西延安", state: "中国共产党（陕甘宁边区）", sources: ["《陕甘宁边区施政纲领》（1941年5月公布）","《解放日报》1941年11月原载","《中国共产党历史》第一卷"], tags: ["施政纲领","三三制","精兵简政"] }, related: ["cn--1937--p02", "cn--1942--p01"] },
  { id: "cn--1941--s01", track: "cn", year: 1941, yearApprox: false, dim: "science", weight: 3, title: "《堆垒素数论》之成稿", summary: "昆明兵戈之地，解析数论得成书。", detail: { background: "战起后北京大学、清华大学、南开大学合为西南联合大学而迁昆明，图书之乏与空袭之警不断，而数学系之研究未辍。", process: "1941年华罗庚在昆明写成《堆垒素数论》之稿，集其关于华林问题与素数分布之诸文而为之序论；稿以战时印局之难未即付梓，1947年由苏联科学院出为俄文本（成稿与出版之年月，诸记略有先后之差）。", impact: "此为中国数学家关于解析数论之代表著作，华罗庚由是在国际数论界有声，1950年代主持数学研究所之事亦自此途出；西南联大得此成果，论战时学术之不辍者每举为证，中央研究院与诸大学之研究多在此种条件下行之。", figures: ["华罗庚","熊庆来"], place: "云南昆明（西南联合大学）", state: "中华民国", sources: ["《堆垒素数论》俄文版（1947年）","王元《华罗庚》","《西南联合大学校史》"], tags: ["解析数论","西南联大","华罗庚"] }, related: ["cn--1928--s01", "cn--1937--s01"] },
  { id: "cn--1942--p01", track: "cn", year: 1942, yearApprox: false, dim: "politics", weight: 4, title: "延安之整风", summary: "三风之整、八股之反，学统为一变。", detail: { background: "皖南以后党之内外皆须一致，而内来之学生与各地之干部于「本本」之辨未清，1941年九月政治局扩大会议已启其议。", process: "1942年2月1日毛泽东在中央党校开学典礼作《整顿党的作风》，8日在延安干部会作《反对党八股》，全党整风由是开始；4月起各地高级干部分别学习文件，6月设中央总学习委员会，1943年秋以后审干之局继起，1945年4月20日六届七中全会通过《关于若干历史问题的决议》而其事毕。", impact: "整风确立以《讲话》与决议为准之学统与话语，毛泽东之名至是为全党之指针；此事与同年之文艺座谈、精兵简政相并为延安丙戌、丁亥年间之内政三变，1949年以后之学习运动皆取其例。", figures: ["毛泽东","刘少奇","康生","任弼时"], place: "陕西延安", state: "中国共产党（陕甘宁边区）", sources: ["《毛泽东选集》第三卷所收《整顿党的作风》《反对党八股》","《中国共产党历史》第一卷","《任弼时传》"], tags: ["整风","学风","若干历史问题决议"] }, related: ["cn--1942--c01", "cn--1945--p02"] },
  { id: "cn--1942--d01", track: "cn", year: 1942, yearApprox: false, dim: "disaster", weight: 4, title: "河南之大饥荒", summary: "旱继以蝗，征粮如故，流民西入关。", detail: { background: "河南为军粮所出之地，驻军与征发并重，1942年夏雨泽愆期而蝗继发。", process: "1942年夏河南大旱，秋蝗起，1943年春饥势最盛，省府之报灾与中央之赈务往复迁延而征粮之额未减，灾民西入陕西者相属于道；省垣与重庆报章之通讯迭载其事，地方请赈之电纷上。", impact: "死亡与流出之数，当时报章、赈务机关与后来之调查自数十万至近三百万不等，诸说差异极大，此条不主一说；饥荒使豫省之战时负担与民心之变成为后来论1944年豫中之役者所屡及，亦为战时粮政与征实之制最受责言之一事。", figures: ["李培基","蒋介石"], place: "河南、陕西（流民之路）", state: "中华民国", sources: ["《（民国）政府公报》1942—1943年","《（天津）大公报》1943年通讯","《（重庆）新华日报》1942—1943年报道"], tags: ["河南饥荒","蝗灾","征粮"] }, related: ["cn--1938--d01", "cn--1944--m01"] },
  { id: "cn--1942--c01", track: "cn", year: 1942, yearApprox: false, dim: "culture", weight: 3, title: "延安文艺之座谈", summary: "五月之会言文艺为谁而作。", detail: { background: "整风既起，延安之作家与鲁艺诸系之学员于文艺与政治之关系争论不已，中央乃召集座谈。", process: "1942年5月2日至23日中共中央在延安开文艺座谈会三次，毛泽东先作引言、后作结论，以文艺为工农兵、为政治服务为纲，定普及与提高、生活与创作之别；丁玲、艾青、萧军、周立波、刘白羽诸人各有发言，1943年10月讲话全文在报上发表。", impact: "讲话为中共文艺政策之定制，秧歌、新歌剧与报告之体裁由是转向民间，1945年《白毛女》之属出于此风；1949年以后历次文艺整风与批判皆援讲话为据，而论者亦以是年为延安与重庆两系文艺分野之定。", figures: ["毛泽东","周扬","丁玲","艾青","萧军"], place: "陕西延安", state: "中国共产党（陕甘宁边区）", sources: ["《毛泽东选集》第三卷所收《在延安文艺座谈会上的讲话》","《解放日报》1943年10月原载","《中国共产党历史》第一卷"], tags: ["延安文艺座谈会","讲话","工农兵方向"] }, related: ["cn--1938--a01", "cn--1942--p01"] },
  { id: "cn--1942--x01", track: "cn", year: 1942, yearApprox: false, dim: "explore", weight: 3, title: "滇缅路断与驼峰之运", summary: "陆路既绝，越山空运自印度入昆明。", detail: { background: "1942年春日军犯缅，英方请中国之军入缅作战，第200师之众在戴安澜率下转战于缅北而多殁于途。", process: "1942年5月滇缅公路全断，中国之国际补给遂尽仰空运；中美由印度阿萨姆之汀江、卓哈尔提诸场北飞，越东喜马拉雅与高黎贡诸脊入昆明，航线之脊形似驼峰，因得此名，6月以后空运渐常，至1945年而止；所运吨数与损失之机数、员数，中美两方之册与后来诸书差异较大。", impact: "驼峰一线为抗战中最后之命脉，其油料与武器维持西南之空军与地面之补给，1943年以后之反攻训练皆倚此得活；此运又与1944—1945年中印公路之成互为表里，论战时交通之探险者以此为空前之事。", figures: ["戴安澜","陈纳德","史迪威"], place: "缅甸、印度阿萨姆、云南昆明", state: "中华民国", sources: ["《（民国）政府公报》1942年","《中国抗日战争史》","《史迪威日记》"], tags: ["驼峰航线","滇缅公路","国际空运"] }, related: ["cn--1940--x01", "cn--1944--m01"] },
  { id: "cn--1943--p01", track: "cn", year: 1943, yearApprox: false, dim: "politics", weight: 4, title: "开罗之会与宣言", summary: "三国首脑会于埃及，言东北、台、澎归还。", detail: { background: "1943年以后中国以四强之列预于盟邦之会，罗斯福主召蒋中正赴会，丘吉尔初以英方之缅甸作战为言。", process: "1943年11月22日至26日罗斯福、丘吉尔、蒋介石会于开罗，会中并议缅甸作战与战后之处置；12月1日《开罗宣言》发表，明定剥夺日本1914年以来在太平洋所夺之一切岛屿，并使日本所窃取于中国之领土如东北四省、台湾、澎湖群岛等归还中华民国，同时公布之德黑兰会议公报与宣言各别其文。", impact: "宣言以明文定台湾、澎湖之当还，1945年10月之受降与此后之处置皆援此约为据；而开罗、德黑兰两会之比附，使中国之战后地位与其不能自主之处并见，1945年2月之雅尔塔密约即成对照。", figures: ["蒋介石","罗斯福","丘吉尔","宋美龄"], place: "埃及开罗、德黑兰", state: "中华民国", sources: ["《开罗宣言》（1943年12月1日发表）","《（民国）政府公报》1943年12月","《剑桥中华民国史》"], tags: ["开罗宣言","四强","台湾归还"] }, related: ["cn--1945--p03", "cn--1943--p02"] },
  { id: "cn--1943--p02", track: "cn", year: 1943, yearApprox: false, dim: "politics", weight: 4, title: "废除治外法权之新约", summary: "一月十一日中美、中英约成，租界与法权并废。", detail: { background: "改订新约之议自1928年以来屡试而未竟，太平洋战起后美国主先弃其特权以坚同盟之名，英国继之。", process: "1943年1月11日中美、中英新约分别签于华盛顿与重庆，英、美两国放弃在华之治外法权及其在上海、厦门之专管租界，并废相关之旧约条款（中英约后附换文，于九龙租借地一节未及议）；同年3月换约生效，随后比利时、挪威等国续有声明。", impact: "不平等条约体系之两柱以明文而去，民国以来修法权、收租界之议至是收其一半；同年10月莫斯科四国宣言列中国之名，1944年敦巴顿橡树园之会、1945年旧金山之会皆由此途，而新约所留之悬案仍为1945年以后之交涉所及。", figures: ["蒋介石","罗斯福","丘吉尔"], place: "华盛顿、重庆、莫斯科", state: "中华民国", sources: ["《中华民国条约汇编》所收1943年新约","《（民国）政府公报》1943年1月","《剑桥中华民国史》"], tags: ["废除不平等条约","治外法权","租界"] }, related: ["cn--1941--p02", "cn--1945--p03"] },
  { id: "cn--1944--m01", track: "cn", year: 1944, yearApprox: false, dim: "military", weight: 4, title: "豫湘桂之役", summary: "四月渡新黄河，十二月两广之铁道通敌。", detail: { background: "1944年春日军为打通大陆交通线与毁航空基地，集战时最大之兵力于豫、湘、桂三省。", process: "1944年4月18日日军由中牟一带渡新黄河而西犯，豫中诸县相继失守，5月下旬洛阳陷，第一战区第36集团军总司令李家钰殉于陕县以东；6月中旬长沙陷，衡阳自6月23日至8月8日苦守；11月上旬桂林、柳州继失，月底日军入贵州独山，重庆震动；至12月平汉、粤汉两路与湘桂之路尽通于日军。", impact: "此役日方称一号作战，为抗战中最大之陆战，中国军失地跨四省，空军基地数处夷毁，美军之对华航空作战由是移其重心；而日军补给线过长、兵力分散之病同时俱显，1945年在华中、华南之守势由此而成。", figures: ["方先觉","李家钰","薛岳"], place: "河南郑州、洛阳，湖南长沙、衡阳，广西桂林、柳州，贵州独山", state: "中华民国", sources: ["《中华民国史》","《中国抗日战争史》","日本防卫厅战史室《中国事变陆军作战史》"], tags: ["豫湘桂战役","一号作战","独山"] }, related: ["cn--1944--m02", "cn--1942--d01"] },
  { id: "cn--1944--m02", track: "cn", year: 1944, yearApprox: false, dim: "military", weight: 3, title: "衡阳之守", summary: "一城苦守四十七日，弹尽而城陷。", detail: { background: "衡阳当粤汉、湘桂两路之交，美军航空基地在其郊，日军必欲得之。", process: "1944年6月23日日军第11军（司令官横山勇）合围衡阳，方先觉率第10军守之，工事与弹粮俱尽而巷战相续；外围诸军数度进击不能达，8月7日方先觉发最后之电，8日城陷，守凡四十七日（所部原额与死伤之数，两方之册互异）；方先觉被拘后逃归。", impact: "一城之守使日军打通之路迟一个月，其攻城之伤亡在历次之战中为巨，盟国报章以是重估中国军之战力；而城破时之降与死诸说不一，衡阳一案在后来之战史与回忆中累为辩论之端。", figures: ["方先觉","横山勇","蒋介石"], place: "湖南衡阳", state: "中华民国", sources: ["《中华民国史》","《文史资料选辑》所收衡阳作战回忆","《中国抗日战争史》"], tags: ["衡阳保卫战","第10军","四十七日"] }, related: ["cn--1944--m01"] },
  { id: "cn--1944--p01", track: "cn", year: 1944, yearApprox: false, dim: "politics", weight: 3, title: "联合政府之主张", summary: "参政会上之请，以结束一党专政为目。", detail: { background: "豫湘桂之败使各方责望政府改弦，美、英之使与国内之党派皆增其议，1944年夏重庆之国共谈判无所成。", process: "1944年9月15日中共代表林伯渠在重庆国民参政会三届三次会议上提出结束国民党一党专政、成立民主联合政府之主张，同年秋冬《解放日报》《新华日报》先后载其文，民主同盟诸党派与文化界之宣言继之；11月美国总统私人代表赫尔利到重庆，两党之谈延至1945年。", impact: "联合政府一语自此为一年间政争之中心，1945年中共七大以其为政治报告之目，1946年政治协商会议诸案其余响也；而政府之改组与一党之训政终不能合，1947年之行宪国民大会即其决裂之形。", figures: ["林伯渠","毛泽东","赫尔利","张澜"], place: "重庆、延安", state: "中华民国", sources: ["《解放日报》1944年9月原载","《毛泽东年谱（1893—1949）》","《中华民国史》"], tags: ["联合政府","国民参政会","国共谈判"] }, related: ["cn--1945--p02", "cn--1946--p01"] },
  { id: "cn--1945--p01", track: "cn", year: 1945, yearApprox: false, dim: "politics", weight: 4, title: "雅尔塔之密约", summary: "三国定对日参战之条件，而以中国之权益当人。", detail: { background: "1945年2月欧洲战事将终，罗斯福以苏联对日参战须有其条件为言，丘吉尔、斯大林会于克里米亚。", process: "1945年2月4日至11日罗斯福、丘吉尔、斯大林会于雅尔塔，11日订秘密协定，定欧洲战事结束后两三月内苏联对日宣战，其所求者为外蒙古现状之维持、库页岛南部与千岛群岛之归苏、大连港国际化与苏联之优先权益、旅顺为海军基地、中长路由苏中共同经营，且须取得中国主席之同意，而约文于签定时未告中国。", impact: "此约以中国之主权数端与人而不由中国预闻，1945年6月中苏之谈与8月14日《中苏友好同盟条约》皆循此定，外蒙古之投票与旅大、中长路之权益根据在此；苏联之对日宣战与东北之入兵亦以是约为其期。", figures: ["罗斯福","丘吉尔","斯大林","宋子文"], place: "克里米亚雅尔塔、重庆、莫斯科", state: "中华民国", sources: ["《雅尔塔协定》文本（1945年2月11日，见美国政府公布之战时文件）","《中华民国史》","《剑桥中华民国史》"], tags: ["雅尔塔密约","外蒙古","中苏条约"] }, related: ["cn--1945--p03", "cn--1943--p01"] },
  { id: "cn--1945--p02", track: "cn", year: 1945, yearApprox: false, dim: "politics", weight: 4, title: "中共之第七次全国代表大会", summary: "延安开七大，论联合政府并定党章。", detail: { background: "整风与历史之决议既成，党之全国大会距1928年之六大已十七年，敌后之根据地各遣其任事之人。", process: "1945年4月23日至6月11日中国共产党第七次全国代表大会在延安开会，毛泽东作《论联合政府》之政治报告，朱德报告军事问题，刘少奇作修改党章之报告并将毛泽东思想写入总纲；大会选中央委员会，6月19日七届一中全会举毛泽东为中央委员会、政治局与会中之主席。", impact: "七大定中共之战后主张与组织之名，其联合政府之说与重庆之国大相反，1945年8月以后之处置皆以七大所定之方针为据；代表多敌后之干员，党之重心由是自陕北移于华北、华中。", figures: ["毛泽东","刘少奇","朱德","周恩来"], place: "陕西延安杨家岭", state: "中国共产党（陕甘宁边区）", sources: ["《毛泽东选集》第三卷所收《论联合政府》","《刘少奇选集》上卷","《中国共产党历史》第一卷"], tags: ["中共七大","论联合政府","毛泽东思想"] }, related: ["cn--1944--p01", "cn--1942--p01"] },
  { id: "cn--1945--p03", track: "cn", year: 1945, yearApprox: false, dim: "politics", weight: 5, title: "日本之降与受降之仪", summary: "八月十五终战之诏下，九月九日南京签降。", detail: { background: "1945年5月德国降而太平洋之战独及日本，7月26日波茨坦之告促其无条件降。", process: "1945年8月6日、9日美军以原子弹投广岛、长崎；8月8日苏联对日宣战，9日起苏军入东北与朝鲜，毛泽东同日发表声明号召反攻；14日日本照受波茨坦诸条，15日午天皇广播终战之诏，9月2日东京湾密苏里号上签降书，9月9日中国战区受降之仪于南京行之，冈村宁次签降书；10月25日台北受降，台湾之行政重归于中国。", impact: "八年之抗战以是告终，中国以战胜与四强之名预于战后之建制（1945年6月旧金山之会与10月联合国之立即其位）；而受降之区、敌伪之武装与8、9月间两军进地之争并起，1946年之内战承此局而来。", figures: ["蒋介石","毛泽东","朱德","冈村宁次"], place: "广岛、长崎、东京湾、南京、台北", state: "中华民国", sources: ["《日本降书》（1945年9月2日）、《（民国）政府公报》1945年9月","《毛泽东选集》第四卷所收《对日寇的最后一战》","《远东国际军事法庭判决书》"], tags: ["日本投降","南京受降","台湾光复"] }, related: ["cn--1943--p01", "cn--1945--p04", "world--1945--p05"] },
  { id: "cn--1945--p04", track: "cn", year: 1945, yearApprox: false, dim: "politics", weight: 4, title: "重庆之谈判与双十之协", summary: "四十三日之谈，成政府与中共代表之纪要。", detail: { background: "终战之诏既下，受降与进兵之地两相逼，蒋三电毛泽东商之国事，美国之使在其中为介。", process: "1945年8月14日、20日、23日蒋介石三电毛泽东，28日毛泽东与周恩来、王若飞飞重庆；谈判凡四十三日，10月10日发表《政府与中共代表会谈纪要》，其承认者为避免内战、和平建国之诸原则，其未决者为解放区之政权与军队之编遣；同时上党之役（8至10月）方在山西相持。", impact: "双十之协以其未决二端而成1946年1月政治协商会议之案，亦为其不能行之根；毛泽东之赴重庆与协定之发表，为民国史上两党主帅共处一地之最后大事，1946年夏以后之局皆自此协之破而来。", figures: ["毛泽东","周恩来","蒋介石","王若飞"], place: "四川重庆", state: "中华民国", sources: ["《政府与中共代表会谈纪要》（1945年10月10日）","《毛泽东年谱（1893—1949）》","《（民国）中央日报》1945年10月原载"], tags: ["重庆谈判","双十协定","政协之基"] }, related: ["cn--1946--p01"] },
  { id: "cn--1946--p01", track: "cn", year: 1946, yearApprox: false, dim: "politics", weight: 4, title: "政治协商会议之五案", summary: "一月十日开幕，三十一日成五项之协议。", detail: { background: "双十之协所留二端须有公议之所，美国特使马歇尔来华，三国外长莫斯科之议亦主停止内争。", process: "1946年1月10日政府与中共双方之停战令发，同日政治协商会议在重庆开幕，政府、国民党、共产党、民主同盟、无党派五方之代表与会；1月31日闭会，通过关于政府组织、国民大会、和平建国纲领、军事问题、宪法草案五项协议，其要以改组国民政府、结束训政、召开国民大会与整编全国军队为目；2月25日整军之方案续成。", impact: "政协五案为1946年上半年政治之枢纽，其后之国大与宪法皆以协议之改组为前提；而两军于军队国家化与解放区政权二端终不能合，4月以后东北之战与11月之制宪国大使协议全失效。", figures: ["蒋介石","周恩来","马歇尔","张澜"], place: "四川重庆、南京", state: "中华民国", sources: ["《政治协商会议决议案》（1946年1月31日）","《周恩来选集》上卷","《中华民国史》"], tags: ["政治协商会议","五项协议","停战令"] }, related: ["cn--1945--p04", "cn--1946--i01"] },
  { id: "cn--1946--m01", track: "cn", year: 1946, yearApprox: false, dim: "military", weight: 4, title: "内战之全面", summary: "六月二十六日中原之围，和议之途遂塞。", detail: { background: "政协以后东北与华北之冲突未止，4、5月间四平之役已启其端，停战令三申而三犯。", process: "1946年6月26日中原军区之解放军由宣化店分路突围，国民党军围之于鄂豫边界，全面战事由是而始；7月至10月国军取承德与冀东、察南诸地，10月11日张家口陷，11月15日制宪国民大会开于南京，中共与之绝而和议之途塞。", impact: "此役以后停战令与政协五案俱成具文，两党之军各以其全力相持至1949年；解放区之政权、1947年之土地改革与1948年之币制崩溃皆在此三年内并见，论战后内战之起者以1946年6月底为其断。", figures: ["蒋介石","毛泽东","李先念"], place: "鄂豫边、东北四平、察哈尔张家口、南京", state: "中华民国", sources: ["《毛泽东年谱（1893—1949）》","《中国人民解放军战史》","《（民国）政府公报》1946年"], tags: ["中原突围","全面内战","张家口"] }, related: ["cn--1946--p01", "cn--1946--i01"] },
  { id: "cn--1946--i01", track: "cn", year: 1946, yearApprox: false, dim: "institution", weight: 3, title: "制宪之国民大会与宪法", summary: "十二月二十五日宪法通过，翌年元旦公布。", detail: { background: "政协之宪法草案协议以改组政府与扩大国会之权为目，而制宪之国大终由以政府单独召集。", process: "1946年11月15日国民大会在南京开会，中共与民主盟之主要分子未与，会议于12月25日通过《中华民国宪法》，以1947年1月1日公布、同年12月25日施行；宪法以五院之制为骨干，而于人民之权利义务与地方自治之条为加详（与会代表之名额与表决之情形，政府公报与他方之报所载互异）。", impact: "宪法虽成而行宪之争随之，训政之结束与多党之承认两端不能并，1948年之国民大会与总统之选即依此宪而行；中共方面以其为非法之会，两方各自之法统争以是为起点。", figures: ["蒋介石","吴稚晖","张君劢"], place: "江苏南京", state: "中华民国", sources: ["《中华民国宪法》（1946年12月25日通过、1947年1月1日公布）","《（民国）国民大会议事日录》","《中华民国史》"], tags: ["制宪国大","中华民国宪法","五院"] }, related: ["cn--1946--m01", "cn--1948--p01"] },
  { id: "cn--1947--p01", track: "cn", year: 1947, yearApprox: false, dim: "politics", weight: 4, title: "台湾之二二八事件", summary: "二月二十八日台北起衅，三月以后全岛戒备。", detail: { background: "台湾自1945年10月受降后以行政长官之制治之，1946年以来缉烟、拘人之事数与市民相抗。", process: "1947年2月27日台北查缉私烟与人众相冲突，28日罢市、请愿并攻官署，遂与军警相持，全岛继起；3月8日以后陆军自大陆续至，台北、高雄次第清乡，处理委员会之参与人士多受捕讯（拘捕、处决与失踪之数，官方之报、报章之载与后来之调查相差极大）；行政长官陈仪于4月免职，5月台湾省政府成立，魏道明任主席。", impact: "此案定台湾此后数年之政事与人心，本省、外省之隔与二二八之名为后来论台事者所恒及；1947年5月之省制与1949年以后之戒严皆与此事相接，其死失总数至今诸说互异，此条不主一说。", figures: ["陈仪","魏道明"], place: "台湾台北、高雄、台中", state: "中华民国", sources: ["《（民国）政府公报》1947年","《（上海）申报》1947年3月原载","张炎宪等《二二八研究报告》"], tags: ["二二八","台湾","清乡"] }, related: ["cn--1945--p03"] },
  { id: "cn--1947--m01", track: "cn", year: 1947, yearApprox: false, dim: "military", weight: 4, title: "大别山之路", summary: "六月渡黄河，八月出大别，三路并南。", detail: { background: "1947年3月以后中共退出延安，内线之防御须转为外线之作战，中原为其空虚之隙。", process: "1947年3月19日中共退出延安，毛泽东、周恩来、任弼时转战陕北；6月30日刘伯承、邓小平率晋冀鲁豫野战军强渡黄河，八月下旬越陇海路而抵大别山区，陈赓、谢富治一军出晋南渡河，粟裕率华东野战军三纵队十月南下，三路互为表里，是年冬中原之局已成。", impact: "解放军自内线转为外线，战争之负担由是移向国民党区域，大别山之立脚点为1948年淮海、平津之战备其地势；而新区之征粮与土改中左倾之病随之并起，1948年春中央有纠正左倾之指示。", figures: ["刘伯承","邓小平","陈赓","粟裕","毛泽东"], place: "黄河以南、大别山区（鄂豫皖边）、陕北", state: "中国共产党", sources: ["《毛泽东年谱（1893—1949）》","《中国人民解放军战史》","《刘伯承传》"], tags: ["千里跃进","大别山","外线作战"] }, related: ["cn--1947--i02", "cn--1948--m02"] },
  { id: "cn--1947--i01", track: "cn", year: 1947, yearApprox: false, dim: "institution", weight: 3, title: "内蒙古自治政府之立", summary: "五月一日王爷庙立府，以民族区域自治为纲。", detail: { background: "日本降以后内蒙诸盟旗别有军政之机关，中共在承德设内蒙古党委之属，乌兰夫主其议，而国大之代表问题与内蒙之隶属相争。", process: "1947年5月1日内蒙古自治政府在王爷庙（后改乌兰浩特）成立，乌兰夫任主席，辖东部诸盟部与蒙旗，其施政纲领以区域自治、军民并治与废除封建之特权为名；同年冬政府之建制渐与东北、华北之解放区相连，1949年12月改称内蒙古自治区。", impact: "此为中共区域中最早之省级民族自治政权，1949年《共同纲领》之民族区域自治条与1952年之实施纲要皆取其例；其辖区与察哈尔、绥远、兴安诸省之分合，1949年以后累有更置。", figures: ["乌兰夫"], place: "内蒙古王爷庙（今乌兰浩特）", state: "中国共产党（内蒙古自治区域）", sources: ["《内蒙古自治政府施政纲领》（1947年5月）","《乌兰夫传》","《中国共产党历史》第一卷"], tags: ["民族区域自治","内蒙古","乌兰夫"] }, related: ["cn--1948--i01"] },
  { id: "cn--1947--i02", track: "cn", year: 1947, yearApprox: false, dim: "institution", weight: 5, title: "中国土地法大纲之布", summary: "平分土地以定为法，封建之剥削明废。", detail: { background: "减租减息之制行于抗战之中，1946年5月4日中央以改变土地政策之指示发出，各解放区之耕者有其田已先行其事。", process: "1947年7月17日至9月13日中共中央工作委员会在河北平山举全国土地会议，刘少奇主其事，9月13日通过《中国土地法大纲》，10月10日以中共中央之名公布；大纲以废除封建性及半封建性剥削之土地制度、按乡村人口平均分配土地为目，并定没收与征收之等与人民法庭之设（分配之细目与执行之先后，1948年之指示又屡更定）。", impact: "大纲行而1947年冬以后各解放区土改大行，得地之农民与参军、支前之数相为表里，1948年战事之所以胜者论者多以土改为其本；而划阶级与斗地主之中乱打、乱斗之病随之，1948年春中央与毛泽东数令纠正左倾。", figures: ["刘少奇","毛泽东","任弼时"], place: "河北平山西柏坡、各解放区", state: "中国共产党", sources: ["《中国土地法大纲》（1947年10月10日公布）","《毛泽东选集》第四卷所收《在晋绥干部会议上的讲话》","《中国共产党历史》第一卷"], tags: ["土地改革","耕者有其田","平分土地"] }, related: ["cn--1947--m01", "cn--1948--p02"] },
  { id: "cn--1947--e01", track: "cn", year: 1947, yearApprox: false, dim: "economy", weight: 3, title: "黄金风潮与经济紧急处分", summary: "抛售黄金不能遏其涨，限价之令随下。", detail: { background: "1946年以来法币之发行岁增数十倍，沪市以黄金为藏值之所，金条之价一日数变而市人疑政府之无策。", process: "1947年2月中央银行在上海大量抛售黄金以期回笼通货而未能遏其涨，金价反跃；同月16日公布经济紧急处分方案，禁黄金之买卖、定物价工资以一月中旬之数为标准，宋子文以是月初辞行政院长之任，中央银行之总裁亦相继去职；3月以后纱布、米面之价仍并起。", impact: "黄金风潮之为效至薄，1947一年物价之比前岁增至数倍（各册指数之基期与类目不同，未可径相较），中产之家与公教薪给者半荡其储；此后政府之治物价屡以限价为术，至1948年金圆券而其术穷。", figures: ["宋子文","贝祖诒"], place: "上海、南京", state: "中华民国", sources: ["《（民国）政府公报》1947年2月","《（上海）申报》1947年原载","《（民国）中央银行月报》1947年"], tags: ["黄金风潮","紧急处分","通货膨胀"] }, related: ["cn--1948--e01"] },
  { id: "cn--1948--p01", track: "cn", year: 1948, yearApprox: false, dim: "politics", weight: 3, title: "行宪之国大与总统之选", summary: "三月二十九日开会南京，五月二十日就职。", detail: { background: "1946年制宪之国民大会既成，宪法以1947年12月25日施行，行宪之选举与动员戡乱之需同时并至。", process: "1948年3月29日行宪国民大会在南京开会，四月成选举之事，蒋介石当选总统、李宗仁副之（副总统之选经数轮而始定），5月20日两人就职；大会于4月间通过《动员戡乱时期临时条款》，国民政府由此改组为总统府制（开会之日与表决之数，公报与报馆所记微异）。", impact: "总统、副总统之选成而训政以来之政府形式一变，1949年以后之「行宪」之名与临时条款之续行皆本于此；而中共与各民盟方面不以是会为合法，1948年国内有两统并立之局。", figures: ["蒋介石","李宗仁","孙科","吴稚晖"], place: "江苏南京", state: "中华民国", sources: ["《（民国）国民大会议事录》1948年","《（民国）政府公报》1948年","《中华民国史》"], tags: ["行宪国大","总统选举","临时条款"] }, related: ["cn--1946--i01"] },
  { id: "cn--1948--p02", track: "cn", year: 1948, yearApprox: false, dim: "politics", weight: 3, title: "五一之号召与新政协之筹", summary: "四月三十日口号，请开新政治协商会议。", detail: { background: "1948年春战局之趋已见，中共须为建政定其名与其序，而民主同盟诸方面在1947年10月以后处于两方之间。", process: "1948年4月30日中共中央发布纪念五一劳动节口号，其第五条提议各民主党派、各人民团体、各社会贤达迅速召开新的政治协商会议，讨论并实现召集人民代表大会、成立民主联合政府；8月1日毛泽东复电诸方面表示赞同，李济深、何香凝、张澜、沈钧儒、陈其尤、马叙伦等先后通电响应，同年夏秋诸人由香港、上海、南洋陆续北上。", impact: "五一之号召为新中国筹建之始，其民主联合政府之说与同年南京之行宪国大并立于国内；1949年6月新政治协商会议筹备会成立于北平，同年9月之全体会议之名额与席位皆由此定。", figures: ["毛泽东","李济深","张澜","周恩来"], place: "河北平山西柏坡、香港、北平", state: "中国共产党", sources: ["《中共中央纪念五一劳动节口号》（1948年4月30日）","《毛泽东年谱（1893—1949）》","《中国共产党历史》第一卷"], tags: ["五一口号","新政协","民主联合政府"] }, related: ["cn--1949--p01", "cn--1948--i01"] },
  { id: "cn--1948--i01", track: "cn", year: 1948, yearApprox: false, dim: "institution", weight: 3, title: "华北人民政府之成", summary: "以人民代表之会举政府，部院并设。", detail: { background: "解放区之政向以边区、行署分立，1948年华北与山东、热河、绥远诸地相连，须一统一之行政机关。", process: "1948年8月华北临时人民代表大会开会，9月华北人民政府成立，董必武任主席，薄一波主华北局之责，设行政、财政、经贸、农业、公安、司法诸部与人民法院，政令行于华北与内蒙之连接地区（开会之日期与政府驻地之迁移，诸记略有出入）。", impact: "此为中共建政前最大的一次区域政权实验，其组织条例、人民代表之选举与部院之名多为1949年10月之中央人民政府所取，中央所属各部之基础半由此转来；1949年10月华北人民政府明令撤销，其工作交于中央。", figures: ["董必武","薄一波"], place: "河北平山、天津", state: "中国共产党（华北解放区）", sources: ["《华北人民政府组织大纲》（1948年）、《（华北）政府公报》","《董必武年谱》","《中国共产党历史》第一卷"], tags: ["华北人民政府","人民代表","建制"] }, related: ["cn--1949--i01", "cn--1947--i01"] },
  { id: "cn--1948--m01", track: "cn", year: 1948, yearApprox: false, dim: "military", weight: 5, title: "辽沈之役", summary: "九月至十一月，东北全境易手。", detail: { background: "1948年春东北之国军守长春、沈阳、锦州三点而路多不通，解放军已据其地之乡村与铁路之半数。", process: "1948年9月12日东北野战军南下北宁路，10月14日总攻锦州、15日城破，司令官范汉杰被俘；17日至19日长春之曾泽生部起义、郑洞国出降；10月下旬廖耀湘兵团在黑山、大虎山间被围覆没，11月2日沈阳陷，营口之部随后被歼；林彪、罗荣桓主东北野战军之任（双方兵力、伤亡与被俘之数，两方之册差异极大）。", impact: "此役后东北全境为解放军所有，其兵工、铁路与重炮皆转用于关内，双方兵力之数至此易位；1949年入关之战与关内之装备多出于是，1948年11月以后战局之速变以此为起点。", figures: ["林彪","罗荣桓","卫立煌","廖耀湘"], place: "辽宁锦州、沈阳、黑山，吉林长春", state: "中国共产党", sources: ["《毛泽东年谱（1893—1949）》","《中国人民解放军战史》","《辽沈战役亲历记》（政协文史资料）"], tags: ["辽沈战役","锦州","长春"] }, related: ["cn--1948--m02", "cn--1948--m03"] },
  { id: "cn--1948--m02", track: "cn", year: 1948, yearApprox: false, dim: "military", weight: 5, title: "淮海之役", summary: "以徐州为中心，三个兵团覆于苏北皖北。", detail: { background: "1947年冬中原既成三路之势，1948年秋徐州一带之国军与解放军之众相错于苏鲁豫皖之境。", process: "1948年11月6日华东、中原两大野战军合击徐州一带，至22日碾庄之役覆黄百韬兵团；11月23日至12月15日双堆集之役擒黄维，1949年1月6日至10日陈官庄之役覆杜聿明所部、杜被俘（双方参战、伤亡与俘虏之数，两方之册与后来诸书差异极大）；战役以徐州为中心，刘伯承、陈毅、邓小平、粟裕、谭震林任总前敌之委。", impact: "国军之美械兵团三处尽于淮海，长江以北之战线无兵可守，1949年4月之渡江由此；而支前民夫以百万计（名数诸书不同），此役之补给全在乡村之人力，论战时民众之动员者每举为最著之例。", figures: ["刘伯承","陈毅","邓小平","粟裕"], place: "江苏徐州、碾庄，安徽双堆集、陈官庄", state: "中国共产党", sources: ["《毛泽东年谱（1893—1949）》","《中国人民解放军战史》","《淮海战役亲历记》（政协文史资料）"], tags: ["淮海战役","碾庄","双堆集"] }, related: ["cn--1948--m01", "cn--1948--e01"] },
  { id: "cn--1948--m03", track: "cn", year: 1948, yearApprox: false, dim: "military", weight: 4, title: "平津之役与北平之和", summary: "新保安、天津相继破，古都受降而不战。", detail: { background: "辽沈既毕，东北之军入关，华北之国军守张家口、北平、天津、塘沽之线而退路在海上。", process: "1948年11月29日解放军围张家口，12月22日新保安之第三十五军覆，军长郭景云死之；1949年1月14日攻天津，15日城破、警备司令陈长捷被俘；同时傅作义与中共之代表议和，1月21日之约成，31日解放军入北平，守军出郊接受改编，古都及其文物未经兵火。", impact: "三大战役以是告终，长江以北无复可守之兵，北平之不战而下并为后来数处所取例；而华北之政与工业之设备全归新政权之手，1949年3月中央之入北平即在此局之后。", figures: ["傅作义","林彪","聂荣臻","罗荣桓"], place: "河北张家口、新保安、天津、北平", state: "中国共产党", sources: ["《毛泽东年谱（1893—1949）》","《聂荣臻回忆录》","《平津战役亲历记》（政协文史资料）"], tags: ["平津战役","北平和平","新保安"] }, related: ["cn--1948--m01", "cn--1949--p02"] },
  { id: "cn--1948--e01", track: "cn", year: 1948, yearApprox: false, dim: "economy", weight: 4, title: "金圆券之改与物价之溃", summary: "八月十九日发金圆券，限价不能终月。", detail: { background: "1947年黄金风潮以后钞价日蹙，预算之赤字半出于军费，沪市之物价以倍数计。", process: "1948年8月19日以财政经济紧急处分令发行金圆券，一元折法币三百万元，限期收存民间之金银、外币与外汇，并以是日之价为物价、工资之最高标准；蒋经国在上海主执行之事，扬子公司之案不能持，11月以后限价之令不能守而市价骤涨，冻结与收存之金银多为所耗（发行额与折率之细则，中央银行之册与后来诸书所载微异）。", impact: "金圆券之行及其败为民国以来币制最大的一次，1949年上半年其额累至不可计，沪、穗之市以银元与实物为市；政府之税源与军需之信用俱尽，而存券之家半荡其产，1949年以后之物价整顿皆以此役为鉴于前。", figures: ["翁文灏","王云五","蒋经国"], place: "上海、南京、广州", state: "中华民国", sources: ["《财政经济紧急处分令》（1948年8月19日）、《（民国）政府公报》","《（民国）中央银行月报》1948年","《（上海）大公报》1948年原载"], tags: ["金圆券","限价","币制改革"] }, related: ["cn--1947--e01", "cn--1948--m02"] },
];
